INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10451, 'koKR', 'Ucieczka z Cysterny Szramowijów', 'Dzięki niech będą Matce Ziemi! Kilka dni temu rozstałam się z pozostałymi. Chciałam odkryć źródło niepokoju, który odczuwały duchy wody. Poszukiwania zaprowadziły mnie do Szramowijów, gdzie odkryłam, że nagi zatruwają zapasy wody Doliny Cienistego Księżyca.$B$BNiestety, ktoś mnie zauważył i trafiłam do niewoli. Nie wiadomo, jakie okropieństwa dla mnie szykowali.$B$BMusimy opuścić to miejsce! Pomóż mi uciec, a potem odszukaj Torloka przy Ołtarzu Potępienia.$B', 'Wyprowadź Uzdrowicielkę ziemi Wildę z Cysterny Szramowijów, a potem odszukaj Uzdrowiciela ziemi Torloka przy Ołtarzu Potępienia, na zachodnich obrzeżach Ręki Gul\'dana.', 'Uzdrowicielka ziemi Wilda odprowadzona w bezpieczne miejsce', 'Wróć do Uzdrowiciela ziemi Torloka przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10458, 'koKR', 'Rozwścieczone duchy ognia i ziemi', 'Musimy spróbować naprawić krzywdy. Musimy nawiązać łączność z żywiołami tej krainy i sprawdzić, czy da się jeszcze coś zrobić!$B$BPowierzam ci totem duchów. Jeśli zabijesz rozwścieczonego ducha żywiołu w pobliżu totemu, pochłonie on duszę żywiołaka. Totem musi pochłonąć wiele dusz, zanim do mnie wrócisz.$B$BZacznij od duchów ognia i ziemi. Wróć do mnie, gdy totem będzie pełny.', 'Uzdrowiciel ziemi Torlok przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca chce, żebyś $gpochwycił:pochwyciła; za pomocą Totemu duchów 8 ziemnych dusz i 8 ognistych dusz.', '', 'Wróć do Uzdrowiciela ziemi Torloka przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', 'Pochwycenie ziemnej duszy', 'Pochwycenie ognistej duszy', '', '', 0),
(10480, 'koKR', 'Rozwścieczone duchy wody', 'Nagi Illidari przejęły kontrolę nad jedynym źródłem czystej wody w Dolinie Cienistego Księżyca.$B$BDokładnie na północ stąd znajdziesz leże nag: Szramowijów. Wokół niego leżą rozlewiska wzburzonej wody, które wyją w udręce ku ziemi. To właśnie przy nich krążą teraz rozwścieczone duchy wody.$B$BUdaj się do Szramowijów i pochwyć wodne dusze za pomocą totemu duchów. Najwięcej tych duchów znajdziesz w pobliżu Cysterny Szramowijów.$B', 'Uzdrowiciel ziemi Torlok przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca chce, żebyś $gpochwycił:pochwyciła; za pomocą Totemu duchów 5 wodnych dusz.$B', '', 'Wróć do Uzdrowiciela ziemi Torloka przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', 'Pochwycenie wodnej duszy', '', '', '', 0),
(10481, 'koKR', 'Rozwścieczone duchy powietrza', 'Wyrusz na południowy wschód, $gbohaterze:bohaterko;. Gdy ujrzysz pola olbrzymich niebieskich kryształów wystających z ziemi, będziesz u celu. Tam, na Polach Otchłanioskrzydłych, znajdziesz rozwścieczone duchy powietrza. Krążą po urwiskach i podnóżach gór otaczających pola.$B$BZniszcz ich udręczone postacie i pochwyć ich dusze za pomocą totemu duchów. Wróć do mnie, gdy to zrobisz.', 'Uzdrowiciel ziemi Torlok przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca chce, żebyś $gpochwycił:pochwyciła; za pomocą Totemu duchów 10 powietrznych dusz.', '', 'Wróć do Uzdrowiciela ziemi Torloka przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', 'Pochwycenie powietrznej duszy', '', '', '', 0),
(10513, 'koKR', 'Oronok Rozdarte Serce', 'Nie wiem, jak zdobyć zaklęcie, o którym wspominały duchy, $N. Prawdę mówiąc, nie wiem nawet, od czego zacząć takie poszukiwania.$B$B<Torlok zapatruje się w dal, pogrążony w myślach.>$B$BHmm... Szansa jest niewielka, ale może to nasza jedyna nadzieja. Widywałem już w okolicy pewnego orka. Raz nawet krótko z nim rozmawiałem. To pustelnik, który twierdzi, że mieszka nad Cysterną Szramowijów, na północnym wschodzie. Odszukaj tego orka – Oronoka Rozdartego Serca.$B$BJak mówiłem, szansa jest niewielka.', 'Odszukaj Oronoka Rozdartego Serca na Strzaskanej Półce, na północ od Cysterny Szramowijów.$B', '', '', '', '', '', '', 0),
(10514, 'koKR', 'Kim ja już nie byłem...', 'Byłem już wieloma rzeczami, nieznajomy, ale to, kim byłem kiedyś, nie ma znaczenia. Liczy się to, kim jestem teraz, a teraz jestem rolnikiem.$B$BUżywam wytresowanych spaczonych dzików, żeby wykopywać bulwy z twardej ziemi Strzaskanych Równin. Ostatnio jednak obdzieracze z gniazda na północnym wschodzie atakują moje zwierzęta i nie mogę zbierać bulw.$B$BPójdziesz na północ stąd i nazbierasz dla mnie bulw? Stań na kopcu bulw i użyj tego gwizdka, a przybiegnie dzik i jedną wykopie!', 'Oronok Rozdarte Serce z Farmy Oronoka w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; 10 bulw z Księżyca Cienia na Strzaskanych Równinach.$B$BChce też, żebyś po wszystkim $goddał:oddała; mu Gwizdek na dzika Oronoka.', '', 'Wróć do Oronoka Rozdartego Serca na Farmę Oronoka w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10515, 'koKR', 'Nauczka', 'Musimy pokazać tym obdzieraczom, co się dzieje, kiedy ktoś wchodzi w drogę interesom Oronoka!$B$BWróć na Strzaskane Równiny i zniszcz każde jajo obdzieraczy, jakie zobaczysz. Będą głęboko na ich terytorium, więc miej się na baczności.', 'Oronok Rozdarte Serce z Farmy Oronoka w Dolinie Cienistego Księżyca chce, żebyś $gzniszczył:zniszczyła; 10 jaj wygłodniałych obdzieraczy na Strzaskanych Równinach.', '', 'Wróć do Oronoka Rozdartego Serca na Farmę Oronoka w Dolinie Cienistego Księżyca.', 'Zniszczone jaja wygłodniałych obdzieraczy', '', '', '', 0),
(10519, 'koKR', 'Szyfr Potępienia – prawda i historia', '<Oronok prostuje się i staje wyprostowany na całą swoją wysokość.>$B$BMusiałem mieć pewność, $N. A żeby ją mieć, musiałem cię sprawdzić. Wybacz tę małą maskaradę. Jestem takim samym rolnikiem, jak ty $gkobietą:mężczyzną;. Czyli żadnym.$B$BJeśli masz odzyskać Szyfr Potępienia, musisz wysłuchać tego, co mam ci do powiedzenia. Gdy będziesz $ggotów:gotowa;, daj znać, a opowiem ci tę historię.', 'Oronok Rozdarte Serce z Farmy Oronoka w Dolinie Cienistego Księżyca chce, żebyś $gwysłuchał:wysłuchała; jego opowieści. Porozmawiaj z Oronokiem, żeby zaczął ją snuć.', 'Szyfr Potępienia – historia i prawda', 'Wróć do Oronoka Rozdartego Serca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10521, 'koKR', 'Grom\'tor, syn Oronoka', 'Mój pierworodny, Grom\'tor, wyruszył przeszukać Cypel Szramowijów – dokładnie na południowy zachód stąd.$B$BTo wojownik w rodzinie – porywczy i żądny krwi... Cechy odziedziczone po matce. Szukaj na obrzeżach Cypla Szramowijów. Jeśli zobaczysz trupy nag, Grom\'tor na pewno jest niedaleko.$B$BGdy go znajdziesz, powiedz mu: „Przelewamy krew w słusznej sprawie”. Da mu to znać, że jesteś $gprzyjacielem:przyjaciółką; Rozdartego Serca, i uchroni cię przed przedwczesną śmiercią.', 'Odnajdź Grom\'tora, syna Oronoka, na Cyplu Szramowijów w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10522, 'koKR', 'Szyfr Potępienia – szarża Grom\'tora', 'Ten nagi śmieć to szósty, którego dziś przesłuchałem. Ma fikuśną zbroję, więc uznałem, że coś wie. Tamci byli do niczego.$B$B<Grom\'tor wskazuje na trupy nag wokół siebie.>$B$BWystarczyło, że raz go stłukłem, i wszystko mi powiedział.$B$BPierwsza część szyfru jest ukryta w skrzyni nag na Cyplu Szramowijów albo w Cysternie Szramowijów, na wschód stąd. Mówi, że klucze noszą przy sobie nagi. Zabijaj je, zabieraj im klucze i otwieraj nimi skrzynie Szramowijów. Wróć do mnie, gdy znajdziesz szyfr.', 'Grom\'tor, syn Oronoka, na Cyplu Szramowijów w Dolinie Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; Pierwszy fragment Szyfru Potępienia.', '', 'Wróć do Grom\'tora, syna Oronoka, na Cypel Szramowijów w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10523, 'koKR', 'Szyfr Potępienia – odzyskany pierwszy fragment', '<Grom\'tor zawija dokumenty i wkłada je do kasetki.>$B$BZanieś tę kasetkę ojcu. Czeka na ciebie na farmie, na północny wschód stąd.$B$BPowiedz mu, że niedługo wrócę do domu. Jak tylko skończę się zabawiać...', 'Zanieś Kasetkę Grom\'tora Oronokowi Rozdartemu Sercu na Farmę Oronoka w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10527, 'koKR', 'Ar\'tor, syn Oronoka', 'Mój najmłodszy syn, Ar\'tor, wyruszył przeszukać Punkt Illidari – daleko na południowy zachód, wciśnięty między Warownię Legionu a Warownię Dzikiego Młota.$B$BAr\'tor jest łowcą o niezwykłych umiejętnościach i znakomitym tropicielem, ale obawiam się, że tym razem porwał się z motyką na słońce. Punkt Illidari to poligon demonów Illidana. To demony, które opuściły Płonący Legion, by przyłączyć się do Zdrajcy!$B$BUdaj się do Punktu Illidari i odnajdź Ar\'tora, $N.', 'Odnajdź Ar\'tora, syna Oronoka, w Punkcie Illidari w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10528, 'koKR', 'Demoniczne kryształowe więzienia', 'Oglądając miejsce, dostrzegasz, że Ar\'tora utrzymują w miejscu promienie energii bijące z kryształów unoszących się wokół runy. Choćbyś nie wiem jak się $gstarał:starała;, nie da się go ruszyć.$B$BZauważasz, że kryształy mają u podstawy puste gniazdo – może na klucz. Wygląda też na to, że sukkuby co jakiś czas odprawiają tu jakiś rytuał.$B$BPrzeszukaj Punkt Illidari w poszukiwaniu ich przywódczyni. Może to ona ma klucz do uwolnienia Ar\'tora.', 'Odszukaj i zabij Panią bólu Gabrissę w Punkcie Illidari, a potem wróć z Kryształowym kluczem do zwłok Ar\'tora, syna Oronoka.', '', 'Wróć do Ar\'tora, syna Oronoka, w Punkcie Illidari w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10537, 'koKR', 'Lohn\'goron, łuk Rozdartego Serca', 'To znak, $N. Nawet śmierć mnie nie powstrzyma. Odzyskanie części Szyfru Potępienia to moje przeznaczenie. Z twoją pomocą to przeznaczenie się wypełni.$B$BZanim jednak wyruszymy w tę drogę, muszę odzyskać mój długi łuk, Lohn\'goron. To rodowa pamiątka, przekazywana od pokoleń z rąk do rąk w rodzie Rozdartego Serca.$B$BInstynkt mi mówi, że ukradł go z moich zwłok jakiś demon. Zabijaj tutejsze demony, aż znajdziesz mój łuk.', 'Duch Ar\'tora w Punkcie Illidari w Dolinie Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; od tutejszych demonów Lohn\'goron, łuk Rozdartego Serca.', '', 'Wróć do Ducha Ar\'tora w Punkcie Illidari w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10540, 'koKR', 'Szyfr Potępienia – szarża Ar\'tora', 'Nareszcie jesteśmy gotowi. Obdarzę cię cząstką mojego ducha, $gbohaterze:bohaterko;. Będzie cię strzegł i pomagał ci w walce ze złem.$B$BPotem musisz się udać na południe, na tyły Punktu Illidari. W eterze ukrywa się tam plugawa istota zwana Veneratusem Mnogim. Mój łowca duchów wywabi go, gdy będzie w pobliżu.$B$BZniszcz Veneratusa i zabierz z jego zwłok drugą część Szyfru Potępienia.', 'Duch Ar\'tora w Punkcie Illidari w Dolinie Cienistego Księżyca chce, żebyś $godebrał:odebrała; Veneratusowi Mnogiemu Drugi fragment Szyfru Potępienia.$B$BIstoty zaatakowane lub zranione przez Łowcę duchów nie dadzą łupu ani doświadczenia.', '', 'Wróć do Ducha Ar\'tora w Punkcie Illidari w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10541, 'koKR', 'Szyfr Potępienia – odzyskany drugi fragment', 'Dziękuję ci, $gbohaterze:bohaterko;. Gdyby nie ty, mój duch na zawsze pozostałby w tym przeklętym miejscu.$B$B<Ar\'tor wręcza ci widmową kasetkę.>$B$BWeź ją i zanieś mojemu ojcu na farmę, daleko na północny wschód, nad Cysterną Szramowijów... W środku są Lohn\'goron i druga część szyfru.$B$BZasmuci go wieść o mojej śmierci. Obiecaj mi, że zapewnisz go, iż umarłem jako wolna dusza. Powiedz mu, że widzę tereny łowieckie i że są wspaniałe. Powiedz mu, że tam na niego czekam...', 'Zanieś Kasetkę Ar\'tora Oronokowi Rozdartemu Sercu na Farmę Oronoka w Dolinie Cienistego Księżyca.$B', '', '', '', '', '', '', 0),
(10546, 'koKR', 'Borak, syn Oronoka', 'Gdy Ar\'tor polował, a Grom\'tor walczył, Borak się uczył. W końcu został uczonym i wyruszył w dzikie ostępy Draenoru. Kilka lat temu wrócił do domu jako zupełnie inny ork.$B$BWyostrzone zmysły i bystry umysł wykuły z niego cichego zabójcę.$B$BTeraz, pewny siebie i potężny, podjął się odzyskania najpilniej strzeżonej części szyfru.$B$BOdnajdź Boraka, który ukrywa się w pobliżu Punktu Zaćmienia, daleko na południu. Obserwuje wszystko z cienia pod mostem.', 'Odnajdź Boraka, syna Oronoka, w pobliżu Punktu Zaćmienia w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10562, 'koKR', 'Oblężenie!', 'Nie trać czujności. Płonący Legion atakuje nas bez przerwy.$B$BZe swojej bazy w Warowni Legionu na północnym zachodzie demony zsyłają na nas nieustanny deszcz piekielników. Gdy tylko zdążymy ich pozabijać, uderzają nowe meteory i zaczyna się kolejna fala ataków.$B$BMoi ludzie są wyczerpani i ledwo trzymają się na nogach. Nie wiem, jak długo jeszcze wytrzymają. Proszę cię, $N, wesprzyj naszą obronę. Stań w szeregu i powstrzymaj natarcie piekielników!', 'Dowódca skrzydła Nuainn, przed Warownią Dzikiego Młota, chce, żebyś $gzabił:zabiła; 10 atakujących piekielników.', '', 'Wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10563, 'koKR', 'Do Warowni Legionu', 'Warownia Legionu to twierdza niemal nie do zdobycia i szczerze mówiąc, nie mogę przeznaczyć sił na szturm. Nasze nadzieje spoczywają na tobie, $N.$B$BZ tych skąpych informacji, które udało nam się zebrać, wynika, że Legion gromadzi i przygotowuje w warowni swoje piekielniki. Dzięki przebraniu, które ci dam, musisz zakraść się do Warowni Legionu i poznać ich plany. Największą szansę masz, jeśli przechwycisz albo podsłuchasz rozmowę ich dowódców. Powodzenia, $N.', 'Dostań się do Warowni Legionu i odnajdź Urządzenie łączności Legionu. Stojąc przy urządzeniu, użyj przebrania i poznaj plany Legionu. Po wykonaniu misji wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota.', '', 'Wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', 'Poznanie planów Legionu', '', 0),
(10564, 'koKR', 'Wysadź piekielniki!', 'Urządzenie, które złożyliśmy, nie wygra żadnego konkursu piękności, ale powinno zniszczyć piekielniki zgromadzone w Warowni Legionu. Sądząc po tym, co energia rdzenia zasilającego grabieżcy Spaczenia zrobiła z Cuchnącą Sadzawką, drzemie w nim spora siła wybuchu.$B$BJeśli zdetonujesz urządzenie na środku zielonego glifu w warowni, powinno dosięgnąć wszystkich piekielników.', 'Użyj Spaczonej bomby, stojąc na zielonym glifie w Warowni Legionu, a potem zamelduj się u Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota.', '', 'Wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', 'Zniszczenie piekielników Warowni Legionu', '', '', 0),
(10568, 'koKR', 'Tablice Baa\'ri', 'Przed laty okryty złą sławą czarnoksiężnik Gul\'dan wydźwignął wulkan pośrodku Cienistego Księżyca. Draenejska wioska Baa\'ri, na południowym zachodzie, została pogrzebana pod lawą wraz z mieszkańcami i przedmiotami o znaczeniu religijnym.$B$BZdradzieckie plemię Złamanych, zwane Popielnymi Językami, dostało od Illidana rozkaz odkopania tego terenu. Musimy wykorzystać tę okazję i odzyskać Tablice Baa\'ri – starożytny tekst, który podobno skrywa tajemnice Świątyni Karaboru, znanej dziś jako Czarna Świątynia.', 'Anachoretka Ceyla przy Ołtarzu Sha\'tar chce, żebyś $gzebrał:zebrała; 12 fragmentów tablic Baa\'ri – z ziemi i od robotników Popielnych Języków w Ruinach Baa\'ri.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Anachoretki Ceyli przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10569, 'koKR', 'Wrak Sketh\'lon', 'Nasi zwiadowcy przynoszą niepokojące wieści ze zrujnowanych obozowisk arakkoa w okolicy.$B$BDuchy potężnych magów arakkoa władają mocami, o które nigdy byśmy ich nie podejrzewali. Wygląda na to, że się organizują, jakby przygotowywali się do czegoś, ale nasza wiedza jest ograniczona. Nie możemy sobie pozwolić na niewiedzę!$B$BUdaj się na północ, do Wraku Sketh\'lon, na północny zachód od Kuźni Śmierci, i poszukaj śladów ich zamiarów.', 'Zdobądź od arakkoa z Mrocznego Konklawe przy Wraku Sketh\'lon strony 1, 2 i 3 dziennika dowódcy Sketh\'lon i przynieś je Jeźdźcowi gryfa Kieranowi.', '', 'Wróć do Jeźdźca gryfa Kierana w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10570, 'koKR', 'Pułapka na ostoholika', '<Borak bierze od ciebie pęk krwawego ostu i podsuwa go sobie pod nos.>$B$BOstry zapach...$B$BA teraz weź ten pęk i połóż go na drugim końcu mostu. Gdy posłaniec będzie robił swój codzienny obchód, nie zdoła się powstrzymać i go podniesie – bez ochroniarza. Widzisz, krwawe elfy gardzą uzależnionymi od krwawego ostu. Gdyby któryś z jego towarzyszy się dowiedział...$B$BWystarczy, że zaczaisz się i poczekasz, aż odprawi ochroniarza. Gdy zostanie sam, uderz! Zabij go i zabierz pismo.', 'Borak, syn Oronoka, przy moście w pobliżu Punktu Zaćmienia w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; Pismo Burzogniewnego.', '', 'Wróć do Boraka, syna Oronoka, w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10571, 'koKR', 'Oronu Starszy', 'Według tablic w Baa\'ri przechowywano artefakt zwany Medalionem Karaboru. Otrzymywali je tylko najwyżsi rangą kapłani draenei, gdyż dawały swobodny wstęp do Świątyni Karaboru.$B$BMusimy się dowiedzieć, czy Popielne Języki odzyskały już medalion z Baa\'ri. Jego moc byłaby ogromną pomocą w walce z Illidanem.$B$BZastępca Akamy w Baa\'ri, Oronu Starszy, codziennie otrzymuje od niego pisemne rozkazy. Zdobądź je i przynieś mi.', 'Anachoretka Ceyla przy Ołtarzu Sha\'tar chce, żebyś $gzdobył:zdobyła; Rozkazy od Akamy od Oronu Starszego w Ruinach Baa\'ri.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Anachoretki Ceyli przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10572, 'koKR', 'Budowa bomby', 'Nie możemy pozwolić, by Legion w marszu na Czarną Świątynię zrealizował plan zniszczenia Warowni Dzikiego Młota.$B$BJest tylko jeden sposób, by ich powstrzymać, $N. Musisz przygotować ładunek wybuchowy dość duży, by zniszczyć cały zapas piekielników Legionu w warowni.$B$BW Cuchnącej Sadzawce przy Warowni Legionu leży stary rdzeń zasilający grabieżcy Spaczenia, który może posłużyć za podstawę urządzenia. Przeszukaj inne szczątki w pobliżu grabieżcy, a może znajdziesz opancerzenie, z którego zrobimy obudowę.', 'Zdobądź Rdzeń zasilający grabieżcy Spaczenia i Płytę pancerną grabieżcy Spaczenia i przynieś je Dowódcy skrzydła Nuainnowi w Warowni Dzikiego Młota.', '', 'Wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10573, 'koKR', 'Kuźnia Śmierci', 'Z tego, co $godkryłeś:odkryłaś; w Warowni Legionu, wiemy, że sprzymierzona z Legionem Rada Cieni wytwarza piekielniki w Kuźni Śmierci. Wysłałem niewielki oddział zwiadowczy, żeby miał oko na okolicę, ale nie są w stanie zrobić wszystkiego, czego potrzebujemy.$B$BJeśli Kuźnia Śmierci będzie mogła działać bez przeszkód, odbudują zapas piekielników, który $gzniszczyłeś:zniszczyłaś; w Warowni Legionu.$B$BChcę, żebyś $gspotkał:spotkała; się z Burzycielem Ewanem Dzikim Skrzydłem przy Wieży Kuźni Śmierci, na północnym zachodzie, skąd widać całą Kuźnię Śmierci.', 'Zamelduj się u Burzyciela Ewana Dzikiego Skrzydła przy Wieży Kuźni Śmierci.', '', '', '', '', '', '', 0),
(10574, 'koKR', 'Plugawiciele Popielnych Języków', 'Według listu Akamy wydobyto cztery fragmenty medalionu i przekazano je Plugawicielom Popielnych Języków. Ci straszliwi Złamani byli niegdyś potężnymi szamanami, a dziś kalają te same żywioły, które kiedyś czcili.$B$BHaaluma, Plugawiciela powietrza, znajdziesz na Przełęczy Otchłanioskrzydłych. Eykenena i Uylaru, Plugawicieli ziemi i ognia, widziano ostatnio w Spaczonych Dołach przy Ręce Gul\'dana. Lakaan, Plugawiciel wody, podobno przebywa w pobliżu Cypla Szramowijów.$B$BOdnajdź ich i zdobądź fragmenty medalionu.', 'Zdobądź cztery fragmenty medalionu od Haaluma, Eykenena, Lakaana i Uylaru i wróć do Anachoretki Ceyli przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Anachoretki Ceyli przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10575, 'koKR', 'Klatka Strażniczki', 'Fragmenty, które $gzdobyłeś:zdobyłaś;, to tylko połowa medalionu. Drugą połowę musiał zatrzymać przywódca Popielnych Języków, Akama.$B$BBoję się cię o to prosić, bo Akama jest zarówno zły, jak i przebiegły.$B$BPodobno on i Zaprzysiężeni Popielnych Języków – najpodlejsi i najbardziej brutalni z plemienia – prowadzą w Klatce Strażniczki salę tortur.$B$BChcę, żebyś $godnalazł:odnalazła; to przeklęte więzienie i $gustalił:ustaliła;, gdzie przebywa Akama. Jego zastępcą na miejscu jest Złamany imieniem Sanoru – przesłuchaj go, jeśli będzie trzeba.', 'Anachoretka Ceyla chce, żebyś $gwszedł:weszła; do Klatki Strażniczki, na południe od Ruin Baa\'ri, i $gwypytał:wypytała; Sanoru o miejsce pobytu Akamy.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10576, 'koKR', 'Przetasowanie w Cienistym Księżycu', '<Borak mierzy cię wzrokiem od stóp do głów.>$B$BTo będzie trudne, ale chyba dam radę.$B$BMogę cię przebrać za jednego z tych krwawych elfów Illidari, $N. Najpierw jednak potrzebuję kilku części ich zbroi. Zbroja musi być koniecznie czysta. Żadnych plam krwi! Nie chcemy wzbudzać podejrzeń.$B$BPrzynieś mi ekwipunek, a resztą przebrania zajmę się sam.$B$BGdy przebranie będzie gotowe, dostarczysz wiadomość Wielkiemu dowódcy – osobiście.', 'Borak, syn Oronoka, przy moście w pobliżu Punktu Zaćmienia w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; 6 części Zbroi Zaćmienia.$B', '', 'Wróć do Boraka, syna Oronoka, w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10577, 'koKR', 'Czego Illidan chce, to Illidan dostaje...', 'Weź to przebranie i wejdź do Punktu Zaćmienia. W środku użyj przebrania, żeby się zamaskować. Krwawe elfy Zaćmienia nie przejrzą przebrania, dzięki czemu bezpiecznie dotrzesz do Wielkiego dowódcy Ruuska.$B$BGdy znajdziesz Ruuska, powiedz mu, dokąd ma następnie przenieść szyfr. Będziesz $gmusiał:musiała; zagrać, ile sił, $N. Udawaj, że jesteś jego $gprzełożonym:przełożoną; i przynosisz wiadomość od jego pana. To powinno wystarczyć!$B$BA, i uważaj na smocze jastrzębie, bo one przejrzą przebranie.', 'Borak, syn Oronoka, przy moście w pobliżu Punktu Zaćmienia w Dolinie Cienistego Księżyca chce, żebyś $gprzekazał:przekazała; wiadomość Illidana Wielkiemu dowódcy Ruuskowi w Punkcie Zaćmienia.', 'Wiadomość Illidana dostarczona', 'Wróć do Boraka, syna Oronoka, w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10578, 'koKR', 'Szyfr Potępienia – szarża Boraka', 'Ten fragment szyfru nigdy nie trafi do Zuluheda. Urządzisz zasadzkę na Ruula Zaciemniacza i jego transport, zanim zdąży go dostarczyć.$B$BForteca Smoczych Paszcz leży dokładnie na wschód stąd, po drugiej stronie Pól Otchłanioskrzydłych. Ruula znajdziesz gdzieś między Fortecą Smoczych Paszcz a Sanktuarium Gwiazd. Uderz mocno i szybko! I, $N, z tego, co słyszę, ten Ruul będzie twardym przeciwnikiem. Miej się na baczności.$B$BJeśli ci się uda, przynieś mi szyfr.$B', 'Borak, syn Oronoka, przy moście w pobliżu Punktu Zaćmienia w Dolinie Cienistego Księżyca chce, żebyś $godebrał:odebrała; Ruulowi Zaciemniaczowi Trzeci fragment Szyfru Potępienia.$B$BTa misja wymaga grupy.', '', 'Wróć do Boraka, syna Oronoka, w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10579, 'koKR', 'Szyfr Potępienia – odzyskany trzeci fragment', 'Zanieś tę skrzynkę mojemu ojcu. Wciąż mieszka na Farmie Oronoka, daleko na północy, nad Cysterną Szramowijów. Gdy wszystkie trzy fragmenty zostaną złożone, starożytne słowa znów będą znane.$B$BPowodzenia, $N. Powiedz ojcu, że niedługo wrócę do domu.', 'Zanieś Kasetkę Boraka Oronokowi Rozdartemu Sercu na Farmę Oronoka w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10582, 'koKR', 'Sługusy Rady Cieni', '<Ewan słucha twojej relacji z wydarzeń w Warowni Legionu i kiwa głową.>$B$BTo stawia nasze obserwacje w innym świetle. Widzieliśmy przelotnie, jak wystrzeliwują piekielniki w stronę warowni, ale niczego więcej nie udało nam się ustalić.$B$BRada Cieni zamknęła Kuźnię Śmierci szczelniej niż nową beczkę piwa Gromowarów. Najpierw musisz porozbijać parę łbów, żeby się tam dostać i powęszyć. Zacznij od wybicia sług Rady Cieni, którzy strzegą wejścia do Kuźni Śmierci!', 'Burzyciel Ewan Dzikie Skrzydło przy Wieży Kuźni Śmierci chce, żebyś $gzabił:zabiła; 10 strażników z Kuźni Śmierci i 5 przywoływaczy z Kuźni Śmierci.', '', 'Wróć do Burzyciela Ewana Dzikiego Skrzydła przy Wieży Kuźni Śmierci w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10583, 'koKR', 'Los Flanisa', 'Dowódca skrzydła Nuainn wysłał tu początkowo trzech z nas, żebyśmy mieli oko na Kuźnię Śmierci i zbierali informacje. Flanis Chyże Skrzydło zgłosił się na ochotnika, żeby spróbować przeniknąć do Kuźni Śmierci, ale od kilku dni nie mamy od niego wieści.$B$BObawiam się najgorszego, $N. Flanis to wprawny zwiadowca, ale jeśli porwał się na coś ponad siły, nie mamy jak się o tym dowiedzieć. Przeszukaj Kuźnię Śmierci, odnajdź go i przynieś wszelkie informacje i przedmioty, które mógł zebrać.', 'Burzyciel Ewan Dzikie Skrzydło przy Wieży Kuźni Śmierci chce, żebyś $gprzeszukał:przeszukała; Kuźnię Śmierci w poszukiwaniu Flanisa Chyżego Skrzydła i $godzyskał:odzyskała; Plecak Flanisa.', '', 'Wróć do Burzyciela Ewana Dzikiego Skrzydła przy Wieży Kuźni Śmierci w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10585, 'koKR', 'Komnata przywołań', 'Żeby Rada Cieni mogła budować piekielniki tak szybko, jak są zużywane, musi mieć miejsce przeznaczone do przywoływania splugawionych żywiołaków, które służą tym istotom za dusze.$B$BKomnata przywołań znajduje się zapewne pod ziemią, w pobliżu sadzawki skażonej wody albo lawy. Odnajdź komnatę przywołań w Kuźni Śmierci i znajdź sposób, żeby przerwać ich rytuał przywołania. Mo\'argowie, którzy wytwarzają piekielniki, mogą mieć przy sobie narzędzie, które pomoże zakłócić magię przywoływacza.', 'Zdobądź Przemieszczacz żywiołaków od kowala z Kuźni Śmierci albo majsterkowicza z Kuźni Śmierci i użyj go, by zakłócić rytuał w komnacie przywołań. Po wykonaniu zadania zamelduj się u Burzyciela Ewana Dzikiego Skrzydła przy Wieży Kuźni Śmierci.', '', 'Wróć do Burzyciela Ewana Dzikiego Skrzydła przy Wieży Kuźni Śmierci w Dolinie Cienistego Księżyca.', 'Przerwanie rytuału przywołania piekielników', '', '', '', 0),
(10586, 'koKR', 'Pokonaj Siewcę wojny!', 'Poczyniliśmy spore postępy w walce z działaniami Rady Cieni w Kuźni Śmierci, ale jeśli mamy naprawdę zatriumfować, musimy pokonać tamtejszego nadzorcę Legionu.$B$BW plecaku Flanisa znalazłem klucz. Jestem pewien, że przyda się w wytropieniu tego Siewcy wojny Razuuna, którego $gwidziałeś:widziałaś; w Warowni Legionu.$B$BGdy już wytropisz Siewcę wojny Razuuna i się z nim rozprawisz, zamelduj się bezpośrednio u Dowódcy skrzydła Nuainna. Będzie chciał się dowiedzieć od razu!', 'Pokonaj Siewcę wojny Razuuna, zdobądź Rozkazy Razuuna i zamelduj się u Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota.', '', 'Wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10587, 'koKR', 'Plac Ćwiczeń Karaboru', 'Nasi zwiadowcy donoszą o masowym napływie rekrutów – krwawych elfów ze Słonecznej Furii – zmierzających do Ruin Karaboru. Zwykle oznaczałoby to zagrożenie czysto militarne, ale sądzimy, że dzieje się coś jeszcze.$B$BOpisy ich strojów i stylu walki podejrzanie przypominają samego Illidana. Nie chcę bić na alarm bez powodu, dlatego proszę cię, żebyś się tam $gudał:udała; i $gprzyniósł:przyniosła; mi ich broń. Wtedy ustalimy, czy moje obawy są bezpodstawne.', 'Egzarcha Onaala przy Ołtarzu Sha\'tar chce, żebyś $gzdobył:zdobyła; 8 glewii Słonecznej Furii od suplikantów łowców demonów i nowicjuszy łowców demonów w Ruinach Karaboru, na południowy wschód od Ołtarza Sha\'tar.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Egzarchy Onaali przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10588, 'koKR', 'Szyfr Potępienia', 'Ile razy użyto tego zaklęcia w historii naszych światów? Jego niszczycielska moc bez wątpienia nie ma sobie równych.$B$BTeraz musisz wziąć szyfr, znów cały, i odczytać go przy Ołtarzu Potępienia – tam, gdzie stoi pamięć Gul\'dana.$B$BGdy słowa zostaną wypowiedziane, ujrzysz wspomnienia wyryte w tej ziemi. Nie ustępuj pola i czekaj na przybycie Cyrukha.$B$BMusisz zwyciężyć, $N. Ta kraina nie zniesie kolejnego rozbicia.', 'Użyj Szyfru Potępienia przy Ołtarzu Potępienia, by przywołać Cyrukha Władcę Ognia.$B$BZniszcz Cyrukha Władcę Ognia, a potem porozmawiaj z Uzdrowicielem ziemi Torlokiem, który również przebywa przy Ołtarzu Potępienia.', '', 'Wróć do Uzdrowiciela ziemi Torloka przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10589, 'koKR', 'Zdobycie dostępu', 'Według rozkazów Razuuna ogromny punkt zborny piekielników nazywa się Punkt Inwazji: Kataklizm i jest ukryty w północnych górach. Można się tam dostać tylko przez teleporter w Warowni Legionu.$B$BNiektórzy członkowie zastępów Legionu noszą urządzenia, które pozwalają uruchamiać teleportery. Musisz zdobyć jedno z nich, żeby uzyskać dostęp do teleportera. Jeśli trzeba, wyrżnij wszystkie demony, ale nie możesz wrócić z pustymi rękami.', 'Przynieś Sterownik teleportera Legionu Dowódcy skrzydła Nuainnowi w Warowni Dzikiego Młota. Wiadomo, że takie urządzenia noszą mo\'argowie kowale broni z Warowni Legionu.', '', 'Wróć do Dowódcy skrzydła Nuainna w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10595, 'koKR', 'Oblężenie!', '<Gulmok spogląda w niebo.>$B$BNasi zwiadowcy dzielnie walczą, ale piekielniki wciąż nadlatują!$B$BZe swojej bazy w Warowni Legionu na południowym zachodzie demony bezkarnie nas bombardują! Nawet elitarna gwardia Kor\'kronu nie powstrzyma ich w nieskończoność.$B$BWcielam do walki każdego, kto może utrzymać broń, by bronił Wioski Cienistego Księżyca. To nie zabawa, $N. Chodzi o przetrwanie wioski. Wypełnij swój obowiązek wobec Hordy i ruszaj do walki!', 'Strażnik krwi Gulmok, przed Wioską Cienistego Księżyca, chce, żebyś $gzabił:zabiła; 10 atakujących piekielników.', '', 'Wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10596, 'koKR', 'Do Warowni Legionu', 'Twoim celem jest twierdza – Warownia Legionu. Nie dostaniesz posiłków, więc atak frontalny nie wchodzi w grę.$B$BZ tych skąpych informacji, które mamy, wynika, że Legion gromadzi i przygotowuje w warowni swoje piekielniki. Dzięki przebraniu, które ci dam, musisz zakraść się do Warowni Legionu i poznać ich plany.$B$BNajwiększą szansę masz, jeśli przechwycisz albo podsłuchasz rozmowę ich dowódców.', 'Dostań się do Warowni Legionu, odnajdź Urządzenie łączności Legionu i w przebraniu poznaj plany Legionu. Po wykonaniu misji wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca.', '', 'Wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', 'Poznanie planów Legionu', '', 0),
(10597, 'koKR', 'Budowa bomby', 'Nie możemy pozwolić, by Legion stratował nas w marszu na Czarną Świątynię.$B$BZnajdź sposób, by zniszczyć piekielniki, które zamierzają przeciw nam użyć. To nie prośba, $N, to rozkaz.$B$BW Cuchnącej Sadzawce przy Warowni Legionu leży stary rdzeń zasilający grabieżcy Spaczenia, który może posłużyć za podstawę czegoś w rodzaju spaczonej bomby. Przeszukaj inne szczątki w pobliżu grabieżcy, a znajdziesz kawałek opancerzenia. Powinno ci się udać zrobić bombę dość silną, żeby rozwalić te piekielniki i porządnie wstrząsnąć warownią!', 'Zdobądź Rdzeń zasilający grabieżcy Spaczenia i Płytę pancerną grabieżcy Spaczenia, a potem przynieś je Strażnikowi krwi Gulmokowi w Wiosce Cienistego Księżyca.', '', 'Wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10598, 'koKR', 'Wysadź piekielniki!', 'Urządzenie, które złożyliśmy, nie wygra żadnego konkursu piękności, ale powinno zniszczyć piekielniki zgromadzone w Warowni Legionu. Sądząc po tym, co energia rdzenia zasilającego grabieżcy Spaczenia zrobiła z Cuchnącą Sadzawką, drzemie w nim spora siła wybuchu.$B$BJeśli zdetonujesz urządzenie na środku zielonego glifu w warowni, powinno dosięgnąć wszystkich piekielników.', 'Użyj Spaczonej bomby, stojąc na zielonym glifie w Warowni Legionu, by zniszczyć piekielniki, a potem zamelduj się u Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca.', '', 'Wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', 'Zniszczenie piekielników Warowni Legionu', '', '', 0),
(10599, 'koKR', 'Kuźnia Śmierci', 'Kiedy $gzajmowałeś:zajmowałaś; się piekielnikami w Warowni Legionu, przeglądałem twoje raporty. Nie mamy powodu sądzić, że Legion kłamał co do tego, co się dzieje w Kuźni Śmierci. Naprawdę trzaskają tam piekielniki jak na taśmie, więc wysłałem oddział zwiadowczy, żeby miał na to oko.$B$BJeśli nie unieszkodliwimy Kuźni Śmierci, odbudują zapas piekielników, który $gzniszczyłeś:zniszczyłaś; w Warowni Legionu.$B$BZamelduj się u Zwiadowcy Zagrana na szczycie Żużlowej Strażnicy, na południowy wschód stąd, skąd widać Kuźnię Śmierci.', 'Zamelduj się u Zwiadowcy Zagrana w Żużlowej Strażnicy.', '', '', '', '', '', '', 0),
(10600, 'koKR', 'Sługusy Rady Cieni', '<Zagran słucha twojej relacji z wydarzeń w Warowni Legionu i kiwa głową.>$B$BTo wypełnia luki w tym, co widzieliśmy. Widzieliśmy przelotnie, jak wystrzeliwują piekielniki w stronę warowni, ale niczego więcej nie udało nam się ustalić.$B$BRada Cieni praktycznie zamknęła kuźnię na cztery spusty. Wygląda na to, że będziesz $gmusiał:musiała; się tam wedrzeć siłą. Zacznij od wybicia sług Rady Cieni, którzy strzegą wejścia do Kuźni Śmierci!', 'Zwiadowca Zagran w Żużlowej Strażnicy chce, żebyś $gzabił:zabiła; 10 strażników z Kuźni Śmierci i 5 przywoływaczy z Kuźni Śmierci.', '', 'Wróć do Zwiadowcy Zagrana w Żużlowej Strażnicy w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10601, 'koKR', 'Los Kagrosha', 'Początkowo nasz oddział zwiadowczy liczył trzech członków. Niestety, Kagrosh postanowił zostać bohaterem.$B$BZszedł do Kuźni Śmierci i od tamtej pory nie mamy od niego wieści.$B$BNajpewniej głupiec dał się zabić. Członkowie Rady Cieni to nie idioci, a Kagrosh nie grzeszył subtelnością, jeśli wiesz, co mam na myśli. Wypatruj go w Kuźni Śmierci i przynieś wszelkie informacje i przedmioty, które mógł zebrać.', 'Zwiadowca Zagran w Żużlowej Strażnicy chce, żebyś $gprzeszukał:przeszukała; Kuźnię Śmierci w poszukiwaniu Kagrosha i $godzyskał:odzyskała; Plecak Kagrosha.', '', 'Wróć do Zwiadowcy Zagrana w Żużlowej Strażnicy w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10602, 'koKR', 'Komnata przywołań', 'Żeby produkować piekielniki tak szybko, jak najwyraźniej robi to Kuźnia Śmierci, muszą mieć miejsce przeznaczone do przywoływania żywiołaków, które stanowią rdzeń piekielników.$B$BKomnata przywołań znajduje się zapewne pod ziemią, w pobliżu sadzawki skażonej wody albo lawy. Odnajdź komnatę przywołań w Kuźni Śmierci i znajdź sposób, żeby przerwać ich rytuał przywołania. Mo\'argowie, którzy wytwarzają piekielniki, mogą mieć przy sobie narzędzie, które pomoże zakłócić magię przywoływacza.', 'Zdobądź Przemieszczacz żywiołaków od kowala z Kuźni Śmierci albo majsterkowicza z Kuźni Śmierci i użyj go, by zakłócić rytuał w komnacie przywołań. Po wykonaniu zadania zamelduj się u Zwiadowcy Zagrana w Żużlowej Strażnicy.', '', 'Wróć do Zwiadowcy Zagrana w Żużlowej Strażnicy w Dolinie Cienistego Księżyca.', 'Przerwanie rytuału przywołania piekielników', '', '', '', 0),
(10603, 'koKR', 'Pokonaj Siewcę wojny!', 'Poczyniliśmy spore postępy w walce z Radą Cieni tu, w Kuźni Śmierci, ale teraz czas dokończyć robotę.$B$BW plecaku Kagrosha znalazłem klucz. Przynajmniej coś osiągnął, zanim go dopadli.$B$BKlucz powinien ci pomóc wytropić tego Siewcę wojny Razuuna, którego $gwidziałeś:widziałaś; w Warowni Legionu.$B$BGdy już wytropisz Siewcę wojny Razuuna i się z nim rozprawisz, zamelduj się bezpośrednio u Strażnika krwi Gulmoka. Nie możemy kazać mu czekać.', 'Pokonaj Siewcę wojny Razuuna, zdobądź Rozkazy Razuuna i zamelduj się u Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca.', '', 'Wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10604, 'koKR', 'Zdobycie dostępu', 'Według rozkazów Razuuna ogromny punkt zborny piekielników nazywa się Punkt Inwazji: Kataklizm i leży w górach za naszą wioską! Można się tam dostać tylko przez teleporter w Warowni Legionu.$B$BNiektóre sługi Legionu noszą urządzenie, które pozwala korzystać z teleportera. Musisz zdobyć jedno z nich, żeby uzyskać dostęp do teleportera. Jeśli trzeba, wyrżnij wszystkie demony, ale nie możesz wrócić z pustymi rękami. Nie zwlekaj – wróg jest niebezpiecznie blisko.', 'Przynieś Sterownik teleportera Legionu Strażnikowi krwi Gulmokowi w Wiosce Cienistego Księżyca. Wiadomo, że takie urządzenia noszą mo\'argowie kowale broni z Warowni Legionu.', '', 'Wróć do Strażnika krwi Gulmoka w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10606, 'koKR', 'Sztuka konserwacji grabieżcy Spaczenia', 'Najlepszy sposób na zniszczenie reszty zapasów Legionu to obrócić przeciw nim ich własną broń. Pracuję nad urządzeniem, które pozwoli ci przejąć kontrolę nad jednym z tych wartowniczych grabieżców Spaczenia na dole.$B$BMuszę jeszcze dopracować parę rzeczy. Do tego potrzebuję instrukcji, którą Doktor Gutrick trzyma zamkniętą w skrzyni u stóp rampy. Pewnie nie odda klucza bez walki, więc będziesz $gmusiał:musiała; go zdobyć siłą. Przynieś mi instrukcję grabieżcy, a resztą zajmę się sam!', 'Zabij Doktora Gutricka i zdobądź Klucz Doktora. Otwórz nim Sejf Doktora, wyjmij z niego „Sztukę konserwacji grabieżcy Spaczenia” i dostarcz książkę Plexiemu w Punkcie Inwazji: Kataklizm.', '', 'Wróć do Plexiego w Punkcie Inwazji: Kataklizm w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10611, 'koKR', 'Sztuka konserwacji grabieżcy Spaczenia', 'Najlepszy sposób na zniszczenie reszty zapasów Legionu to obrócić przeciw nim ich własną broń. Pracuję nad urządzeniem, które pozwoli ci przejąć kontrolę nad jednym z tych wartowniczych grabieżców Spaczenia na dole.$B$BMuszę jeszcze dopracować parę rzeczy. Do tego potrzebuję instrukcji, którą Doktor Maleficus trzyma zamkniętą w skrzyni u stóp rampy. Pewnie nie odda klucza bez walki, więc będziesz $gmusiał:musiała; go zdobyć siłą. Przynieś mi instrukcję grabieżcy, a resztą zajmę się sam.', 'Zabij Doktora Maleficusa i zdobądź Klucz Doktora. Otwórz nim Sejf Doktora, wyjmij z niego „Sztukę konserwacji grabieżcy Spaczenia” i dostarcz książkę Nakansiemu w Punkcie Inwazji: Kataklizm.', '', 'Wróć do Nakansiego w Punkcie Inwazji: Kataklizm w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10612, 'koKR', 'Spaczeni i wściekli', '<Plexi kartkuje instrukcję.>$B$BNo, jest tu wszystko, czego potrzebujemy, ale jest jeden problem. Grabieżcy Spaczenia nie są właściwie zbudowani do zdalnego sterowania.$B$BMożemy jednego przerobić, żebyś $gmógł:mogła; z niego przez chwilę korzystać, ale będziesz $gmusiał:musiała; działać szybko, bo nie wiadomo, co się może stać! Nie zdziwię się też, jeśli twoje popisy z grabieżcą zwrócą uwagę pachołków Legionu. Miej oczy szeroko otwarte i cokolwiek robisz, nie zapomnij zniszczyć tyle, ile się da!', 'Użyj Konsoli sterującej grabieżcy Spaczenia, by przejąć kontrolę nad wartowniczym grabieżcą Spaczenia. Zniszcz 60 piekielników z Kuźni Śmierci, zanim twój grabieżca się rozpadnie. Po wykonaniu misji zamelduj się u Plexiego w Punkcie Inwazji: Kataklizm.', '', 'Wróć do Plexiego w Punkcie Inwazji: Kataklizm w Dolinie Cienistego Księżyca.', 'Zniszczone piekielniki z Kuźni Śmierci', '', '', '', 0),
(10613, 'koKR', 'Spaczeni i wściekli', '<Nakansi kartkuje instrukcję.>$B$BWszystkie informacje tu są, ale uważaj. Te maszyny nie zostały zbudowane do zdalnego sterowania.$B$BMożemy jedną przerobić, żebyś $gmógł:mogła; z niej przez chwilę korzystać, ale będziesz $gmusiał:musiała; działać szybko, bo nie wiadomo, co się może stać! Nie zdziwię się też, jeśli twoje popisy z grabieżcą zwrócą uwagę legionowej hołoty. Staraj się uważać na siebie, ale pamiętaj: misja i bezpieczeństwo Wioski Cienistego Księżyca są najważniejsze!', 'Użyj Konsoli sterującej grabieżcy Spaczenia, by przejąć kontrolę nad wartowniczym grabieżcą Spaczenia. Zniszcz 60 piekielników z Kuźni Śmierci, zanim twój grabieżca się rozpadnie. Po wykonaniu misji zamelduj się u Nakansiego w Punkcie Inwazji: Kataklizm.', '', 'Wróć do Nakansiego w Punkcie Inwazji: Kataklizm w Dolinie Cienistego Księżyca.', 'Zniszczone piekielniki z Kuźni Śmierci', '', '', '', 0),
(10619, 'koKR', 'Plemię Popielnych Języków', 'Plemię Popielnych Języków budzi strach wśród wszystkich Złamanych. Należą do niego najokrutniejsi i najbardziej krwiożerczy osobnicy, wybrani osobiście przez samego Akamę. Są równie zajadli i bezwzględni jak każdy naga, demon czy krwawy elf w armii Illidana, a teraz rozmieszczono ich w dużej liczbie w Ruinach Baa\'ri, na południowy zachód stąd. Udaj się tam i przerzedź ich szeregi, zanim zdążą nas zaatakować.', 'Obrońca Aluumen chce, żebyś $gudał:udała; się do Ruin Baa\'ri i $gzabił:zabiła; 3 treserów Popielnych Języków, 4 wojowników Popielnych Języków i 6 szamanów Popielnych Języków.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Obrońcy Aluumena przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10621, 'koKR', 'Odłamek zguby Illidari', 'Odłamek wygląda na kawałek większej broni. Ostro zarysowane runy wyryte w metalu jarzą się złowrogim światłem.$B$BNie wiesz, do czego miała służyć ta broń, ale trudno przejść obok niej obojętnie. Większość mo\'argów w Warowni Legionu zdaje się pracować z fragmentami tego samego metalu, który trzymasz w dłoni. Może któryś z kowali broni w Warowni Dzikiego Młota powie ci o nim coś więcej.', 'Zanieś Odłamek zguby Illidari Ordinnowi Gromopięściowi w Warowni Dzikiego Młota.', '', '', '', '', '', '', 0),
(10622, 'koKR', 'Dowód lojalności', 'Akama bardzo uważnie śledzi twoje postępy, $N.$B$BPopielne Języki, które $gzabiłeś:zabiłaś; w Ruinach Baa\'ri, należą do najpodlejszych Złamanych, jakich znamy... starannie wybranych przez samego Akamę, by podtrzymać pozory, które musimy utrzymywać wobec Illidana. Zaprzysiężeni znają jednak prawdziwe zamiary Akamy.$B$BNajpierw najważniejsze. Musimy wiedzieć, że nie trzymasz z Illidanem. Satyr imieniem Zandras obserwuje nas w jego imieniu znad murów więzienia. Zabij go na dowód swojej lojalności.', 'Zabij Zandrasa w Klatce Strażniczki w Dolinie Cienistego Księżyca i wróć do Sanoru.', '', 'Wróć do Sanoru w Klatce Strażniczki w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10623, 'koKR', 'Odłamek zguby Illidari', 'Odłamek wygląda na kawałek większej broni. Ostro zarysowane runy wyryte w metalu jarzą się złowrogim światłem.$B$BNie wiesz, do czego miała służyć ta broń, ale trudno przejść obok niej obojętnie. Większość mo\'argów w Warowni Legionu zdaje się pracować z fragmentami tego samego metalu, który trzymasz w dłoni. Może któryś z kowali broni w Wiosce Cienistego Księżyca powie ci o nim coś więcej.', 'Zanieś Odłamek zguby Illidari Grokomowi Śmierciookiemu w Wiosce Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10624, 'koKR', 'Nawiedzona historia', 'Czy $gpoczułeś:poczułaś; lodowaty dreszcz? Może coś, co $gwziąłeś:wzięłaś; za dłoń na swoim ramieniu? To nie umysł płatał ci figle. Ta kraina jest nawiedzona. Duchy zaśmiecają okolicę, uwięzione tu na całą wieczność.$B$BChcesz je zobaczyć? Na pewno? Takie rzeczy zwykle zmieniają człowieka – i to nie na lepsze.$B$BDobrze więc, musisz zebrać dla mnie wiecznie tlący się popiół, który można znaleźć w pobliżu każdej z sadzawek spaczonej lawy w zachodniej części Cienistego Księżyca. Gdziekolwiek w pobliżu zielonej lawy...$B', 'Główna aptekarka Hildagard z Wioski Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; jej 15 próbek wiecznie tlącego się popiołu.', '', 'Wróć do Głównej aptekarki Hildagard w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10625, 'koKR', 'Duchokulary', 'Nazywam je „duchokularami”. Sprytne, co? Gdy założysz te gogle, zobaczysz duchy Doliny Cienistego Księżyca.$B$BZanim ci je dam, musisz mi jednak obiecać, że pomożesz nam oczyścić wioskę z duchów.$B$BWeź gogle i zniszcz wszystkie duchy, które zobaczysz błąkające się po Wiosce Cienistego Księżyca. Mam nadzieję, że zniszczenie tych duchów zmusi pozostałe do przeniesienia się gdzie indziej.', 'Główna aptekarka Hildagard z Wioski Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; 12 fanatyków Cienistego Księżyca.', '', 'Wróć do Głównej aptekarki Hildagard w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10626, 'koKR', 'Zdobycie broni', 'Mając więcej tego materiału, może zdołalibyśmy wykuć dla ciebie broń.$B$BDwaj lordowie otchłani z Warowni Legionu, Makazradon i Morgroron, już dostali tę broń przeciw demonom. Nie wiemy, ile jeszcze Legion zamierza jej wyprodukować, ale jeśli zdobędziemy te prototypy, materiału powinno wystarczyć na nasz projekt.$B$B<Ordinn szczerzy zęby.>$B$BTo spora satysfakcja użyć przeciw Legionowi jego własnej „tajnej broni”, nie sądzisz?', 'Ordinn Gromopięść w Warowni Dzikiego Młota chce, żebyś $gprzyniósł:przyniosła; mu Glewię Makazradona i Glewię Morgrorona.', '', 'Wróć do Ordinna Gromopięścia w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10627, 'koKR', 'Zdobycie broni', 'Mając więcej tego materiału, mogę wykuć broń odpowiednią dla ciebie.$B$BDwaj lordowie otchłani z Warowni Legionu, Makazradon i Morgroron, już dostali tę broń przeciw demonom. Zdobycie tych dwóch sztuk powinno nam dać dość materiału na twoją broń, a nawet z nawiązką.$B$BNie mogę się doczekać, aż ruszymy z tą bronią na wroga. To oduczy Legion igrania z magią przeciw demonom.', 'Grokom Śmierciooki w Wiosce Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu Glewię Makazradona i Glewię Morgrorona.', '', 'Wróć do Grokoma Śmierciookiego w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10628, 'koKR', 'Akama', '$GUdowodniłeś:Udowodniłaś;, po której stronie stoisz. Wyjawię ci kryjówkę naszego przywódcy.$B$BIdź dalej korytarzami; po prawej stronie znajdziesz podziemne przejście ukryte pod stojącą wodą.$B$BMuszę cię ostrzec, $N. Nie wolno ci nikomu mówić o tym, co tam zobaczysz.', 'Porozmawiaj z Akamą w ukrytej komnacie w Klatce Strażniczki.', '', '', '', '', '', '', 0),
(10633, 'koKR', 'Teron Krwawy Bies – wiedza i legenda', 'Krąży wiele opowieści o życiu Terona Krwawego Biesa, ale większość z nich to tylko opowieści. Nie wiemy, co się stało z Krwawym Biesem po jego powrocie na Draenor.$B$BWiemy na pewno tylko to, że raz już umarł.$B$BSłyszałam, jak tutejsi zwiadowcy mówili o pradawnym duchu orka, który przebywa przy Ołtarzu Cieni, daleko na południowym wschodzie, za Polami Otchłanioskrzydłych i Przełęczą Otchłanioskrzydłych. Weź duchokulary i wytrop tego orka. Z pewnością wie więcej o Krwawym Biesie.', 'Główna aptekarka Hildagard z Wioski Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $godnalazł:odnalazła; Pradawnego ducha Cienistego Księżyca.$B$BJeśli zgubisz Duchokulary, Główna aptekarka Hildagard może ci zrobić nową parę.', '', '', '', '', '', '', 0),
(10634, 'koKR', 'Wróżba: zbroja Krwawego Biesa', 'Za życia Krwawy Bies był potworem, ale po śmierci stał się prawdziwym postrachem.$B$BNa południowym wschodzie znajdziesz Występ Otchłanioskrzydłych. To, co niegdyś było częścią lądu Cienistego Księżyca, jest teraz wyspą unoszącą się na niebie.$B$BVhel\'kur, pomiot Śmiercioskrzydłego, nazywał ją niegdyś swoim domem, a teraz jest ona jego grobem. Krąży bez końca nad wyspą, kipiąc gniewem po klęsce zadanej mu przez Krwawego Biesa.$B$BJeśli chcesz odzyskać zbroję Krwawego Biesa, musisz pokonać Vhel\'kura.', 'Pradawny duch Cienistego Księżyca przy Ołtarzu Cieni w południowo-wschodniej części Doliny Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; Zbroję Krwawego Biesa.', '', 'Wróć do Pradawnego ducha Cienistego Księżyca przy Ołtarzu Cieni w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10635, 'koKR', 'Wróżba: płaszcz Krwawego Biesa', 'Popełnił wiele okrutnych czynów, ale żaden nie był tak bezduszny jak rzeź kleryków Karaboru.$B$BGdy Horda Gul\'dana pokonała draenei z Karaboru, ocalałych kleryków Karaboru wyprowadzono, mówiąc im, że zostaną zabrani do Cytadeli Piekielnego Ognia jako jeńcy wojenni.$B$BKrwawy Bies, jeszcze zanim został rycerzem śmierci, z zimną krwią wymordował ich co do jednego. Teraz błąkają się przed Czarną Świątynią z żądzą zemsty w sercach.$B$BTo klerycy Karaboru mają płaszcz Krwawego Biesa.', 'Pradawny duch Cienistego Księżyca przy Ołtarzu Cieni w południowo-wschodniej części Doliny Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; Płaszcz Krwawego Biesa.', '', 'Wróć do Pradawnego ducha Cienistego Księżyca przy Ołtarzu Cieni w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10636, 'koKR', 'Wróżba: pałka Krwawego Biesa', 'Jeden po drugim klękali przed nim, ofiarując swoje życie na dowód wierności. Krwawy Bies wznosił sierp i ścinał im głowy jednym cięciem. Wkrótce po tej rzezi Krwawy Bies odebrał sobie życie.$B$BAle nie był to akt skruchy! Nie, Krwawy Bies szukał nieśmiertelności! Ze zwłok poległych rycerzy śmierci powstali Widmowi jeźdźcy Karaboru.$B$BTeraz przemierzają drogi okalające Rękę Gul\'dana, czekając na dzień powrotu swojego pana. To oni mają pałkę Krwawego Biesa. Odzyskaj ją...', 'Pradawny duch Cienistego Księżyca przy Ołtarzu Cieni w południowo-wschodniej części Doliny Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; Pałkę Krwawego Biesa.', '', 'Wróć do Pradawnego ducha Cienistego Księżyca przy Ołtarzu Cieni w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10637, 'koKR', 'Konieczna dywersja', 'Broń jest prawdziwa, tak jak się obawialiśmy. Illidan szkoli łowców demonów w Ruinach Karaboru i musimy z tym skończyć.$B$BNie daj się zwieść ich nazwie, $N – ich moc zostanie użyta przeciw nam równie często jak przeciw demonom.$B$BIch czarnoksiężnicy przywołują i ujarzmiają demony, które służą do szkolenia nowicjuszy. Władca otchłani imieniem Azaloth okazał się zbyt silny, by go używać do szkolenia, i jest trzymany w stanie wygnania. Znajdź sposób, by uwolnić go przeciw jego strażnikom. To powinno dać nam potrzebny czas.', 'Egzarcha Onaala chce, żebyś $gwrócił:wróciła; do Ruin Karaboru i $gznalazł:znalazła; sposób, by nasłać Azalotha na jego strażników.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Egzarchy Onaali przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', 'Uwolnienie Azalotha', '', '', '', 0),
(10639, 'koKR', 'Teronem Krwawym Biesem jestem...', 'Przedmioty Krwawego Biesa są już odzyskane, brakuje więc tylko ostatniego elementu układanki: nosiciela.$B$B<Usta pradawnego ducha Cienistego Księżyca wykrzywiają się w złowrogim uśmiechu.>$B$BChyba nie $guwierzyłeś:uwierzyłaś; w bajeczkę, którą ci opowiedziałem? Ołtarz Cieni jest moim więzieniem. Bez twojej pomocy tkwiłbym tu przez całą wieczność. Teraz przejmę twoje ciało, a ty zniszczysz moich strażników i zerwiesz te więzy. Odmów, a na zawsze utkniemy tu razem.$B$BTeron Krwawy Bies będzie wolny!', 'Pradawny duch Cienistego Księżyca wykorzystał cię jak pionka! Teraz, gdy $gzebrałeś:zebrałaś; potrzebne mu przedmioty, ujawnił, że jest Teronem Krwawym Biesem. Aby uwolnić się spod jego władzy, musisz wykonać jego polecenie i zabić Karsiusa Pradawnego Wartownika.$B$BJeśli ci się uda, wróć do Głównej aptekarki Hildagard w Wiosce Cienistego Księżyca.', '', 'Wróć do Głównej aptekarki Hildagard w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10642, 'koKR', 'Duch w maszynie', 'Obawiam się, że te krasnoludy nie rozumieją, na czym zbudowały swoją warownię. Ten teren był niegdyś ziemią przodków orków z klanu Cienistego Księżyca. Mówię o duchach.$B$BPrzez blisko dwadzieścia lat spoczywały uśpione pod Warownią Dzikiego Młota, ale ostatnio coś je rozjątrzyło.$B$BWyjdź za bramy Warowni Dzikiego Młota i odszukaj sadzawki i rzeki spaczonej lawy, których pełno w tej krainie. Przy lawie znajdziesz wiecznie tlący się popiół. Przynieś mi go, żebym mógł zrobić z niego coś, co nam pomoże.$B', 'Zorus Sędzia w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 15 próbek wiecznie tlącego się popiołu.', '', 'Wróć do Zorusa Sędziego w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10643, 'koKR', 'Zwiastuni Cienistego Księżyca', 'Niech wszyscy wiedzą, że Zorus ma poczucie humoru.$B$BDość pogaduszek. Załóż duchokulary, żeby widzieć duchy orków z Cienistego Księżyca, które błąkają się po tej warowni. Nie bój się, bo tak naprawdę to my jesteśmy tu najeźdźcami. Niestety, trzeba je zniszczyć, bo ich czas dawno minął.$B$BZniszcz zwiastunów Cienistego Księżyca, którzy nawiedzają Warownię Dzikiego Młota, i wróć do mnie.', 'Zorus Sędzia w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; 12 zwiastunów Cienistego Księżyca.', '', 'Wróć do Zorusa Sędziego w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10644, 'koKR', 'Teron Krwawy Bies – wiedza i legenda', 'Krąży wiele opowieści o życiu Terona Krwawego Biesa, ale większość z nich to tylko opowieści. Nie wiemy, co się stało z Krwawym Biesem po jego powrocie na Draenor.$B$BWiemy na pewno tylko to, że raz już umarł.$B$BSłyszałem, jak tutejsi zwiadowcy mówili o pradawnym duchu orka, który przebywa przy Ołtarzu Cieni, daleko na wschodzie, za Polami Otchłanioskrzydłych i Przełęczą Otchłanioskrzydłych. Weź duchokulary i wytrop tego orka. Z pewnością wie więcej o Krwawym Biesie.', 'Zorus Sędzia w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $godnalazł:odnalazła; Pradawnego ducha Cienistego Księżyca.$B$BJeśli zgubisz Duchokulary, Zorus Sędzia może ci zrobić nową parę.$B', '', '', '', '', '', '', 0),
(10645, 'koKR', 'Teronem Krwawym Biesem jestem...', 'Przedmioty Krwawego Biesa są już odzyskane, brakuje więc tylko ostatniego elementu układanki: nosiciela.$B$B<Usta pradawnego ducha Cienistego Księżyca wykrzywiają się w złowrogim uśmiechu.>$B$BChyba nie $guwierzyłeś:uwierzyłaś; w bajeczkę, którą ci opowiedziałem? Ołtarz Cieni jest moim więzieniem. Bez twojej pomocy tkwiłbym tu przez całą wieczność. Teraz przejmę twoje ciało, a ty zniszczysz moich strażników i zerwiesz te więzy. Odmów, a na zawsze utkniemy tu razem.$B$BTeron Krwawy Bies będzie wolny!', 'Pradawny duch Cienistego Księżyca wykorzystał cię jak pionka! Teraz, gdy $gzebrałeś:zebrałaś; potrzebne mu przedmioty, ujawnił, że jest Teronem Krwawym Biesem. Aby uwolnić się spod jego władzy, musisz wykonać jego polecenie i zabić Karsiusa Pradawnego Wartownika.$B$BJeśli ci się uda, wróć do Zorusa Sędziego w Warowni Dzikiego Młota.', '', 'Wróć do Zorusa Sędziego w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10647, 'koKR', 'Poszukiwany: Uvuros, plaga Cienistego Księżyca', 'Poszukiwany – MARTWY:$B$BUvuros, plaga Doliny Cienistego Księżyca.$B$BNa rozkaz Zwierzchnika Or\'barokha spaczoną bestię Uvurosa należy zabić na miejscu, a z jego truchła zedrzeć grzywę na dowód wykonania zadania. Jeśli ci się uda, zanieś ognistą grzywę bestii Heroldowi wojny Sardonowi Celnociosowi.$B$BUvurosa widziano ostatnio przy Ręce Gul\'dana, w sercu Doliny Cienistego Księżyca – na wschód od Wioski Cienistego Księżyca.', 'Zabij Uvurosa i zdobądź Ognistą grzywę Uvurosa. Zanieś ją Heroldowi wojny Sardonowi Celnociosowi w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', 'Wróć do Herolda wojny Sardona Celnociosa w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10648, 'koKR', 'Poszukiwany: Uvuros, plaga Cienistego Księżyca', 'Poszukiwany – MARTWY:$B$BUvuros, plaga Doliny Cienistego Księżyca.$B$BNa rozkaz Thana Yoregara spaczoną bestię Uvurosa należy zabić na miejscu, a z jego truchła zedrzeć grzywę na dowód wykonania zadania. Jeśli ci się uda, zanieś ognistą grzywę bestii Heroldowi wojny Piworyjowi.$B$BUvurosa widziano ostatnio przy Ręce Gul\'dana, w sercu Doliny Cienistego Księżyca – na północny wschód od Warowni Dzikiego Młota.', 'Zabij Uvurosa i zdobądź Ognistą grzywę Uvurosa. Zanieś ją Heroldowi wojny Piworyjowi w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', 'Wróć do Herolda wojny Piworyja w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10651, 'koKR', 'Varedis musi zostać powstrzymany', 'Musimy pozbyć się tego plugawego artefaktu, ale nie wcześniej, niż użyjemy go, by pozbawić Varedisa mocy.$B$BMusimy raz na zawsze zamknąć plac ćwiczeń w Ruinach Karaboru, co oznacza zabicie nie tylko Varedisa, ale i trzech nocnych elfów, mistrzów, którzy mu pomagają: Alandiena, Therasa i Netharela.$B$BZbierz odpowiednie siły i wróć do Ruin Karaboru. Postępuj według wskazówek Altruisa, jak pokonać Varedisa. Dla dobra nas wszystkich mam nadzieję, że się sprawdzą.', 'Egzarcha Onaala chce, żebyś $gudał:udała; się do Ruin Karaboru i $gzabił:zabiła; Alandiena, Therasa, Netharela i Varedisa. Gdy Varedis użyje Metamorfozy, użyj Księgi spaczonych imion, by go osłabić. Po wykonaniu zadania wróć z Księgą spaczonych imion do Egzarchy Onaali.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Egzarchy Onaali przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10660, 'koKR', 'Cóż za dziwne stworzenia...', 'Chciałbym dowiedzieć się więcej o dziwnych gadach, które kręcą się wokół potoków lawy w Dolinie Cienistego Księżyca. Nigdy nie widziałem bestii, które potrafią znieść palący żar roztopionej lawy!$B$BZa Wioską Cienistego Księżyca, tam gdzie ziemia popękała, a przez szczeliny płynie lawa, znajdziesz diemetradony ognia spaczenia. Zabij je i przynieś mi ich śledziony. Na ich podstawie zacznę wstępną analizę ich odporności na żar.$B$BZacznij poszukiwania na południowym wschodzie.$B', 'Badacz Tiorus z Wioski Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; 8 śledzion ognia spaczenia.', '', 'Wróć do Badacza Tiorusa w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10661, 'koKR', 'Wyśledzionite!', '$GSłyszałeś:Słyszałaś; kiedyś o jedzeniu, które samo się gotuje i jest wiecznie gorące? Trzeba mieć marzenia, mówię!$B$BA może to wcale nie marzenie! Za twierdzą, w pobliżu sadzawek i strumieni lawy, żyją bestie, które kwitną w skwierczącym żarze. Nazywają się diemetradony ognia spaczenia.$B$BTutejsze krasnoludy mówią mi, że te diemetradony mają najsmaczniejsze śledziony na świecie i że te śledziony są praktycznie ugotowane z góry! Przynieś mi te śledziony, a dostaniesz trochę grosza.$B$BZacznij szukać dokładnie na wschód stąd.', 'Gnomus w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; 8 śledzion ognia spaczenia.', '', 'Wróć do Gnomusa w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10672, 'koKR', 'Szczerze mówiąc, to nie ma sensu...', 'Musimy dalej badać te stworzenia.$B$BDaleko na wschodzie – przy wielkim potoku lawy pod Ruinami Baa\'ri – znajdziesz arkanomoduły sterujące. Zbudował je geniusz imieniem Gnomus wyłącznie po to, by badać lawę za pomocą mechanicznego skorpiona.$B$BDawno już postradał zmysły i teraz interesuje go tylko jedzenie najostrzejszych potraw, jakie zna gnomi ród.$B$B<Tiorus dziwnie na ciebie patrzy.>$B$BChcę, żebyś $gużył:użyła; sterownika i $goznakował:oznakowała; diemetradony z potoku lawy do dalszych badań.$B', 'Badacz Tiorus z Wioski Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $gudał:udała; się do potoku lawy przy Ruinach Baa\'ri, za pomocą Arkanomodułu sterującego $gprzejął:przejęła; kontrolę nad arkanoskorpionem, $gpopłynął:popłynęła; nim w lawie i $goznakował:oznakowała; 8 większych diemetradonów ognia spaczenia.', '', 'Wróć do Badacza Tiorusa w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', 'Oznakowane większe diemetradony ognia spaczenia', '', '', '', 0),
(10673, 'koKR', 'Spaczogrzbiet Większy', 'Gnomus wie o tym ogromnym diemetradonie i zamierza go zjeść! Musiał widzieć oczami swojego arkanoskorpiona to samo co ja. Słuchaj, nie ma czasu na wyjaśnienia. To wariat, a przez jego wariactwo stracimy najlepsze, co mamy, jeśli chodzi o ognioodporny kombinezon.$B$BWróć do potoku lawy przy Baa\'ri i wytrop Spaczogrzbieta Większego. Gdy go znajdziesz, zabij go i przynieś mi jego skórę.$B$BNawet nie próbuj przemawiać mi do rozsądku, $N. Mam to już dawno za sobą.', 'Badacz Tiorus z Wioski Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; Spaczogrzbieta Większego i $gzdobył:zdobyła; Skórę Spaczogrzbieta.$B', '', 'Wróć do Badacza Tiorusa w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10677, 'koKR', 'Drugie danie...', 'Pamiętam, że widziałem większe diemetradony na wschód od Ręki Gul\'dana, przy potokach lawy wokół Ruin Baa\'ri. Teraz chcę, żebyś $gzdobył:zdobyła; dla mnie jeden przerośnięty żołądek ognia spaczenia od tamtejszych bestii. Może trzeba będzie zabić kilka, zanim znajdziesz taki żołądek, jak opisałem. Nie ustawaj! Któraś z nich na pewno ma w sobie mój następny posiłek.', 'Gnomus w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; 1 Przerośnięty żołądek ognia spaczenia.', '', 'Wróć do Gnomusa w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10678, 'koKR', 'Danie główne!', 'Krótko mówiąc, pracowałem kiedyś z krwawym elfem imieniem Tiorus. Nasza spółka się rozpadła, gdy zająłem się życiem smakosza. Postanowił na własną rękę prowadzić dalej nasze badania, używając MOICH wynalazków. W każdym razie kilku jego osiłków z Hordy używało moich arkanoskorpionowych sond przy potoku lawy w Ruinach Baa\'ri i odkryło matkę wszystkich diemetradonów!$B$BMusisz dotrzeć tam przed nim, zabić tego diemetradona, Spaczogrzbieta, i przynieść mi jego skórę.$B$BPospiesz się!', 'Gnomus w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $gzdobył:zdobyła; Skórę Spaczogrzbieta.', '', 'Wróć do Gnomusa w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10680, 'koKR', 'Ręka Gul\'dana', 'Żywioły potrzebują twojej pomocy! Dolina Cienistego Księżyca doświadczyła niewypowiedzianego zła. Duchy do dziś cierpią męki. Wiele z nich jest rozwścieczonych i nie chce porozumiewać się z Kręgiem Ziemi.$B$BPomóż temu światu się uleczyć, $gprzyjacielu:przyjaciółko;.$B$BDokładnie na północny wschód od Warowni Dzikiego Młota znajdziesz miejsce zwane Ołtarzem Potępienia. Udaj się tam i porozmawiaj z Uzdrowicielem ziemi Torlokiem.', 'Porozmawiaj z Uzdrowicielem ziemi Torlokiem przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10681, 'koKR', 'Ręka Gul\'dana', 'Żywioły potrzebują twojej pomocy! Dolina Cienistego Księżyca doświadczyła niewypowiedzianego zła. Duchy do dziś cierpią męki. Wiele z nich jest rozwścieczonych i nie chce porozumiewać się z Kręgiem Ziemi.$B$BPomóż temu światu się uleczyć, $gprzyjacielu:przyjaciółko;.$B$BNa południowy wschód od Wioski Cienistego Księżyca – w sercu Doliny Cienistego Księżyca – znajdziesz miejsce zwane Ołtarzem Potępienia. Udaj się tam i porozmawiaj z Uzdrowicielem ziemi Torlokiem.', 'Porozmawiaj z Uzdrowicielem ziemi Torlokiem przy Ołtarzu Potępienia w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10683, 'koKR', 'Tablice Baa\'ri', 'Illidan rozkazał Złamanym z Popielnych Języków odkopać Ruiny Baa\'ri, daleko na północy. Bez wątpienia szukają draenejskich artefaktów – Baa\'ri kryło wiele relikwii, zanim Gul\'dan pogrzebał miasto w erupcji wulkanu. Musimy wykorzystać tę okazję i odzyskać Tablice Baa\'ri – starożytny tekst, który podobno skrywa tajemnice Świątyni Karaboru... miejsca, które znasz pewnie jako Czarną Świątynię.', 'Arkanista Thelis w Sanktuarium Gwiazd chce, żebyś $gzebrał:zebrała; 12 fragmentów tablic Baa\'ri – z ziemi i od robotników Popielnych Języków w Ruinach Baa\'ri.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Arkanisty Thelisa w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10684, 'koKR', 'Oronu Starszy', 'Według tablic w Baa\'ri przechowywano artefakt zwany Medalionem Karaboru. Otrzymywali je tylko najwyżsi rangą kapłani draenei, gdyż dawały swobodny wstęp do Świątyni Karaboru.$B$BMusimy się dowiedzieć, czy Popielne Języki odzyskały już medalion z Baa\'ri. Jego moc byłaby ogromną pomocą w walce z Illidanem.$B$BZastępca Akamy w Baa\'ri, Oronu Starszy, codziennie otrzymuje od niego pisemne rozkazy. Zdobądź je i przynieś mi.', 'Arkanista Thelis w Sanktuarium Gwiazd chce, żebyś $gzdobył:zdobyła; Rozkazy od Akamy od Oronu Starszego w Ruinach Baa\'ri.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Arkanisty Thelisa w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10685, 'koKR', 'Plugawiciele Popielnych Języków', 'Według listu Akamy wydobyto cztery fragmenty medalionu i przekazano je Plugawicielom Popielnych Języków. Ci straszliwi Złamani byli niegdyś potężnymi szamanami, a dziś kalają te same żywioły, które kiedyś czcili.$B$BHaaluma, Plugawiciela powietrza, znajdziesz na Przełęczy Otchłanioskrzydłych. Eykenena i Uylaru, Plugawicieli ziemi i ognia, widziano ostatnio w Spaczonych Dołach przy Ręce Gul\'dana. Lakaan, Plugawiciel wody, podobno przebywa w pobliżu Cypla Szramowijów.$B$BOdnajdź ich i zdobądź fragmenty medalionu.', 'Zdobądź cztery fragmenty medalionu od Haaluma, Eykenena, Lakaana i Uylaru i wróć do Arkanisty Thelisa w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Arkanisty Thelisa w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10686, 'koKR', 'Klatka Strażniczki', 'Fragmenty, które $gzdobyłeś:zdobyłaś;, to tylko połowa medalionu. Drugą połowę musiał zatrzymać przywódca Popielnych Języków, Akama.$B$BBoję się cię o to prosić, bo Akama jest zarówno zły, jak i przebiegły.$B$BPodobno on i Zaprzysiężeni Popielnych Języków – najpodlejsi i najbardziej brutalni z plemienia – prowadzą w Klatce Strażniczki salę tortur.$B$BChcę, żebyś $godnalazł:odnalazła; to przeklęte więzienie i $gustalił:ustaliła;, gdzie przebywa Akama. Jego zastępcą na miejscu jest Złamany imieniem Sanoru – przesłuchaj go, jeśli będzie trzeba.', 'Arkanista Thelis chce, żebyś $gwszedł:weszła; do Klatki Strażniczki, na południe od Ruin Baa\'ri, i $gwypytał:wypytała; Sanoru o miejsce pobytu Akamy.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10687, 'koKR', 'Plac Ćwiczeń Karaboru', 'Nasi zwiadowcy donoszą o masowym napływie rekrutów – krwawych elfów ze Słonecznej Furii – zmierzających do Ruin Karaboru. Zwykle oznaczałoby to zagrożenie czysto militarne, ale sądzimy, że dzieje się coś jeszcze.$B$BOpisy ich strojów i stylu walki podejrzanie przypominają samego Illidana. Nie chcę bić na alarm bez powodu, dlatego proszę cię, żebyś się tam $gudał:udała; i $gprzyniósł:przyniosła; mi ich broń. Wtedy ustalimy, czy moje obawy są bezpodstawne.', 'Larissa Słoneczne Uderzenie w Sanktuarium Gwiazd chce, żebyś $gzdobył:zdobyła; 8 glewii Słonecznej Furii od suplikantów łowców demonów i nowicjuszy łowców demonów w Ruinach Karaboru, na północny wschód od Sanktuarium Gwiazd.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Larissy Słonecznego Uderzenia w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10688, 'koKR', 'Konieczna dywersja', 'Broń jest prawdziwa, tak jak się obawialiśmy. Illidan szkoli łowców demonów w Ruinach Karaboru i musimy z tym skończyć.$B$BNie daj się zwieść ich nazwie, $N – ich moc zostanie użyta przeciw nam równie często jak przeciw demonom.$B$BIch czarnoksiężnicy przywołują i ujarzmiają demony, które służą do szkolenia nowicjuszy. Władca otchłani imieniem Azaloth okazał się zbyt silny, by go używać do szkolenia, i jest trzymany w stanie wygnania. Znajdź sposób, by uwolnić go przeciw jego strażnikom. To powinno dać nam potrzebny czas.', 'Larissa Słoneczne Uderzenie chce, żebyś $gwrócił:wróciła; do Ruin Karaboru i $gznalazł:znalazła; sposób, by nasłać Azalotha na jego strażników.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Larissy Słonecznego Uderzenia w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', 'Uwolnienie Azalotha', '', '', '', 0),
(10692, 'koKR', 'Varedis musi zostać powstrzymany', 'Oczywiście musimy zniszczyć tę księgę, ale dopiero wtedy, gdy użyjemy jej do zniszczenia Varedisa.$B$BJeśli mamy zamknąć tę akademię naśladowców Illidana, będziemy musieli rozprawić się nie tylko z Varedisem, ale też z trojgiem mistrzów spośród nocnych elfów, którzy mu pomagają: Alandien, Therasem i Netharelem.$B$BZbierz odpowiednie siły i wróć do Ruin Karaboru. Postępuj zgodnie ze wskazówkami Altruisa, jak pokonać Varedisa. Miejmy nadzieję, że jego plan się powiedzie – w przeciwnym razie... cóż, miło się z tobą pracowało.', 'Larissa Słoneczne Uderzenie chce, żebyś $gudał:udała; się do Ruin Karaboru i $gzabił:zabiła; Alandien, Therasa, Netharela i Varedisa. Gdy Varedis użyje Metamorfozy, użyj Księgi spaczonych imion, żeby go osłabić. Po wykonaniu zadania wróć z Księgą spaczonych imion do Larissy Słonecznego Uderzenia.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Larissy Słonecznego Uderzenia w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10702, 'koKR', 'Robota dla siepacza...', 'Wszystkie siły Hordy w tej okolicy wysłano do odpierania ataków Płonącego Legionu. To znaczy, że brakuje nam rąk do czarnej roboty.$B$BNaszym karawanom z zaopatrzeniem nieustannie zagraża tutejsza zwierzyna. Nie da się zboczyć z drogi nawet na pięć kroków, żeby nie wpaść na chimerę, spaczonego dzika albo nienaturalnie wielkiego skorpiona.$B$BRuszaj i oczyść Dolinę Cienistego Księżyca z tej krwiożerczej zwierzyny! Po prostu wybij wszystko!', 'Zwierzchnik Or\'barokh w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; 20 dzikich zwierząt Doliny Cienistego Księżyca.$B$BNależą do nich spaczone dziki, plugawoskrzydłe chimery i żaroskorupe szczypacze. Mogą być w dowolnych proporcjach.', '', 'Wróć do Zwierzchnika Or\'barokha w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10703, 'koKR', 'Załóż nakolanniki...', 'Czas zejść w błoto i się ubrudzić. A czego się $gspodziewałeś:spodziewałaś;? Trza się nauczyć chodzić, zanim się zacznie raczkować, nie? Eee, odwrotnie...$B$BW każdym razie wszystkie ręce mamy zajęte tłuczeniem tego śmiecia, co go na nas rzuca Płonący Legion. Tobie zatem przypada zaszczyt oczyszczenia Doliny Cienistego Księżyca z oszalałej zwierzyny.$B$BChwyć miecz, kostur, co tam lubisz, i ubij tyle zwierzyny, ile zobaczysz. Oczyści to drogę naszym karawanom z zaopatrzeniem!', 'Than Yoregar w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; 20 dzikich zwierząt Doliny Cienistego Księżyca.$B$BNależą do nich spaczone dziki, plugawoskrzydłe chimery i żaroskorupe szczypacze. Mogą być w dowolnych proporcjach.', '', 'Wróć do Thana Yoregara w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10705, 'koKR', 'Jasnowidz Udalo', 'Mam nadzieję, że nie wstrząśnie tobą wiadomość, iż fragmenty Medalionu Karaboru, które $godebrałeś:odebrałaś; moim sługom, to jedynie kopie.$B$B<Akama pokazuje ci na otwartej dłoni identyczny medalion.>$B$BRazem z moimi Zaprzysiężonymi jak najdłużej ukrywaliśmy ten sekret przed Illidanem. Wciąż jednak brakuje nam ostatniego fragmentu.$B$BUdalo przyszedł do mnie we śnie, by oznajmić, że go odnalazł. Niestety Kael\'thas więzi go w Arkatrazie, w Twierdzy Burz. Odnajdź go i dowiedz się, co wie.', 'Odnajdź Jasnowidza Udalo w Arkatrazie, w Twierdzy Burz.', '', '', '', '', '', '', 0),
(10706, 'koKR', 'Tajemniczy znak', 'Wygląda na to, że przed śmiercią Udalo napisał na podłodze pod sobą jedno słowo. Pismo jest ledwo czytelne, ale rozpoznajesz słowo Atam\'al.$B$BByć może Akama zrozumie znaczenie wiadomości od swojego pobratymca.', 'Wróć do Akamy w Klatce Strażniczki w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(10707, 'koKR', 'Taras Ata\'mal', 'Wiemy, że spaczone orki pod rozkazami Illidana strzegą na Tarasie Ata\'mal kryształu ata\'mal zwanego Sercem Furii. Ukrywają jego obecność za pomocą mrocznej magii, żeby nie znaleźli go Sha\'tar.$B$BPrzebij się na Taras Ata\'mal przed Czarną Świątynią i spójrz w niebo. Nad tarasem, poza twoim zasięgiem, będzie krążył Władca cieni Jęk Śmierci. Zanim zdobędziesz kryształ, będziesz $gmusiał:musiała; zabić jego i jego czarnoksiężników.$B$BNie będzie łatwo, $N. Życzę ci powodzenia.', 'Udaj się na szczyt Tarasu Ata\'mal w Dolinie Cienistego Księżyca i zdobądź Serce Furii. Po wykonaniu zadania wróć do Akamy w Klatce Strażniczki w Dolinie Cienistego Księżyca.', '', 'Wróć do Akamy w Klatce Strażniczki w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10744, 'koKR', 'Wieści o zwycięstwie', 'Musisz natychmiast zanieść wieść o naszym sukcesie Kurdranowi Dzikiemu Młotowi! Jego ludzie pod dowództwem Dowódcy skrzydła Nuainna walczą bez wytchnienia, by utrzymać Warownię Dzikiego Młota, a twój powrót z pewnością doda im ducha. Gdy zagrożenie ze strony Legionu zostało usunięte, Kurdran może wreszcie zająć się siłami Illidana. Nasza pozycja tutaj jest daleka od bezpiecznej, ale odnieśliśmy dziś wielkie zwycięstwo.', 'Wróć do Warowni Dzikiego Młota i porozmawiaj z Kurdranem Dzikim Młotem.', '', '', '', '', '', '', 0),
(10745, 'koKR', 'Wieści o zwycięstwie', 'Musisz natychmiast zanieść wieść o naszym sukcesie Zwierzchnikowi Or\'barokhowi! Teraz, gdy zmiażdżyliśmy Legion i zmietliśmy go z Doliny Cienistego Księżyca, zwierzchnik może zająć się innymi wrogami.$B$BGwardia Kor\'kronu nigdy się do tego nie przyzna, ale ucieszy się, że nie walczymy już na dwa fronty.', 'Wróć do Wioski Cienistego Księżyca i porozmawiaj ze Zwierzchnikiem Or\'barokhiem.', '', '', '', '', '', '', 0),
(10750, 'koKR', 'Szlak Podboju', 'Moi jeźdźcy wiatru przynieśli wieści, $N. Krwawe elfy Zaćmienia szykują coś wielkiego. Zaczęły gromadzić armie na Szlaku Podboju, daleko na południowym wschodzie – tuż przy Punkcie Zaćmienia.$B$BChcę, żebyś $gudał:udała; się na Szlak Podboju i $gocenił:oceniła; sytuację. Gdy to zrobisz, użyj tej rakietnicy, żeby dać znak jeźdźcowi wiatru. Jeden z nich sfrunie z nieba, żeby się z tobą spotkać. Powiedz mu, czego się $gdowiedziałeś:dowiedziałaś;, a przekaże ci kolejne rozkazy.', 'Udaj się na Szlak Podboju w Dolinie Cienistego Księżyca.', 'Odkryto Szlak Podboju', 'Użyj Rakietnicy Kor\'kronu, żeby dać znak Jeźdźcowi wiatru Kor\'kronu.$B$BJeśli zgubisz Rakietnicę Kor\'kronu i potrzebujesz nowej, porozmawiaj ze Zwierzchnikiem Or\'barokhiem.', '', '', '', '', 0),
(10751, 'koKR', 'Przełamanie szlaku', 'Będziemy potrzebowali więcej czasu. Polecę dalej naprzód z kilkoma innymi jeźdźcami wiatru. Mam nadzieję, że zdobędziemy więcej informacji. Od ciebie potrzebuję teraz, żebyś $goczyścił:oczyściła; drogę, a przede wszystkim żeby ich strzały nie leciały w naszą stronę!$B$BGdy przetrzebisz ich szeregi, wezwij jeźdźca wiatru rakietnicą Kor\'kronu.', 'Zabij 20 żołnierzy Zaćmienia, 10 kawalerzystów Zaćmienia i 10 zaklinaczy Zaćmienia.', '', 'Użyj Rakietnicy Kor\'kronu, żeby dać znak Jeźdźcowi wiatru Kor\'kronu.$B$BJeśli zgubisz Rakietnicę Kor\'kronu i potrzebujesz nowej, porozmawiaj ze Zwierzchnikiem Or\'barokhiem w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10759, 'koKR', 'Odnajdź dezertera', 'Mam wrażenie, że wszystkie elementy są na miejscu, ale nie umiem ich złożyć w sensowną całość.$B$BChyba najlepszym tropem będzie próba odnalezienia tego dezertera. Jeśli opuścił towarzyszy w obozie, to może zdołasz go przekonać, żeby pomógł nam zrozumieć, co knują arakkoa z Mrocznego Konklawe.$B$BZacznij go szukać przy drodze na Polach Magmy, na północnym zachodzie. To prawdopodobne miejsce, w którym mógł się schronić.', 'Odszukaj Parshaha na Polach Magmy i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(10760, 'koKR', 'Wrak Sketh\'lon', 'Wrak Sketh\'lon, tuż na wschód stąd, to niesamowite miejsce. Peoni są przekonani, że ciąży na nim klątwa.$B$BJest tu niewiele drzew, więc peoni nie mają wyboru i muszą zapuszczać się po drewno do ruin arakkoa. Duchy arakkoa polują na grupy robocze, wysysają z nich życie i zasilają nim swoją plugawą magię.$B$BMusimy się dowiedzieć, co napędza Mroczne Konklawe, i powstrzymać ich, zanim ich wpływy się rozszerzą. Przeszukaj Wrak Sketh\'lon w poszukiwaniu dowodów ich planów.', 'Odzyskaj od arakkoa z Mrocznego Konklawe przy Wraku Sketh\'lon strony 1, 2 i 3 Dziennika dowódcy Sketh\'lon i zanieś je Sierżantowi Kargrulowi w Wiosce Cienistego Księżyca.', '', 'Wróć do Sierżanta Kargrula w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10761, 'koKR', 'Odnajdź dezertera', 'Nie ma tu niczego, co by wyjaśniało, czemu duchy tych arakkoa pozostały na tym świecie ani skąd wzięło się ich pragnienie orczej krwi.$B$BChyba najlepszym tropem będzie próba odnalezienia dezertera, o którym wspomina dziennik. Jeśli opuścił towarzyszy w obozie, to może zdołasz go przekonać, żeby pomógł nam zrozumieć, co knują arakkoa z Mrocznego Konklawe.$B$BZacznij go szukać przy drodze przez Pola Magmy, na południowym wschodzie.', 'Odszukaj Parshaha na Polach Magmy i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(10765, 'koKR', 'Gdy zderzają się światy...', 'Na południowym krańcu Szlaku Podboju, przy stojącej karawanie, natknąłem się na coś, co wyglądało na spotkanie olbrzyma z kanclerzem krwawych elfów. Pewnie już $gzauważyłeś:zauważyłaś; na szlaku mniejsze olbrzymy. Coś tu jest nie tak, siepaczu.$B$BChcę, żebyś $gprzebił:przebiła; się na to spotkanie i $grozpędził:rozpędziła; towarzystwo. Zabierz z miejsca, co się da, a potem wezwij któregoś z nas rakietnicą.', 'Zabij Kanclerza Krwawego Liścia i Coroka Potężnego i zdobądź Rozkaz Illidana.', '', 'Użyj Rakietnicy Kor\'kronu, żeby dać znak Jeźdźcowi wiatru Kor\'kronu.$B$BJeśli zgubisz Rakietnicę Kor\'kronu i potrzebujesz nowej, porozmawiaj ze Zwierzchnikiem Or\'barokhiem w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10766, 'koKR', 'Punkt Inwazji: Kataklizm', 'Skoro mamy już dostęp do bazy Legionu w Punkcie Inwazji: Kataklizm, musimy wymyślić, jak ukrócić ich działania. Warownia Dzikiego Młota nie będzie bezpieczna, dopóki nie wymażemy Legionu z Doliny Cienistego Księżyca.$B$BWysłałem do punktu inwazji oddział zwiadowczy, który pomoże ci obmyślić plan zniszczenia zapasów Legionu. Wróć do Warowni Legionu i wejdź do teleportera, nad którym unoszą się zielone kryształy. Na miejscu spotka się z tobą Plexi.', 'Zamelduj się u Plexiego w Punkcie Inwazji: Kataklizm.', '', '', '', '', '', '', 0),
(10767, 'koKR', 'Punkt Inwazji: Kataklizm', 'Skoro mamy już dostęp do bazy Legionu w Punkcie Inwazji: Kataklizm, musimy wymyślić, jak ukrócić ich działania. Wioska Cienistego Księżyca nie będzie bezpieczna, dopóki nie wymażemy Legionu z doliny.$B$BWysłałem do punktu inwazji oddział zwiadowczy, który pomoże ci obmyślić plan zniszczenia zapasów Legionu. Wróć do Warowni Legionu i wejdź do teleportera, nad którym unoszą się zielone kryształy. Na miejscu spotka się z tobą Nakansi.', 'Zamelduj się u Nakansiego w Punkcie Inwazji: Kataklizm.', '', '', '', '', '', '', 0),
(10768, 'koKR', 'Tabardy Illidari', 'Jeźdźcy wiatru muszą wrócić do Wioski Cienistego Księżyca, żeby przygotować się do kolejnej fazy natarcia. Od ciebie potrzebuję teraz tabardów, które noszą te krwawe elfy.$B$BGdy zbierzesz dość tabardów, wezwij jeźdźca wiatru rakietnicą Kor\'kronu. Szykuj się na odrobinę szpiegowania!', 'Zbierz 10 tabardów Illidari.', '', 'Użyj Rakietnicy Kor\'kronu, żeby dać znak Jeźdźcowi wiatru Kor\'kronu.$B$BJeśli zgubisz Rakietnicę Kor\'kronu i potrzebujesz nowej, porozmawiaj ze Zwierzchnikiem Or\'barokhiem w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10769, 'koKR', 'Niezgoda w szeregach...', 'Badacz Tiorus był tak uprzejmy, że przygotował tę miksturę na ostateczne uderzenie. Wystarczy, że poleję nią tabard, który mi $gdostarczyłeś:dostarczyłaś;, a przesiąknie on esencją plugastwa Illidari.$B$BWeź zaczarowany tabard i udaj się na Pola Zaćmienia, na południowy zachód od Punktu Zaćmienia. Na miejscu użyj tabardu, żeby przemienić się w sługę Illidana. W przebraniu zabijaj oszalałe kolosy, które wędrują po polach. Uznają to za atak elfów Zaćmienia i zerwą z nimi wszelkie więzi!', 'Zabij 5 oszalałych kolosów w przebraniu krwawego elfa Illidari i wróć do Zwierzchnika Or\'barokha w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca. Będzie też chciał odzyskać swoją Rakietnicę Kor\'kronu.', '', 'Wróć do Zwierzchnika Or\'barokha w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', 'Oszalały kolos zabity w przebraniu', '', '', '', 0),
(10772, 'koKR', 'Szlak Podboju', 'Moi jeźdźcy gryfów wrócili z nowinami! Krwawe elfy Zaćmienia szykują coś wielkiego. Zaczęły gromadzić armie na Szlaku Podboju, na wschód stąd – tuż przy Punkcie Zaćmienia.$B$BChcę, żebyś $gudał:udała; się na Szlak Podboju i $gocenił:oceniła; sytuację. Gdy to zrobisz, użyj tej rakietnicy, żeby dać znak jeźdźcowi gryfa. Jeden z nich sfrunie z nieba, żeby się z tobą spotkać. Powiedz mu, czego się $gdowiedziałeś:dowiedziałaś;, a przekaże ci kolejne rozkazy.', 'Udaj się na Szlak Podboju w Dolinie Cienistego Księżyca.', 'Odkryto Szlak Podboju', 'Użyj Rakietnicy Dzikiego Młota, żeby dać znak Jeźdźcowi gryfa Dzikiego Młota.$B$BJeśli zgubisz Rakietnicę Dzikiego Młota i potrzebujesz nowej, porozmawiaj z Thanem Yoregarem w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10773, 'koKR', 'Przełamanie szlaku', 'Będziemy potrzebowali więcej czasu. Polecę dalej naprzód z kilkoma innymi jeźdźcami gryfów. Mam nadzieję, że zdobędziemy więcej informacji. Od ciebie potrzebuję teraz, żebyś $goczyścił:oczyściła; drogę, a przede wszystkim żeby ich strzały nie leciały w naszą stronę!$B$BGdy przetrzebisz ich szeregi, wezwij jeźdźca gryfa rakietnicą Dzikiego Młota.', 'Zabij 20 żołnierzy Zaćmienia, 10 kawalerzystów Zaćmienia i 5 synów Coroka.', '', 'Użyj Rakietnicy Dzikiego Młota, żeby dać znak Jeźdźcowi gryfa Dzikiego Młota.$B$BJeśli zgubisz Rakietnicę Dzikiego Młota i potrzebujesz nowej, porozmawiaj z Thanem Yoregarem w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10774, 'koKR', 'Krwawy elf + olbrzym = ???', 'Na południowym krańcu Szlaku Podboju, przy stojącej karawanie, natknąłem się na coś, co wyglądało na spotkanie olbrzyma z kanclerzem krwawych elfów. Co tu w ogóle robią olbrzymy? Coś tu jest nie tak, żołnierzu.$B$BChcę, żebyś $gprzebił:przebiła; się na to spotkanie i $grozpędził:rozpędziła; towarzystwo. Zabierz z miejsca, co się da, a potem wezwij któregoś z nas rakietnicą.', 'Zabij Kanclerza Krwawego Liścia i Coroka Potężnego i zdobądź Rozkaz Illidana.', '', 'Użyj Rakietnicy Dzikiego Młota, żeby dać znak Jeźdźcowi gryfa Dzikiego Młota.$B$BJeśli zgubisz Rakietnicę Dzikiego Młota i potrzebujesz nowej, porozmawiaj z Thanem Yoregarem w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10775, 'koKR', 'Tabardy Illidari', 'Jeźdźcy gryfów muszą wrócić do Warowni Dzikiego Młota, żeby przygotować się do kolejnej fazy natarcia. Od ciebie potrzebuję teraz tabardów, które noszą te krwawe elfy.$B$BGdy zbierzesz dość tabardów, wezwij jeźdźca gryfa rakietnicą Dzikiego Młota. Szykuj się na odrobinę szpiegowania!', 'Zbierz 10 tabardów Illidari.$B', '', 'Użyj Rakietnicy Dzikiego Młota, żeby dać znak Jeźdźcowi gryfa Dzikiego Młota.$B$BJeśli zgubisz Rakietnicę Dzikiego Młota i potrzebujesz nowej, porozmawiaj z Thanem Yoregarem w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10776, 'koKR', 'Niezgoda w szeregach...', 'Gnomus był tak uprzejmy, że przygotował tę miksturę na ostateczne uderzenie. Wystarczy, że poleję nią tabard, który mi $gdostarczyłeś:dostarczyłaś;, a przesiąknie on esencją plugastwa Illidari.$B$BWeź zaczarowany tabard i udaj się na Pola Zaćmienia, na południowy zachód od Punktu Zaćmienia. Na miejscu użyj tabardu, żeby przemienić się w sługę Illidana. W przebraniu zabijaj oszalałe kolosy, które wędrują po polach. Uznają to za atak elfów Zaćmienia i zerwą z nimi wszelkie więzi!', 'Zabij 5 oszalałych kolosów w przebraniu sługi Illidana i wróć do Thana Yoregara w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca. Będzie też chciał odzyskać swoją Rakietnicę Dzikiego Młota.', '', 'Wróć do Thana Yoregara w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', 'Oszalały kolos zabity w przebraniu', '', '', '', 0),
(10777, 'koKR', 'Totem Asghara', 'To, co $gprzeczytałeś:przeczytałaś; w dzienniku dowódcy, jest prawdą. Gdy orcza Horda gromadziła się pod wodzą Gul\'dana, mój lud postanowił się bronić przed tym zagrożeniem, uderzając na niego. Gul\'dan poznał ich zamiary i rzucił potężne zaklęcie, które zniszczyło nasze obozy i wypaczyło duchy moich braci.$B$BTrzeba ich powstrzymać, zanim rozpętają jeszcze większe zło. We Wraku Sketh\'lon, na północy, odszukaj Asghara i przynieś mi totem, który nosi. Z jego pomocą zaczniemy krzyżować plany Mrocznego Konklawe.', 'Przynieś Wojenny totem Sketh\'lon Parshahowi na Polach Magmy.', '', 'Wróć do Parshaha na Pola Magmy w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10778, 'koKR', 'Różdżka Lianthe', 'Sam totem nie ma dość mocy, by przeciwstawić się złowrogiej magii Mrocznego Konklawe.$B$BMożemy go jednak połączyć z innymi przedmiotami mocy i stworzyć kostur, który skupi energię. Nie zdołamy wyrwać moich pobratymców z otchłani ich zepsucia, ale możemy ich powstrzymać.$B$BJednym z przedmiotów potrzebnych do kostura jest Różdżka Lianthe, którą mają krwawe elfy w Punkcie Zaćmienia, na południowym wschodzie. Trzymają ją w pawilonie na najwyższym poziomie ruin i z pewnością jest pilnie strzeżona. Zachowaj ostrożność, $N.', 'Zdobądź Klucz Lianthe od któregoś z krwawych elfów w Punkcie Zaćmienia, otwórz nim Sejf Lianthe i zabierz Różdżkę Lianthe. Zanieś różdżkę Parshahowi na Polach Magmy.', '', 'Wróć do Parshaha na Pola Magmy w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10780, 'koKR', 'Pióra Sketh\'lon', 'Do kostura brakuje jeszcze ostatniego elementu. Musimy skierować jego moc przeciwko duchom Mrocznego Konklawe.$B$BZrobimy to, zbierając pióra rozrzucone po ziemi w Obozie Sketh\'lon i wykorzystując je w kosturze. Obóz leży na południu, na wschód od Warowni Dzikiego Młota.$B$BMagia Gul\'dana doszczętnie zniszczyła moich pobratymców, zostawiając tylko ich duchy, ale na tym się nie skończyło. Magia pożywiła się zaklęciem, które przygotowywali arakkoa, i wykuła złowrogą siłę, która pochłonęła duchy.', 'Zbierz 8 piór Sketh\'lon i przynieś je Parshahowi na Polach Magmy.', '', 'Wróć do Parshaha na Pola Magmy w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10782, 'koKR', 'Nasycenie nakrycia głowy', 'Kostur jest prawie gotowy!$B$BZostało tylko nasycić jego głowicę mocą płynącą z ech Gul\'dana w tym przeklętym miejscu. Na wschodzie, w pobliżu Spaczonych Dołów i na południe od Kuźni Śmierci, leży Ołtarz Potępienia.$B$BUwięzione są tam fragmenty przeszłości Gul\'dana. Gdy wniesiesz niedokończone nakrycie głowy – głowicę kostura – w okolice ołtarza, nie zdziw się, jeśli niektóre z tamtejszych istot na nie zareagują. Będziesz nieść niebezpieczny przedmiot silnie związany z kataklizmem.', 'Załóż Niedokończone nakrycie głowy, udaj się do Ołtarza Potępienia i użyj go, stojąc w pobliżu Gul\'dana. Gdy nakrycie głowy zostanie zasilone, wróć do Parshaha na Polach Magmy.', '', 'Wróć do Parshaha na Pola Magmy w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10793, 'koKR', 'Dziennik Val\'zareqa: zapowiedzi wojny', 'Ten dziennik opisuje ostatnie poczynania armii Illidana. Wyjaśnia też, dlaczego Val\'zareq paradował po Szlaku Podboju. To on osobiście pojmał wielkiego generała Sha\'tar.$B$BGenerał jest przetrzymywany w posterunku zwanym Karmazynową Strażnicą, na południowym krańcu Szlaku Podboju. Jego uwięzienie powierzono tajemniczemu stronnictwu, które nazywa się Karmazynowym Symbolem. Jeśli zamierzasz to zbadać, rozsądnie będzie zabrać sojuszników.', 'Odnajdź Marcusa Auraliona, Wielkiego generała Sha\'tar, w Karmazynowej Strażnicy.$B$BSzukaj go w kryształowym więzieniu.', '', '', '', '', '', '', 0),
(10804, 'koKR', 'Życzliwość', 'Coś je przeraziło.$B$B<Mordenai wskazuje na smokowce Otchłani krążące w górze.>$B$BNie zlatują nawet, żeby się pożywić. Widziałem, jak kilka spadło na ziemię, martwe z wycieńczenia, zanim jeszcze ich ciała uderzyły o grunt.$B$BMusimy je ratować! Ich naturalną zdobyczą są obdzieracze Skalnego Pazura, których znajdziesz przy kryształach. Zabijaj obdzieraczy i zabieraj ich truchła. Połóż truchło na polu i stój zupełnie nieruchomo. Dopóki nie wykonasz żadnego agresywnego ruchu, nie zaatakują cię.', 'Mordenai na Polach Otchłanioskrzydłych w Dolinie Cienistego Księżyca chce, żebyś $gnakarmił:nakarmiła; 8 dorosłych smokowców otchłanioskrzydłych.', '', 'Wróć do Mordenaia na Pola Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', 'Nakarmiony dorosły smokowiec otchłanioskrzydły', '', '', '', 0),
(10807, 'koKR', 'Złamani z Popielnych Języków', 'Wśród wszystkich Złamanych najbardziej budzi strach plemię Popielnych Języków. Tworzą je najokrutniejsi i najbardziej krwiożerczy spośród nich, wybrani osobiście przez samego Akamę. Są równie zajadli i bezwzględni jak każda naga, demon czy krwawy elf w armii Illidana, a w Ruinach Baa\'ri, na północy, rozmieszczono ich w wielkiej liczbie. Udaj się tam i przerzedź ich szeregi, zanim zdążą nas zaatakować.', 'Varen Odzyskiwacz chce, żebyś $gudał:udała; się do Ruin Baa\'ri i $gzabił:zabiła; 3 treserów Popielnych Języków, 4 wojowników Popielnych Języków i 6 szamanów Popielnych Języków.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Varena Odzyskiwacza w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10808, 'koKR', 'Pokrzyżuj plany Mrocznego Konklawe', 'Duchy Mrocznego Konklawe chcą przywołać pradawne i potężne zło za pomocą rytuału odprawianego przy jeziorkach lawy na południe od Obozu Sketh\'lon.$B$BMagia Gul\'dana splotła się z ich własną i dała im moc, by pomogli tej istocie zjawić się w naszym świecie! Nie możemy do tego dopuścić, $N. Śmierć i zniszczenie, jakie by sprowadziła, są niewyobrażalne!$B$BZanieś kostur na miejsce przywołania i użyj jego magii, by raz na zawsze powstrzymać Mroczne Konklawe!', 'Zabij rytualistów Mrocznego Konklawe i użyj Kostura Parshaha, by przerwać rytuał przywołania Mrocznego Konklawe, a potem wróć do Parshaha na Polach Magmy.', '', 'Wróć do Parshaha na Pola Magmy w Dolinie Cienistego Księżyca.', 'Przerwanie rytuału przywołania Mrocznego Konklawe', '', '', '', 0),
(10811, 'koKR', 'Odszukaj Neltharaku', 'Ich patron szybuje wysoko w górze, $N. Może życzliwość, którą $gokazałeś:okazałaś; jego dzieciom, poruszyła jego serce. Odszukaj Neltharaku i pozyskaj jego pomoc. Razem może zdołacie zaradzić niedoli smokowców otchłanioskrzydłych.$B$B<Mordenai wskazuje na niebo.>$B$BLeć wysoko, $gprzyjacielu:przyjaciółko;...', 'Odszukaj Neltharaku, patrona Stada Otchłanioskrzydłych.', '', '', '', '', '', '', 0),
(10814, 'koKR', 'Opowieść Neltharaku', 'Mam informacje, które mogą ci się przydać. Wysłuchaj, proszę, tego, co mam ci do powiedzenia.', 'Porozmawiaj z Neltharaku i wysłuchaj jego opowieści.', 'Opowieść Neltharaku', 'Wróć do Neltharaku na Pola Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10815, 'koKR', 'Dziennik Val\'zareqa: zapowiedzi wojny', 'Ten dziennik opisuje ostatnie poczynania armii Illidana. Wyjaśnia też, dlaczego Val\'zareq paradował po Szlaku Podboju. To on osobiście pojmał wielkiego generała Sha\'tar.$B$BGenerał jest przetrzymywany w posterunku zwanym Karmazynową Strażnicą, na południowym krańcu Szlaku Podboju. Jego uwięzienie powierzono tajemniczemu stronnictwu, które nazywa się Karmazynowym Symbolem. Jeśli zamierzasz to zbadać, rozsądnie będzie zabrać sojuszników.', 'Odnajdź Marcusa Auraliona, Wielkiego generała Sha\'tar, w Karmazynowej Strażnicy.', '', '', '', '', '', '', 0),
(10816, 'koKR', 'Odzyskanie świętej ziemi', 'Dobrze ci poszło ze Złamanymi w Baa\'ri, $N. Zobaczmy, jak sobie poradzisz z najbardziej budzącą strach armią Illidana.$B$BSpaczone orki z klanu Cienistego Księżyca zajmują Taras Ata\'mal, niegdyś bardzo święte miejsce, gdzie podczas duchowych obrzędów używano kryształów ata\'mal.$B$BMieliśmy powody sądzić, że gdzieś w pobliżu ukrywają prawdziwy kryształ ata\'mal, ale nasze wróżby niczego nie wykazały. Tak czy inaczej, spaczone orki panoszą się na świętej ziemi draenei i trzeba się z nimi rozprawić.', 'Obrońca Aluumen chce, żebyś $gzabił:zabiła; 8 pogromców Cienistego Księżyca, 8 wybrańców Cienistego Księżyca i 4 mrocznych tkaczy Cienistego Księżyca.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Obrońcy Aluumena przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10817, 'koKR', 'Wielki odwet', 'Dobrze ci poszło ze Złamanymi z Popielnych Języków, $N. Mam dla ciebie kolejne wyzwanie, jeśli mu podołasz.$B$BNiedawno Sanktuarium Gwiazd padło ofiarą potężnego ataku spaczonych orków Illidana.$B$BUstaliliśmy, że dokonały go orki z klanu Cienistego Księżyca, które zajmują Taras Ata\'mal.$B$BPokaż im, że z Widzącymi nie ma żartów.', 'Varen Odzyskiwacz chce, żebyś $gzabił:zabiła; 8 pogromców Cienistego Księżyca, 8 wybrańców Cienistego Księżyca i 4 mrocznych tkaczy Cienistego Księżyca.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Varena Odzyskiwacza w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10824, 'koKR', 'Sygnety Słonecznej Furii', 'Przetrwanie Widzących zależy od tego, czy zwerbujemy więcej ochotników niż Kael\'thas. Każdy pielgrzym z Quel\'Thalas, który przyłącza się do niego, przybliża go do zwycięstwa. W naszym przypadku jest tak samo.$B$BWkrótce jednak zabraknie nam rekrutów i wszystko sprowadzi się do tego, która strona szybciej wybije drugą. Dowiedź swojej wartości Widzącym i przynieś mi sygnety Słonecznej Furii noszone przez wysoko postawione krwawe elfy sprzymierzone z Kael\'thasem i Illidanem. Znajdziesz je w Punkcie Zaćmienia na zachodzie i w Ruinach Karaboru na północnym wschodzie.', 'Magini bojowa Vyara w Sanktuarium Gwiazd chce, żebyś $gprzyniósł:przyniosła; jej 10 sygnetów Słonecznej Furii.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Magini bojowej Vyary w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10836, 'koKR', 'Przeniknięcie do Fortecy Smoczych Paszcz', 'Potrzebuję czasu, by obmyślić plan ratunku dla moich dzieci i mojej towarzyszki. Ty zapewnisz mi ten czas, $gśmiertelniku:śmiertelniczko;.$B$BWyrusz do Fortecy Smoczych Paszcz na wschodnim skraju Pól Otchłanioskrzydłych i wybij wszystkie orki Smoczych Paszcz, jakie znajdziesz. Wywołany tym chaos i zamęt powinien poważnie pokrzyżować ich plany.$B$BOstrzegam cię: niektórzy z moich pobratymców są już straceni – Smocze Paszcze splugawiły ich umysły. Dla nich jedynym wyjściem jest śmierć. Masz moje pozwolenie, by i ich życiu położyć kres.', 'Neltharaku, szybujący wysoko nad Polami Otchłanioskrzydłych w Dolinie Cienistego Księżyca, chce, żebyś $gzabił:zabiła; 15 orków Smoczych Paszcz.$B$BWystarczy dowolny ork Smoczych Paszcz w Fortecy Smoczych Paszcz.', '', 'Wróć do Neltharaku na Pola Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10837, 'koKR', 'Na Występ Otchłanioskrzydłych!', 'Sądzę, że zdołam nasycić kryształy pnącza Otchłani własną esencją. Moc zawarta w tak nasyconych kryształach powinna wystarczyć, by wyrwać zniewolone smokowce z uścisku ich panów.$B$BUdaj się na Występ Otchłanioskrzydłych, wyspę u strzaskanego skraju Doliny Cienistego Księżyca, na południowym wschodzie. To na Występie Otchłanioskrzydłych znajdziesz kryształy pnącza Otchłani. Wróć do mnie, gdy zbierzesz tyle kryształów, ile zmieścisz w torbach.$B$BI jeszcze jedno, $N: strzeż się Smoczych Paszcz, które zamieszkują teraz wyspę.', 'Neltharaku, szybujący wysoko nad Polami Otchłanioskrzydłych w Dolinie Cienistego Księżyca, chce, żebyś $gzebrał:zebrała; 12 kryształów pnącza Otchłani na Występie Otchłanioskrzydłych.$B', '', 'Wróć do Neltharaku na Pola Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10854, 'koKR', 'Moc Neltharaku', 'Weź ten zaczarowany kryształ pnącza Otchłani i wróć do Fortecy Smoczych Paszcz. Na miejscu odszukaj zniewolone smokowce i przywołaj magię kryształu. Popłynie z niego moja własna energia, dzięki której smokowce zerwą więzy łączące je z porywaczami. Gdy zobaczysz, że smokowiec się uwolnił, pomóż mu pokonać jego porywacza! Po niewoli na pewno będzie osłabiony.$B$BUwolnij wszystkie, jakie znajdziesz, i wróć do mnie, $N.', 'Neltharaku, szybujący wysoko nad Polami Otchłanioskrzydłych w Dolinie Cienistego Księżyca, chce, żebyś $guwolnił:uwolniła; 5 zniewolonych smokowców otchłanioskrzydłych.', '', 'Wróć do Neltharaku na Pola Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', 'Uwolniony zniewolony smokowiec otchłanioskrzydły', '', '', '', 0),
(10858, 'koKR', 'Karynaku', 'Wstyd mi znów prosić cię o pomoc, $N, ale jesteś jedyną nadzieją mojego stada. Bez mojej towarzyszki ród Otchłanioskrzydłych może całkiem wyginąć.$B$BDostań się na szczyt Fortecy Smoczych Paszcz i odszukaj Karynaku.$B$BBędziemy krążyć w górze. Jeśli w ich obronie pojawi się wyłom, potęga Otchłanioskrzydłych sfrunie ci na pomoc.$B', 'Odszukaj Karynaku w Fortecy Smoczych Paszcz.', '', '', '', '', '', '', 0),
(10866, 'koKR', 'Zuluhed Obłąkany', 'Kryje się w moich myślach, $gśmiertelniku:śmiertelniczko;. Czeka, aż się złamię... aż ugnę się przed jego wolą.$B$BI to go zgubi. Wezwę go. Powiem mu, że zrobię, o co prosi. Gdy się zjawi, zabij go i zabierz klucz!$B$BWiedz jedno: Zuluhed to stary ork o nieznanych mocach. Illidan z pewnością jeszcze go wzmocnił. Robiąc to, o co proszę, ryzykujesz dla mnie życie. Czy na pewno chcesz ponieść taką ofiarę?', 'Zabij Zuluheda Obłąkanego i zdobądź Klucz Zuluheda. Użyj Klucza Zuluheda na Łańcuchach Zuluheda, żeby uwolnić Karynaku.', '', 'Wróć do Karynaku w Fortecy Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Uwolniona Karynaku', '', '', '', 0),
(10870, 'koKR', 'Sprzymierzeniec Otchłanioskrzydłych', 'Pozwól, że zabiorę cię z powrotem do Mordenaia. Jestem pewna, że chce cię znów zobaczyć.', 'Pozwól, by Karynaku zabrała cię z powrotem do Mordenaia na Polach Otchłanioskrzydłych.', '', '', '', '', '', '', 0),
(10871, 'koKR', 'Sprzymierzeniec Otchłanioskrzydłych', 'Pozwól, że zabiorę cię z powrotem do Mordenaia. Jestem pewna, że chce cię znów zobaczyć.', 'Pozwól, by Karynaku zabrała cię z powrotem do Mordenaia na Polach Otchłanioskrzydłych.', '', '', '', '', '', '', 0),
(10872, 'koKR', 'Zuluhed Obłąkany', 'Kryje się w moich myślach, $gśmiertelniku:śmiertelniczko;. Czeka, aż się złamię... aż ugnę się przed jego wolą.$B$BI to go zgubi. Wezwę go. Powiem mu, że zrobię, o co prosi. Gdy się zjawi, zabij go i zabierz klucz!$B$BWiedz jedno: Zuluhed to stary ork o nieznanych mocach. Illidan z pewnością jeszcze go wzmocnił. Robiąc to, o co proszę, ryzykujesz dla mnie życie. Czy na pewno chcesz ponieść taką ofiarę?', 'Zabij Zuluheda Obłąkanego i zdobądź Klucz Zuluheda. Użyj Klucza Zuluheda na Łańcuchach Zuluheda, żeby uwolnić Karynaku.', '', 'Wróć do Karynaku w Fortecy Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Uwolniona Karynaku', '', '', '', 0),
(10944, 'koKR', 'Tajemnica zagrożona', 'Jeszcze raz dziękuję, $N. Znam twoje imię. Akama powierzył ci swoje plany, więc i ja ci zaufam.$B$BNagi odkryły, że działam przeciwko Illidanowi, i torturami próbowały zmusić mnie do mówienia. Nic im nie powiedziałem – sam Akama nauczył mnie panować nad bólem przez medytację.$B$BIllidan kazał nagom przyprowadzić mnie do siebie. Przejrzałby moje ciało na wskroś, aż do najgłębszych tajemnic mojej duszy.$B$BTrzeba ostrzec Akamę. Nasze plany są zagrożone!', 'Udaj się do Klatki Strażniczki w Dolinie Cienistego Księżyca i porozmawiaj z Akamą.', '', '', '', '', '', '', 0),
(10946, 'koKR', 'Podstęp Popielnych Języków', 'Ofiara Oluma była ogromna. Sam nigdy nie poprosiłbym go, by oddał życie. Ale stało się.$B$BJeśli mamy uśpić czujność Illidana, musimy – przynajmniej na razie – spełniać jego rozkazy.$B$BDowodzę ogromną armią Popielnych Języków, ale – poza Zaprzysiężonymi – nikomu nie można ufać.$B$BTo ty wykonasz zadanie, którego żąda Illidan. Weź ten kaptur; jest magiczny. Każdemu, kto zobaczy, jak zabijasz feniksa Kaela, Al\'ara, wydasz się jednym z moich ludzi.', 'Udaj się do Twierdzy Burz i zabij Al\'ara, mając na sobie Kaptur Popielnych Języków. Po wykonaniu zadania wróć do Akamy w Dolinie Cienistego Księżyca.', 'Podstęp Popielnych Języków', '', '', '', '', '', 0),
(10947, 'koKR', 'Artefakt z przeszłości', 'Dzięki tobie Illidan skupił teraz uwagę na Kael\'thasie. Nadszedł czas, byśmy wykonali nasz ruch.$B$BMiałem wizję artefaktu, który pomoże nam w ostatecznej rozgrywce – filakterii lisza znanego jako Zimowy Chłód. Niestety jej moc przepadła na zawsze po jego klęsce w Bitwie o Górę Hyjal.$B$BByć może jest jednak sposób, by odzyskać ten artefakt. Legenda mówi o miejscu w Azeroth strzeżonym przez brązowe smoki... miejscu, gdzie spotykają się przeszłość i teraźniejszość. Tam znajdziesz to, czego szukamy.', 'Udaj się do Jaskiń Czasu w Tanaris i zdobądź dostęp do Bitwy o Górę Hyjal. Gdy będziesz w środku, pokonaj Rage\'a Zimowego Chłodu i przynieś Filakterię przesuniętą w czasie Akamie w Dolinie Cienistego Księżyca.', '', 'Wróć do Akamy w Klatce Strażniczki w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10957, 'koKR', 'Odkupienie Popielnych Języków', 'Gdy Illidan zyskał wierność Złamanych, Akama był najmądrzejszy z nas. Wiedział, że otwarte wystąpienie przeciw Zdrajcy doprowadziłoby do zagłady naszej rasy.$B$BZamiast tego w najgłębszej tajemnicy knuł i planował właśnie na tę chwilę. Porażka byłaby katastrofą... nie tylko dla Akamy, nie tylko dla Złamanych, ale dla całej Rubieży. Nikt, kto był tak blisko Illidana, nigdy nie zdołał zadać mu tak straszliwego ciosu.$B$BPomóż Akamie uwolnić jego duszę, a zapewni ci dostęp do sanktuarium Illidana.', 'Pomóż Akamie odzyskać władzę nad własną duszą, pokonując Widmo Akamy w Czarnej Świątyni. Po wykonaniu zadania wróć do Jasnowidza Kanaia.', '', 'Wróć do Jasnowidza Kanaia w Czarnej Świątyni.', '', '', '', '', 0),
(10958, 'koKR', 'Odszukaj Popielne Języki', '<Gdy spoglądasz na Xi\'ri, twój umysł się skupia, a wola krzepnie. Twoja praca tutaj nie jest skończona; musisz wejść do Czarnej Świątyni i odnaleźć zwolenników Akamy.>$B$B<Wiele zależy od powodzenia Akamy.>', 'Odnajdź Zaprzysiężonych Akamy w Czarnej Świątyni.', '', '', '', '', '', '', 0),
(10959, 'koKR', 'Upadek Zdrajcy', 'Gdy przyboczni Illidana zostaną pokonani, Akama zdoła wyważyć drzwi do sanktuarium Illidana. Bądź $ggotów:gotowa; wprowadzić do środka swój oddział, gdy tylko Akama to zrobi.$B$BWciąż nie wiemy, co się stało z Maiev, ale musimy działać bez niej.$B$BMam nadzieję, że twój oddział sprosta zadaniu. Illidan nie ucieszy się na widok Akamy.', 'Jasnowidz Kanai chce, żebyś $gpokonał:pokonała; Illidana w Czarnej Świątyni.', '', 'Wróć do Jasnowidza Kanaia w Czarnej Świątyni.', '', '', '', '', 0),
(10985, 'koKR', 'Odwrócenie uwagi dla Akamy', '<Xi\'ri pulsuje światłem, a otaczające go siły Aldorów i Widzących wykonują jego rozkazy. Armia Xi\'riego jest gotowa odepchnąć siły Illidana i odwrócić uwagę na rzecz Akamy. Naaru czeka, aż poprosisz o rozpoczęcie ataku.>', 'Dopilnuj, by Akama i Maiev weszli do Czarnej Świątyni w Dolinie Cienistego Księżyca, gdy siły Xi\'riego odwrócą uwagę wroga.', 'Pomóż Akamie i Maiev wejść do Czarnej Świątyni.', 'Wróć do Xi\'riego w Ruinach Baa\'ri w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11012, 'koKR', 'Krwawa przysięga Otchłanioskrzydłych', '', '', '', '', '', '', '', '', 0),
(11013, 'koKR', 'W służbie Illidari', 'Występ Otchłanioskrzydłych... To, co niegdyś było bezpiecznym schronieniem Otchłanioskrzydłych, jest teraz domem Smoczych Paszcz. Choć orki zawładnęły naszym terytorium, nasza magia wciąż jest tam silna. Dość silna, by ukryć twoją prawdziwą tożsamość i pozwolić ci przeniknąć w szeregi Smoczych Paszcz.$B$BPrzygotowałem dla ciebie list, który przedstawisz ich przywódcy, nadrządcy Mor\'ghorowi. Leć prosto w paszczę wroga i odszukaj Obóz Smoczych Paszcz, by rozpocząć nowe życie jako spaczony ork w służbie Illidana Burzogniewnego.', 'Udaj się na Występ Otchłanioskrzydłych i dostarcz dokumenty służbowe Illidari nadrządcy Mor\'ghorowi w Obozie Smoczych Paszcz.$B', '', '', '', '', '', '', 0),
(11014, 'koKR', 'Wejście poganiacza', '<Mor\'ghor zgniata list służbowy i odrzuca go na bok.>$B$BDobra, $gsiepaczu:siepaczko;, zacznijmy od początku. Jeśli chcesz wstąpić do mojej ukochanej armii Smoczych Paszcz, musisz pracować. Tu, na występie, pracują wszyscy. Weź się do roboty, nie spartacz jej, a zobaczę, czy później nie znajdzie się dla ciebie coś ciekawszego.$B$BIdź pogadać z poganiaczem Varkule\'em Smoczym Oddechem. Stoi na środku osady. Oceni twoje umiejętności i przydzieli ci robotę, jaką uzna za stosowną.$B$BA teraz zejdź mi z oczu!', 'Porozmawiaj z poganiaczem Varkule\'em Smoczym Oddechem w Obozie Smoczych Paszcz.', '', '', '', '', '', '', 0),
(11015, 'koKR', 'Kryształy Otchłanioskrzydłych', 'Do niczego się nie nadajesz? Nie szkodzi. Nawet takie tępaki jak ty można tu do czegoś wykorzystać. Po prostu znajdź stwory na występie i je pozabijaj. Czasem mają przy truchłach kryształy Otchłani. Zbierz je i przynieś mi, a uznam twoje dzisiejsze zlecenie za wykonane.$B', 'Poganiacz Varkule Smoczy Oddech w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 30 kryształów Otchłanioskrzydłych.', '', 'Wróć do poganiacza Varkule\'a Smoczego Oddechu na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11016, 'koKR', 'Skóra obdzieracza z Kopalni Otchłani', '$GSkórnik:Skórniczka;, co? No to będziesz tu $gmiał:miała; co obdzierać ze skóry! Szukaj obdzieraczy wokół kryształowych formacji. Ubij ich i zedrzyj z nich skóry. Czasem trafi się skóra warta zachowania. Takie przynoś do mnie.', 'Poganiacz Varkule Smoczy Oddech w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 35 skór obdzieraczy z Kopalni Otchłani.', '', 'Wróć do poganiacza Varkule\'a Smoczego Oddechu na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11017, 'koKR', 'Pyłek otchłaniopyłu', '$GZbieracz:Zbieraczka; kwiatków?! Przezabawne... Niestety nasi magowie i szamani potrzebują twoich usług. Krzewy otchłaniopyłu, które rosną na tym występie, mają szczególny pyłek, podobno bardzo przydatny w ich magicznych sprawkach. Przynieś mi to paskudztwo, a uznam twoje zlecenie za wykonane.', 'Poganiacz Varkule Smoczy Oddech w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 40 porcji pyłku otchłaniopyłu.', '', 'Wróć do poganiacza Varkule\'a Smoczego Oddechu na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11018, 'koKR', 'Ruda otchłanitu', '$GGórnik:Górniczka;!$B$B<Varkule salutuje.>$B$BOrk w moim guście! Varkule też tak zaczynał – od kopania! Nie ma nic lepszego niż ubrudzić sobie ręce w kopalni, co?$B$BA teraz ruszaj i znajdź te złoża otchłanitu. Wyeksploatuj je do cna i przynieś mi rudę.', 'Poganiacz Varkule Smoczy Oddech w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 40 bryłek rudy otchłanitu.', '', 'Wróć do poganiacza Varkule\'a Smoczego Oddechu na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11019, 'koKR', 'Twój przyjaciel w środku', '', '', '', '', '', '', '', '', 0),
(11020, 'koKR', 'Powolna śmierć', 'Smocze Paszcze mają peony przy niemal każdej kryształowej formacji tutaj, w górze. Choć otwarte wybijanie ich ściągnęłoby na ciebie o wiele za dużo niepożądanej uwagi, jest sposób, by przerzedzić ich szeregi i nie wzbudzić podejrzeń Mor\'ghora.$B$BWyrusz na dzikie tereny Doliny Cienistego Księżyca i zabijaj skażone zwierzęta. Odbierz im zepsute gruczoły Spaczenia. Użyj tych gruczołów z baraniną, którą ci dam, w pobliżu peonów. Wystarczy jeden kęs, a śmiertelnie się pochorują!', 'Yarzill Najemnik w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gużył:użyła; baraniny Yarzilla razem z gruczołami Spaczenia, by otruć 12 obozowisk peonów Smoczych Paszcz.$B', '', 'Wróć do Yarzilla Najemnika na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', 'Otrute obozowisko peonów Smoczych Paszcz', '', '', '', 0),
(11035, 'koKR', 'Nie takie przyjazne niebo...', 'Na północno-wschodnim krańcu tej wyspy znajduje się przystań, gdzie pakuje się i wysyła kryształy oraz relikty Otchłanioskrzydłych. Przewoźnicy Smoczych Paszcz transportują towary z przystani do Fortecy Smoczych Paszcz, a wyniesieni Smoczych Paszcz strzegą ziemi przed ewentualnymi napastnikami.$B$BZostaje ci więc jedna luka, by uderzyć w Smocze Paszcze: Podniebny Szlak Smoczych Paszcz.$B$BPoleć na strzaskane wysepki Podniebnego Szlaku Smoczych Paszcz i zaatakuj z zasadzki przewoźników, którzy korzystają z tej trasy. Odzyskaj nasze skradzione relikty!', 'Yarzill Najemnik w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; 10 reliktów Otchłanioskrzydłych.', '', 'Wróć do Yarzilla Najemnika na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11041, 'koKR', 'Niedokończona robota...', 'W imię naszego wielkiego pana... Ku chwale Illidana!$B$BZ rozkazu nadrządcy Mor\'ghora należy zabezpieczyć wielki płaskowyż Występu Otchłanioskrzydłych. Odkąd wszystkie smokowce otchłanioskrzydłe zostały pojmane lub wypędzone z tych ziem, obdzieracze skalni panoszą się bez przeszkód i zagrażają wydobyciu kryształów.$B$BZniszczyć je wszystkie, ich matkę legowiska i jej towarzysza, Arvoara.$B$BMor\'ghor tak rozkazuje!$B$B<Wygląda na to, że temu orkowi nie udało się zdobyć płaskowyżu. Czas udowodnić Mor\'ghorowi swoją wartość!>', 'Zabij 10 nadkopalnianych obdzieraczy i Barash Matkę Legowiska. Jeśli ci się uda, wróć do nadrządcy Mor\'ghora w Obozie Smoczych Paszcz.', '', 'Wróć do nadrządcy Mor\'ghora na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11049, 'koKR', 'Wielkie polowanie na jaja Otchłanioskrzydłych', 'Jeśli podczas wędrówek natrafisz na jaja Otchłanioskrzydłych, przynieś je do mnie.$B$BOstrzegam, jajo Otchłanioskrzydłych to rzadkie odkrycie. Nie zniechęcaj się, jeśli żadnego nie znajdziesz. Te Smocze Paszcze bardzo skrupulatnie zebrały większość z nich i wysłały w nieznane strony.$B$BJaja można znaleźć przy stworach na wyspie, w pobliżu kryształowych formacji, w kopalniach, a nawet w złożu otchłanitu czy krzewie otchłaniopyłu.$B$BNie wychylaj się. Nie potrzeba nam, żeby Mor\'ghor zwęszył, co robisz.', 'Yarzill Najemnik w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; jajo Otchłanioskrzydłych.', '', 'Wróć do Yarzilla Najemnika na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11050, 'koKR', 'Przyjmujemy wszystkie jaja', '', '', '', 'Wróć do Yarzilla Najemnika w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11053, 'koKR', 'Powstań, nadzorco!', 'Rzadko się zdarza, żeby peon przeżył tak długo jak ty. Jeszcze rzadziej peon wydostaje się z samego dna i zdobywa nowy stopień.$B$B<Varkule klaszcze.>$B$BNadrządca cię wzywa, $gsiepaczu:siepaczko;. Bez wątpienia czeka cię nowy stopień.', 'Porozmawiaj z nadrządcą Mor\'ghorem w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11054, 'koKR', 'Ty i nadzorowanie: jak dokonywać właściwych wyborów', 'A więc to ty jesteś $gnowym nadzorcą:nową nadzorczynią;, co? No to każdy porządny nadzorca potrzebuje jednej rzeczy: odpowiedniej broni dyscyplinarnej. Zanim ruszysz przemówić tym peonom do rozumu, musisz mieć swoje „cacko”. Każdy nadzorca sam zbiera materiały na własne „cacko” i ty nie będziesz wyjątkiem.$B$BPotrzebuję sękatej skóry i utwardzonej skóry Tyrantusa. Tyrantusa znajdziesz w Ekokopule Dalekiego Pola, w północnej części Burzy Otchłani.', 'Główny nadzorca Błotobryła w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 10 kawałków sękatej skóry i 1 utwardzoną skórę Tyrantusa.$B', '', 'Wróć do głównego nadzorcy Błotobryły na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11055, 'koKR', 'Butorang: lek na pospolitego leniwego peona', 'To jest twój butorang. Jest wiele takich jak on, ale ten jest twój.$B$BJako nadzorca będziesz używać tego butorangu, by siać strach w sercach krnąbrnych peonów. Właściwe użycie butorangu wpoi im posłuszeństwo i zapewni uległość.$B$BRuszaj na kryształowe pola i ukarz każdego peona, który się obija. Pokaż im potęgę butorangu!$B', 'Główny nadzorca Błotobryła w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gzdyscyplinował:zdyscyplinowała; 20 leniwych peonów Smoczych Paszcz. Musisz też zwrócić swój butorang.', '', 'Wróć do głównego nadzorcy Błotobryły na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', 'Zdyscyplinowany peon Smoczych Paszcz', '', '', '', 0),
(11063, 'koKR', 'Zasłużyć na skrzydła...', '', '', '', '', '', '', '', '', 0),
(11064, 'koKR', 'Wyścig Smoczych Paszcz: Ballada o Staruszku Staruchowskim', 'Nie daj się zwieść siwym włosom, $gsiepaczu:siepaczko;. Wciąż jestem dziesięć razy lepszym jeźdźcem niż ty! I nie myśl sobie, że ten stary pies nie ma w zanadrzu paru sztuczek.$B$BWystarczy, że polecisz za mną i nie dasz się strącić z wierzchowca. Jeśli ci się to uda, Staruszek przyzna się do porażki.$B$BWystartujemy, gdy tylko będziesz $ggotów:gotowa;.$B', 'Leć za Murgiem „Staruszkiem” Błotoszczękiem i staraj się utrzymać na latającym wierzchowcu. Jeśli pokonasz Murga „Staruszka” Błotoszczęka, zgłoś zwycięstwo Ja\'yowi Nosliwowi w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Pokonany Murg „Staruszek” Błotoszczęk', 'Wróć do Ja\'ya Nosliwa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11067, 'koKR', 'Wyścig Smoczych Paszcz: Trope Brudobekacz', 'Smocze Paszcze dobrze cię traktują, $N. Nawet takiej wyświechtanej, przeklętej istocie jak ja dają szansę. Jeśli chcesz udowodnić Niebołamaczom swoją wartość, musisz mnie pokonać.$B$BStrząsnę cię z ogona jak uporczywe pchły...$B$BWystartujemy, gdy będziesz $ggotów:gotowa;.', 'Leć za Trope\'em Brudobekaczem i staraj się utrzymać na latającym wierzchowcu. Jeśli pokonasz Trope\'a Brudobekacza, zgłoś zwycięstwo Ja\'yowi Nosliwowi w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Pokonany Trope Brudobekacz', 'Wróć do Ja\'ya Nosliwa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11068, 'koKR', 'Wyścig Smoczych Paszcz: Corlok Weteran', 'Ty wyzywasz MNIE? Nie rozśmieszaj mnie!$B$BMówisz poważnie? No dobrze! Wystarczy, że nie zginiesz. Dasz radę nie zginąć, co?? Nawet kiedy będę w ciebie ciskać czaszkami i zataczać kręgi wokół twoich żałosnych umiejętności jeździeckich?$B$BDaj znać, gdy będziesz $ggotów:gotowa;, to wystartujemy.', 'Leć za Corlokiem Weteranem i staraj się utrzymać na latającym wierzchowcu. Jeśli pokonasz Corloka Weterana, zgłoś zwycięstwo Ja\'yowi Nosliwowi w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Pokonany Corlok Weteran', 'Wróć do Ja\'ya Nosliwa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11069, 'koKR', 'Wyścig Smoczych Paszcz: Dowódca skrzydła Ichman', 'Trzy lata spędziłem w tej piekielnej dziurze. Trzy lata w niewoli u przeklętego Klanu Mroźnego Wilka. Kazali mi siedzieć w swojej wieży i słuchać, jak bez końca jęczą o moście do Dun Baldar. Że to „niesprawiedliwe”, bla, bla, bla, bla... Wojna nie jest sprawiedliwa! Do diabła z nimi wszystkimi!$B$BGdy tylko mnie uwolniono, opuściłem to miejsce na zawsze i przybyłem tutaj, by zacząć nowe życie. Teraz rywalizujemy z Mulvem o tytuł Orka nad Orkami. Jeśli chcesz go zdobyć, musisz najpierw przejść przeze mnie, $gżółtodziobie:żółtodziobko;.$B$BRuszamy, gdy będziesz $ggotów:gotowa;.$B', 'Leć za dowódcą skrzydła Ichmanem i staraj się utrzymać na latającym wierzchowcu. Jeśli pokonasz dowódcę skrzydła Ichmana, zgłoś zwycięstwo Ja\'yowi Nosliwowi w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Pokonany dowódca skrzydła Ichman', 'Wróć do Ja\'ya Nosliwa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11070, 'koKR', 'Wyścig Smoczych Paszcz: Dowódca skrzydła Mulverick', 'Trzy lata krwi, potu i łez. Głównie łez... To niesamowite, ile potrafi wypłakać zaprawiony w boju żołnierz, kiedy dochodzi do totalnej wojny!$B$B„Wskakują nam do wieży na koniach!” „Czemu ich baza jest tak dobrze broniona?” „Zajmują nam chatę zaopatrzeniową, ja dezerteruję!”$B$BMięczaki...$B$BZłapałem pierwszy pociąg z „Beksowa”, gdy tylko otworzył się Mroczny Portal. Teraz jestem asem Smoczych Paszcz. Jeśli chcesz zostać Orkiem nad Orkami, musisz mnie pokonać.$B$BRuszamy, gdy będziesz $ggotów:gotowa;.$B', 'Leć za dowódcą skrzydła Mulverickiem i staraj się utrzymać na latającym wierzchowcu. Jeśli pokonasz dowódcę skrzydła Mulvericka, zgłoś zwycięstwo Ja\'yowi Nosliwowi w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.$B', 'Pokonany dowódca skrzydła Mulverick', 'Wróć do Ja\'ya Nosliwa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11071, 'koKR', 'Wyścig Smoczych Paszcz: Kapitan Kruszyciel Niebios', 'Śmiesz wyzywać Kruszyciela Niebios? Świat wokół ciebie pogrąży się w ciemności, gdy moje meteory rozedrą niebiosa.$B$BNie masz szans, żołnierzu. A jednak pragniesz zginąć...$B$BSpełnię tę chorobliwą zachciankę, choćby po to, by dać nauczkę każdemu, kto głupio marzy o popełnieniu tego samego błędu.$B$BLecimy, gdy będziesz $ggotów:gotowa;!', 'Leć za kapitanem Kruszycielem Niebios i staraj się utrzymać na latającym wierzchowcu. Jeśli pokonasz kapitana Kruszyciela Niebios, zgłoś zwycięstwo Ja\'yowi Nosliwowi w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', 'Pokonany kapitan Kruszyciel Niebios', 'Wróć do Ja\'ya Nosliwa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11075, 'koKR', 'Kopalnie Otchłanioskrzydłych', 'Potrzebna jest twoja pomoc w Kopalniach Otchłanioskrzydłych, $gnadzorco:nadzorczyni; $N.$B$BDwa dni temu nasze wydobycie stanęło w miejscu, kiedy dokonaliśmy ponurego odkrycia. Pewien górnik pracował w głębi kopalni i uderzył kilofem w niezwykłą kryształową formację. Niestety ta formacja była przyczepiona do bardzo rozzłoszczonego smoka Otchłani. Bestia zbudziła się ze snu i wybiła wszystkich naszych robotników.$B$BZgłoś się do Pani Kopalń. Czekają na ciebie u wylotu kopalń, na południowy zachód stąd.', 'Odszukaj Panią Kopalń na Występie Otchłanioskrzydłych.', '', '', '', '', '', '', 0),
(11076, 'koKR', 'Zbieranie resztek...', 'Większość naszej ciężkiej pracy leży porozrzucana po tych kopalniach. Wózki pełne ładunku walają się na każdym skrawku kopalni! Przy obecnej plądze po prostu nie możemy się do nich dostać.$B$BI tu wkraczasz ty, $N. Twoim codziennym obowiązkiem w tej kopalni jest zbieranie ładunku porzuconego przez górników i robotników z głębin.$B$BZbierz ładunek z Kopalni Otchłani i przynieś go mnie albo mojej siostrze.', 'Pani Kopalń w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca chce, żebyś $godzyskał:odzyskała; 15 skrzyń ładunku z Kopalni Otchłani.', '', 'Wróć do Pani Kopalń w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11077, 'koKR', 'Smoki to najmniejszy z naszych problemów', 'Przebudzenie tego smoka rozjuszyło całą masę innych paskudnych stworów w tych kopalniach. Dwa gatunki szczególnie dają się Smoczym Paszczom we znaki: obdzieracze z Kopalni Otchłani i pustoszyciele z Kopalni Otchłani. Musisz nam pomóc je wybić. Proszę tylko o twój udział raz dziennie.$B$BWchodź tam i zabij, ile zdołasz!', 'Brygadzista Smoczych Paszcz w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; 15 obdzieraczy z Kopalni Otchłani i 5 pustoszycieli z Kopalni Otchłani.', '', 'Wróć do brygadzisty Smoczych Paszcz w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11081, 'koKR', 'Wielki bunt Mętnej Krwi', 'Ten dokument opisuje bunt zaplanowany przez Złamanych z Mętnej Krwi. Wygląda na to, że smok miał posłużyć do odwrócenia uwagi od ich ucieczki. Sądząc po wszystkich trupach zaściełających kopalnię, można bezpiecznie założyć, że ich plany spełzły na niczym.$B$BZanieś plany ucieczki Pani Kopalń.', 'Zanieś plany ucieczki Mętnej Krwi Pani Kopalń.', '', 'Wróć do Pani Kopalń w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11082, 'koKR', 'Poszukiwacz prawdy', 'Ci górnicy są o wiele za głupi, żeby wymyślić jakikolwiek plan ucieczki. Musimy znaleźć i ukarać prowodyra. Zapuść się w głąb kopalni i odszukaj nadzorców Mętnej Krwi. Jeśli nie dopadli ich mieszkańcy kopalni, z pewnością się ukrywają.$B$BGdy któregoś znajdziesz, przesłuchuj go, aż wyjawi, kto naprawdę stoi za ucieczką. Wróć do mnie z imieniem tego zdrajcy i dłonią nadzorcy.', 'Znajdź nadzorcę Mętnej Krwi i go przesłuchaj. Wróć do Pani Kopalń z informacjami od Mętnej Krwi i dłonią nadzorcy.', 'Zdobyte informacje od Mętnej Krwi', 'Wróć do Pani Kopalń w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11083, 'koKR', 'Oszalali i skołowani', 'Nie martw się tym smokiem, $N. Mamy wobec niego plany...$B$BGłębiej w tej kopalni jest banda oszalałych z Mętnej Krwi. Kiedy smok się uwolnił, zostali odcięci od wyjścia. Jakimś cudem po zaledwie 2 dniach odosobnienia stracili wszelką przyzwoitość.$B$BUciekli się do kanibalizmu i siania zamętu. Nie potrzeba nam tu takiego szaleństwa. Znajdź ich i zabij. Wszystkich.', 'Ronag Poganiacz Niewolników w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; oszalałego brygadzistę Mętnej Krwi i 5 oszalałych górników Mętnej Krwi.', '', 'Wróć do Ronaga Poganiacza Niewolników w Kopalniach Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11084, 'koKR', 'Baczność, kapitanie!', 'No proszę, proszę... Widzę, że wciąż żyjesz. To dobrze, bo Mor\'ghor chce cię natychmiast widzieć w swojej wieży. Ruszaj się!', 'Porozmawiaj z nadrządcą Mor\'ghorem w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11086, 'koKR', 'Zakłócenie Portalu Zmierzchu', 'Jednym z twoich obowiązków jako kapitana Smoczych Paszcz jest tłumienie działalności Płonącego Legionu na Rubieży. Twoją powinnością jest uciszyć tych, którzy przeciwstawiają się lordowi Illidanowi!$B$BDemony głupio próbują ustabilizować portal na Grani Zmierzchu w zachodnim Nagrandzie. Muszą zapłacić za swoją zdradę, a ty będziesz tym orkiem, który ściągnie z nich ten dług.$B$BUdaj się na Grań Zmierzchu i wybij jej mieszkańców. Masz obowiązek przeprowadzać co najmniej jeden atak dziennie na ich umocnienia.', 'Nadrządca Mor\'ghor w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gzabił:zabiła; 20 agentów Cienia Śmierci.', '', 'Wróć do nadrządcy Mor\'ghora na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11089, 'koKR', 'Działo dusz Reth\'hedrona', 'Reth\'hedron panuje teraz nad Granią Zmierzchu w Nagrandzie. Eredar o takiej mocy puszczony wolno na ten świat nie wróży Illidari nic dobrego. Niestety nie mamy środków, by zgładzić Reth\'hedrona. Nie w czasie wojny, którą Sha\'tarowie wydali Czarnej Świątyni. Nie... Mam lepszy plan.$B$BPoskromisz Reth\'hedrona i odeślesz go z powrotem przez Portal Zmierzchu. W tym celu trzeba sporządzić działo dusz.$B$BWróć do mnie z materiałami z tej listy.', 'Lord Illidari Balthas w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca chce, żebyś $gprzyniósł:przyniosła; mu 2 sztabki spaczostali, 1 ramę z adamantytu, 1 rdzeń energetyczny z khorium i 1 nieskazitelną tajemną esencję.', '', 'Wróć do lorda Illidari Balthasa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11090, 'koKR', 'Poskromić Pogromcę', '<Balthas unosi urządzenie o obcym wyglądzie.>$B$BTo działo dusz. Po zestrojeniu jego działanie jest niszczycielskie. To jest zestrojone z moją krwią. Z tą samą krwią, która płynie w żyłach Reth\'hedrona – mojego brata. Tak, jego chybiona lojalność będzie jego zgubą.$B$BWeź działo i leć na Grań Zmierzchu w zachodnim Nagrandzie. Odnajdź Reth\'hedrona i strzelaj! Musisz pozostać na wierzchowcu i w zasięgu, by działo zadziałało. Nie ustępuj mu pola, a nie będzie miał innego wyjścia, jak uciec!', 'Lord Illidari Balthas w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca zlecił ci użycie działa dusz na Reth\'hedronie Pogromcy w Nagrandzie.$B$BMusisz też zwrócić działo dusz.', 'Poskrom Reth\'hedrona Pogromcę', 'Wróć do lorda Illidari Balthasa na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11092, 'koKR', 'Witaj, dowódco!', 'Kapitanie $N!$B$B<Poganiacz Varkule ci salutuje.>$B$BNadrządca Mor\'ghor chce cię natychmiast widzieć w swoich komnatach!', 'Porozmawiaj z nadrządcą Mor\'ghorem w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11094, 'koKR', 'Zabić ich wszystkich!', 'Dowódco $N, baczność! Weźmiesz batalion Niebołamaczy i złupisz placówkę Widzących u stóp Pól Otchłanioskrzydłych. Gdy Sanktuarium Gwiazd zostanie zniszczone, nasze linie łączności z posterunkami w Punkcie Zaćmienia i Punkcie Illidari znów będą otwarte.$B$BRuszaj! Użyj tej rakietnicy, by dać Niebołamaczom sygnał do ataku!', 'Przekaż wieści o swojej misji wraz z rakietnicą Smoczych Paszcz arkaniście Thelisowi w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', 'Wróć do Arkanisty Thelisa w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11095, 'koKR', 'Dowódca Hobb', 'Smocze Paszcze ważą się nas atakować tylko wtedy, gdy tracimy czujność. Gdyby zaatakowały, kiedy jesteśmy przygotowani, czekałaby je pewna klęska.$B$BChcę, żebyś $gpozwolił:pozwoliła; im przyjść, $N.$B$B<Thelis kiwa głową.>$B$BTak... pułapka. Weź tę rakietnicę, którą dał ci ich nadrządca, i zanieś ją dowódcy Hobbowi. Stoi na straży tuż przed tym budynkiem.', 'Daj rakietnicę Smoczych Paszcz dowódcy Hobbowi w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', 'Wróć do dowódcy Hobba w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11097, 'koKR', 'Najzabójczejsza pułapka w dziejach', 'Weź te medale Widzących. Gdy będzie po wszystkim, Mor\'ghor zażąda dowodu „zwycięstwa”. Rozpozna, że pochodzą ze zwłok poległych żołnierzy Widzących.$B$BTeraz pozostało już tylko użyć rakietnicy sygnałowej, by zaalarmować najeźdźców Smoczych Paszcz. Zmiażdżymy ich, gdy będziesz $ggotów:gotowa;. Daj tylko znać.', 'Pomóż dowódcy Hobbowi i Widzącym obronić Sanktuarium Gwiazd. Gdy wszystkie siły Smoczych Paszcz zostaną pokonane, wróć z medalami Widzących do nadrządcy Mor\'ghora w Obozie Smoczych Paszcz.$B', 'Pokonane siły Smoczych Paszcz', 'Wróć do nadrządcy Mor\'ghora na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11099, 'koKR', 'Zabić ich wszystkich!', 'Dowódco $N, baczność! Weźmiesz batalion Niebołamaczy i złupisz placówkę Aldorów na północny zachód od naszej ukochanej Czarnej Świątyni. Gdy Ołtarz Sha\'tar zostanie zniszczony, nasze linie łączności z posterunkami przy Szramowijach znów będą otwarte.$B$BRuszaj! Użyj tej rakietnicy, by dać Niebołamaczom sygnał do ataku!', 'Przekaż wieści o swojej misji i rakietnicę Smoczych Paszcz anachoretce Ceyli przy Ołtarzu Sha\'tar.', '', 'Wróć do Anachoretki Ceyli przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11100, 'koKR', 'Dowódca Arcus', 'Smocze Paszcze ważą się nas atakować tylko wtedy, gdy tracimy czujność. Gdyby zaatakowały, kiedy jesteśmy przygotowani, czekałaby je pewna klęska.$B$BChcę, żebyś $gpozwolił:pozwoliła; im przyjść, $N.$B$B<Ceyla kiwa głową.>$B$BTak... pułapka. Weź tę rakietnicę, którą dał ci ich nadrządca, i zanieś ją dowódcy Arcusowi. Stoi na straży tuż przed tym budynkiem.$B', 'Daj rakietnicę Smoczych Paszcz dowódcy Arcusowi przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', 'Wróć do dowódcy Arcusa przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11101, 'koKR', 'Najzabójczejsza pułapka w dziejach', 'Weź te medale Aldorów. Gdy będzie po wszystkim, Mor\'ghor zażąda dowodu „zwycięstwa”. Rozpozna, że pochodzą ze zwłok poległych żołnierzy Aldorów.$B$BTeraz pozostało już tylko użyć rakietnicy sygnałowej, by zaalarmować najeźdźców Smoczych Paszcz. Zmiażdżymy ich, gdy będziesz $ggotów:gotowa;. Daj tylko znać.', 'Pomóż dowódcy Arcusowi i Aldorom obronić Ołtarz Sha\'tar. Gdy wszystkie siły Smoczych Paszcz zostaną pokonane, wróć z medalami Aldorów do nadrządcy Mor\'ghora w Obozie Smoczych Paszcz.', 'Pokonane siły Smoczych Paszcz', 'Wróć do nadrządcy Mor\'ghora na Występie Otchłanioskrzydłych w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(11107, 'koKR', 'Pokłoń się najwyższemu lordowi', 'Nie jestem godzien nawet przekazać wiadomości skierowanej do ciebie, $gpanie:pani;. Proszę, wybacz mi tę śmiałość. Nadrządca Mor\'ghor chce cię natychmiast widzieć w swoich komnatach!', 'Porozmawiaj z nadrządcą Mor\'ghorem w Obozie Smoczych Paszcz w Dolinie Cienistego Księżyca.$B', '', '', '', '', '', '', 0),
(11544, 'koKR', 'Uzbrojenie Ata\'mal', 'Taras Ata\'mal we wschodniej części Doliny Cienistego Księżyca jest dla draenei świętym miejscem, ale teraz roi się tam od spaczonych orków. Wykopali stamtąd szczególną rudę i wykuli z niej spaczoną broń i zbroje.$B$BPotrzebuję tego uzbrojenia, by stworzyć stop z rudą nag. Nasi anachoreci pobłogosławili moje kowadło, dając mu moc oczyszczania.$B$BZdobądź uzbrojenie od wybrańców, pogromców i mrocznych tkaczy Cienistego Księżyca. Przynieś je tutaj, rozbij i oczyść na moim kowadle, a potem daj mi oczyszczony metal.', 'Kowalka Hauthaa potrzebuje 5 sztuk oczyszczonego metalu Ata\'mal. Zdobędziesz go, rozbijając uzbrojenie Ata\'mal na jej kowadle w Zbrojowni Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', 'Wróć do kowalki Hauthaa na Wybrzeżu Zielonoskrzelnych na Wyspie Quel\'Danas.', '', '', '', '', 0),
(13429, 'koKR', 'Odwrócenie uwagi dla Akamy', '<Xi\'ri pulsuje światłem, a otaczające go siły Aldorów i Widzących wykonują jego rozkazy. Armia Xi\'riego jest gotowa odepchnąć siły Illidana i odwrócić uwagę na rzecz Akamy. Naaru czeka, aż poprosisz o rozpoczęcie ataku.>', 'Dopilnuj, by Akama i Maiev weszli do Czarnej Świątyni w Dolinie Cienistego Księżyca, gdy siły Xi\'riego odwrócą uwagę wroga.', 'Pomóż Akamie i Maiev wejść do Czarnej Świątyni.', 'Wróć do Xi\'riego w Ruinach Baa\'ri w Dolinie Cienistego Księżyca.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(10451, 'koKR', 'Chwała Matce Ziemi. Jestem pewien, że Wilda odnajdzie drogę do domu. Przyjmij to, proszę, jako wyraz naszej wdzięczności.', 0),
(10458, 'koKR', 'Gdy wszystkie dusze żywiołaków z tej krainy trafią do totemu, porozumiemy się z nimi i dowiemy się, czy da się coś zrobić dla Doliny Cienistego Księżyca.', 0),
(10480, 'koKR', 'Zostało już tylko powietrze, $N.', 0),
(10481, 'koKR', 'Pozwól, że cię wynagrodzę za podjęcie się tak żmudnego zadania, $gbohaterze:bohaterko;.$B$BA teraz do pracy! Odsuń się, proszę, żebym mógł ustawić totem i uwolnić dusze.', 0),
(10513, 'koKR', 'Słowa potępienia? Nigdy o nich nie słyszałem. Posłuchaj mojej rady: pozwól umarłym spoczywać w spokoju.$B$BSkoro jednak $gprzebyłeś:przebyłaś; taki kawał drogi, przydałaby mi się pomoc w kilku innych sprawach. Co ty na to?', 0),
(10514, 'koKR', 'Mówisz, że tych obdzieraczy było dużo więcej, niż się $gspodziewałeś:spodziewałaś;? Wygląda na to, że czas wynieść śmieci.', 0),
(10515, 'koKR', 'To oduczy te przeklęte, plugawe bestie zabijania moich dzików! Dobra robota, $N!', 0),
(10519, 'koKR', 'Rozumiesz, co trzeba zrobić? Odnajdź synów Oronoka. Odnajdź moich chłopców...', 0),
(10521, 'koKR', '<Grom\'tor chrząka.>$B$BDobrze, że $gprzyszedłeś:przyszłaś;. Ten robal właśnie wszystko wyśpiewał. Mamy ich!', 0),
(10522, 'koKR', 'To trzeba natychmiast zanieść ojcu.', 0),
(10523, 'koKR', 'Gdy Szyfr Potępienia znów będzie cały, położymy kres tej klątwie!', 0),
(10527, 'koKR', 'Ciało Ar\'tora zwisa bezwładnie, zawieszone w powietrzu. Nie wiesz, jak długo nie żyje, ale serce ci się kraje na myśl o Oronoku.$B$BMoże warto spróbować go zdjąć i zanieść jego zwłoki ojcu.', 0),
(10528, 'koKR', 'Wsuwasz kryształowy klucz w gniazda u podstawy każdego z demonicznych kryształów.', 0),
(10537, 'koKR', 'W moim ojczystym języku to znaczy „wędrówka bohatera”. To wciąż prawdziwe – nawet teraz, w czasach, gdy wszyscy nasi bohaterowie polegli...$B$BZdaje się, że zawsze ktoś się podnosi.', 0),
(10540, 'koKR', '<Ar\'tor to znika, to znów się pojawia.>$B$BZdaje się, że mój czas dobiega końca, $gbohaterze:bohaterko;.', 0),
(10541, 'koKR', '<Oronok ociera łzę i uśmiecha się do ciebie.>$B$BDziękuję. Obiecuję ci, $gbohaterze:bohaterko;, że powstanie pieśń ku twojej czci.', 0),
(10546, 'koKR', '<Borak przez chwilę milczy.>$B$BObserwuję tych krwawych elfów od tygodni i próbuję ustalić, gdzie ukryli trzecią część Szyfru Potępienia.$B$BJak dotąd nie udało mi się znaleźć żadnych wskazówek. Wiem tylko tyle, że Illidan raz dziennie przysyła tu z Czarnej Świątyni posłańca.$B$BTen posłaniec jest nietykalny. Śledzę go od tygodnia i próbuję wymyślić, jak odciągnąć go od jego ochroniarza. Niestety, ochroniarz nigdy nie odstępuje go na krok.', 0),
(10562, 'koKR', 'Dziękuję, że $gzluzowałeś:zluzowałaś; moich ludzi, $N. Z twoją pomocą, a także z pomocą innych, może jeszcze wytrzymamy. Niestety, samo przetrwanie to za mało. Musimy przejść do natarcia.', 0),
(10563, 'koKR', '<Dowódca skrzydła Nuainn słucha twojego raportu i z każdym zdaniem jest coraz bardziej zaniepokojony.>$B$BCzyli mówisz, że mają aż nadto piekielników, żeby nasilić ostrzał? Jeśli nie powstrzymamy ich, zanim wprowadzą w życie kolejną fazę swojego planu, Warownia Dzikiego Młota jest skończona.', 0),
(10564, 'koKR', 'Dobra robota, $N! Chciałbym powiedzieć, że Legion odpuści po takiej porażce, ale dobrze wiemy, że tak nie będzie. Kuźnia Śmierci, o której $gdowiedziałeś:dowiedziałaś; się podczas zwiadu, będzie naszym następnym celem.', 0),
(10568, 'koKR', 'Tablice Baa\'ri! Tak, mogą nam dostarczyć bardzo cennych informacji.', 0),
(10569, 'koKR', '<Kieran kartkuje strony dziennika.>$B$BWiększość jest nie do odczytania, ale tu i ówdzie rozpoznaję fragmenty o przygotowaniach do zaklęcia, które wymknęło się spod kontroli, o ofiarach i o pogarszającym się położeniu. Jest tu też ciekawa wzmianka o jakimś „dezerterze”.', 0),
(10570, 'koKR', '<Borak bierze od ciebie pismo i zaczyna czytać.>$B$BSprytne dranie! To rozkaz Illidana, który wskazuje, gdzie szyfr ma zostać ukryty następnym razem. Najwyraźniej ciągle go przenoszą. Nie ma tu słowa o tym, gdzie jest teraz... Gdybyśmy tylko mogli dostarczyć to pismo teraz, gdy znamy następne miejsce.$B$BSzkoda, że pieczęć jest złamana, przez co pismo jest bezużyteczne.$B$BHmm... A jednak...', 0),
(10571, 'koKR', 'Własnoręczne pismo Akamy. Aż smutno pomyśleć, co się stało z kimś tak mądrym i ukochanym jak on.', 0),
(10572, 'koKR', '<Dowódca skrzydła wkłada rdzeń zasilający między płyty pancerne, szczelnie zamyka urządzenie i kiwa głową.>$B$BPowinno zadziałać. I zrobi niezły huk, jeśli wolno mi tak powiedzieć.', 0),
(10573, 'koKR', '<Krasnolud kiwa głową.>$B$BDobrze będzie mieć wsparcie. Zebraliśmy wstępne informacje o tym, co Rada Cieni tam wyprawia, ale lepiej się poczuję, gdy wreszcie zaczniemy przeciw nim działać.', 0),
(10574, 'koKR', 'Tak! Cztery fragmenty medalionu. Teraz trzeba je złożyć...', 0),
(10575, 'koKR', 'Spodziewaliśmy się ciebie, $N. Akama mówił, że prędzej czy później się zjawisz.', 0),
(10576, 'koKR', 'Dobra robota, $N. Mam nadzieję, że z ciebie $gdobry aktor:dobra aktorka;. Kolejny krok mojego wielkiego planu będzie wymagał trochę teatru!', 0),
(10577, 'koKR', 'Teraz wystarczy tylko pójść po szyfr. Łatwizna, prawda?', 0),
(10578, 'koKR', 'Nareszcie! Fragment szyfru jest nasz!$B$B<Borak wkłada fragment do skrzynki.>', 0),
(10579, 'koKR', 'Gdy tylko wszystkie trzy fragmenty szyfru znajdą się razem, starożytne słowa zostaną poznane.$B$BOdzyskanie tego fragmentu z pewnością nie było łatwe. Takie bohaterstwo musi zostać nagrodzone.', 0),
(10582, 'koKR', 'Szkoda, że nie mogłem tam być z tobą! Aż mnie świerzbi, żeby użyć młota, ale moim zadaniem jest obserwować, nie zabijać.$B$BSkoro już $gwybiłeś:wybiłaś; dziurę w ich obronie, weźmy się za wstrzymanie produkcji w Kuźni Śmierci.', 0),
(10583, 'koKR', '<Ewan kręci głową, odbierając od ciebie plecak.>$B$BChyba Flanis nie zdawał sobie sprawy, jak silnie strzeżona będzie Kuźnia Śmierci. Teraz, gdy wiemy, co się tam naprawdę dzieje, wcale im się nie dziwię. Szkoda tylko, że Flanis nie wiedział o tym, kiedy tam wchodził.$B$BMogę tylko mieć nadzieję, że znajdzie się tu coś, co pomoże nam raz na zawsze unieszkodliwić Kuźnię Śmierci.', 0),
(10585, 'koKR', 'Dobra robota, $N. Zakłócenie przywołań Rady Cieni przybliża nas o krok do unieszkodliwienia Kuźni Śmierci.', 0),
(10586, 'koKR', '<Składasz raport dowódcy skrzydła i przekazujesz mu zdobyte rozkazy.>$B$BPokonanie Siewcy wojny Razuuna powinno było zakończyć nasze kłopoty z Legionem, ale te rozkazy opisują plan o wiele większy, niż się spodziewałem. Obawiam się, że jeszcze wiele zostało do zrobienia.', 0),
(10587, 'koKR', 'Przyjrzyjmy się tej broni z bliska, $N. Hmm... to dość niepokojące.', 0),
(10588, 'koKR', '<Uzdrowiciel ziemi Torlok bierze od ciebie Szyfr Potępienia.>$B$B$GZrobiłeś:Zrobiłaś; to, o co prosiły żywioły. Jesteśmy ci za to wdzięczni. Zostaniesz $gnagrodzony:nagrodzona;, ale kłopoty wciąż wiszą nad nami. Duchy ognia są wzburzone. Ktoś zgłosił roszczenie. Szyfr Potępienia zna ktoś jeszcze.$B$BWiem, że brzmi to zagadkowo, ale tylko tyle duchy chciały mi wyjawić. To i ten symbol...$B$B<Uzdrowiciel ziemi Torlok odwraca się i wskazuje na niebo.>$B$BCo to może oznaczać?', 0),
(10589, 'koKR', 'Zobaczmy, czy uda mi się ustalić, jak to działa...', 0),
(10595, 'koKR', 'Jestem pod wrażeniem, że $gprzeżyłeś:przeżyłaś; tę rzeź. Może właśnie ciebie potrzebujemy do niebezpiecznej misji.', 0),
(10596, 'koKR', 'Jak to, zamierzają nasilić ostrzał? Nie możemy do tego dopuścić. Wracaj tam i zajmij się tym, póki z Wioski Cienistego Księżyca coś jeszcze zostało!', 0),
(10597, 'koKR', 'Powinno zadziałać. Nie chciałbym być w warowni, kiedy to wybuchnie.', 0),
(10598, 'koKR', 'To nie czas na świętowanie, $N. Jeszcze nie wyszliśmy z ognia. Mam dla ciebie nowe rozkazy.', 0),
(10599, 'koKR', '<Ork kiwa głową.>$B$BDobrze będzie mieć wsparcie. Zebraliśmy wstępne informacje o tym, co Rada Cieni tam wyprawia, ale czas, żeby spadł na nich młot.', 0),
(10600, 'koKR', 'Sam bym tam zszedł rozbijać łby, ale mam surowy rozkaz nie wdawać się w walkę z wrogiem.$B$BWeźmy się za wstrzymanie produkcji w tym miejscu.', 0),
(10601, 'koKR', '<Zagran kręci głową, odbierając od ciebie plecak.>$B$BMówiłem ci, że to głupiec. Mam nadzieję, że jest tu coś, co wynagrodzi ci czas spędzony na jego szukaniu.', 0),
(10602, 'koKR', 'Dobrze, robimy postępy. To przybliża nas o krok do unieszkodliwienia tego miejsca i bezpiecznego powrotu do Wioski Cienistego Księżyca.', 0),
(10603, 'koKR', '<Składasz raport strażnikowi krwi i przekazujesz mu zdobyte rozkazy.>$B$BDobra robota, $N, ale nie myśl sobie, że dostaniesz za to jakieś wstążki. Niech nocne elfy obwieszają sobie ślicznymi ozdóbkami te swoje mundurki, jeśli chcą. Prawdziwi wojownicy opowiadają o bitwach przy kuflu piwa.', 0),
(10604, 'koKR', 'Nareszcie mamy sposób, żeby wypędzić Legion z Cienistego Księżyca!', 0),
(10606, 'koKR', 'O, właśnie tego nam trzeba. Nigdy nie posądziłbym Legionu o tworzenie czegoś choćby przypominającego literaturę, ale to spełnia swoje zadanie.', 0),
(10611, 'koKR', 'Są tu informacje, których szukam. Jeszcze parę poprawek i w mig przejmiesz kontrolę nad grabieżcą Spaczenia.', 0),
(10612, 'koKR', 'Niesamowite! $GZrobiłeś:Zrobiłaś; to, czego nie zdołali wszyscy jeźdźcy gryfów z Warowni Dzikiego Młota! $GZłamałeś:Złamałaś; kręgosłup natarciu Płonącego Legionu i $gocaliłeś:ocaliłaś; nas przed zagładą z rąk ich piekielników. Jesteśmy ci głęboko wdzięczni za twoją służbę, $N.', 0),
(10613, 'koKR', 'Przyznaję, $N, jestem pod wrażeniem wszystkiego, co ci się udało osiągnąć. Pozbawienie Legionu możliwości prowadzenia wojny w Cienistym Księżycu da nam szansę odwrócić losy walki gdzie indziej.', 0),
(10619, 'koKR', 'Chwała naaru, $N. $GWypełniłeś:Wypełniłaś; wolę Światłości, pokonując tych, którzy podążają za Illidanem.', 0),
(10621, 'koKR', '<Ordinn bierze od ciebie fragment broni.>$B$BDawno nie widziałem czegoś takiego. Jasne, zrobiono to z rzadkiej rudy, ale to nie jest przeznaczone do zwykłej broni, $N. Jest nasycone magią, która ma niszczyć demony. Skoro $gzdobyłeś:zdobyłaś; to od Legionu, to musi być jakaś „tajna broń”, którą zamierzają wystawić przeciw Illidanowi. Ale znalezisko!', 0),
(10622, 'koKR', 'Dobrze, $N. Twoja lojalność nie budzi już wątpliwości. Możesz się teraz zobaczyć z Akamą.', 0),
(10623, 'koKR', '<Grokom bierze od ciebie fragment broni.>$B$BNie widziałem czegoś takiego od lat. Nie dość, że zrobiono to z rzadkiej rudy, to jeszcze nie trafi do zwykłej broni, $N.$B$BTe runy nadają ostrzu moc unicestwiania demonów. To pokazuje, jak bardzo Legion nienawidzi Illidana, skoro gotów jest uzbroić własne wojska w broń niszczącą demony. Możemy to obrócić na naszą korzyść.', 0),
(10624, 'koKR', 'Twój świat zaraz się zmieni, $N.$B$B<Hildagard zaczyna coś tworzyć z popiołu.>', 0),
(10625, 'koKR', 'Krwawy Bies? T... Teron Krwawy Bies? Ale... jak?$b$bJak Krwawy Bies może tu być? To niemożliwe!$b$bLegenda o Teronie Krwawym Biesie przyprawia o drżenie nawet Porzuconych. Według wszelkich przekazów Krwawy Bies był czarnoksiężnikiem Gul\'dana – i sam w sobie niezwykle potężnym. Gdy Orgrim Zgładziciel zabił Krwawego Biesa, Gul\'dan wziął duszę poległego czarnoksiężnika i umieścił ją w strzaskanej powłoce zabitego rycerza z Wichrogrodu. Tak narodził się pierwszy rycerz śmierci Hordy.', 0),
(10626, 'koKR', 'Nadadzą się świetnie. A teraz przekujmy je w coś bardziej użytecznego.', 0),
(10627, 'koKR', 'Nadadzą się świetnie. A teraz przekujmy je w coś bardziej użytecznego.', 0),
(10628, 'koKR', 'Witaj, $N. Musimy wiele omówić.$B$BMam nadzieję, że masz otwarty umysł. Wielu nie rozumie decyzji, które podejmuję. Tylko moi najbliżsi współpracownicy pojmują wróżby, które widzę, i znaki, na które czekam.$B$BGdy połączyłem siły z Illidanem, zrobiłem to z powodu wizji, które przepowiadały, że w przeciwnym razie moja rasa zostanie zniszczona. Cierpliwie czekałem, aż spełnią się kolejne znaki i wizje... exodus Velena... otwarcie Mrocznego Portalu... a teraz... twoje przybycie.', 0),
(10633, 'koKR', 'Krwawy Bies? Ależ nie słyszałem tego imienia od wieków!$B$BPo Drugiej Wojnie Krwawy Bies wrócił tutaj razem ze swoimi rycerzami śmierci. Nie mogąc znieść okropnej natury swojej nowej postaci i pozbawiony wsparcia ukochanego przywódcy, Gul\'dana, Krwawy Bies odebrał sobie życie.$B$BJeśli teraz przemierza te ziemie jako duch, to jest to dla mnie nowina. Może jednak z twoją pomocą zdołam przepowiedzieć coś więcej.', 0),
(10634, 'koKR', 'Muszę mieć wszystkie części, zanim zdołam przepowiedzieć los Krwawego Biesa.', 0),
(10635, 'koKR', 'Gdy będę mieć w posiadaniu wszystkie trzy części, zdołam przepowiedzieć, gdzie przebywa Krwawy Bies.', 0),
(10636, 'koKR', 'Tylko gdy wszystkie trzy części będą razem, zdołam przepowiedzieć tajemnice, których tak rozpaczliwie szukasz!', 0),
(10637, 'koKR', 'Miejmy nadzieję, że ta dywersja dała nam dość czasu, by dowiedzieć się wszystkiego, czego potrzebujemy, o placu ćwiczeń w Karaborze.', 0),
(10639, 'koKR', 'Coś ty $gzrobił:zrobiła;? GŁUPCZE!$B$BMusisz naprawić to zło. W końcu to twoja wina. Weź jeden z tych hełmów. Każdy z nich jest nasycony wiecznie tlącym się popiołem, który dla mnie $gprzyniosłeś:przyniosłaś;. Co ważniejsze, pozwolą ci widzieć duchy Cienistego Księżyca, w tym Terona Krwawego Biesa.$B$BJeśli kiedykolwiek znajdziesz Terona Krwawego Biesa, zniszcz go.', 0),
(10642, 'koKR', '<Zorus zaczyna coś tworzyć z próbek popiołu.>$B$BGotowe. Oto duchokulary!', 0),
(10643, 'koKR', 'Twierdzisz, że $gsłyszałeś:słyszałaś; szept duchów? I że wspominały o Teronie Krwawym Biesie?$B$B<Zorus wzdryga się.>$B$BTak... Znam Terona Krwawego Biesa. A raczej słyszałem o nim. Od dawna uważano go za martwego. O czym mogą mówić te duchy?', 0),
(10644, 'koKR', 'Krwawy Bies? Ależ nie słyszałem tego imienia od wieków!$B$BPo Drugiej Wojnie Krwawy Bies wrócił tutaj razem ze swoimi rycerzami śmierci. Nie mogąc znieść okropnej natury swojej nowej postaci i pozbawiony wsparcia ukochanego przywódcy, Gul\'dana, Krwawy Bies odebrał sobie życie.$B$BJeśli teraz przemierza te ziemie jako duch, to jest to dla mnie nowina. Może jednak z twoją pomocą zdołam przepowiedzieć coś więcej.', 0),
(10645, 'koKR', 'Coś ty $gzrobił:zrobiła;? GŁUPCZE!$B$BMusisz naprawić to zło. W końcu to twoja wina. Weź jeden z tych hełmów. Każdy z nich jest nasycony wiecznie tlącym się popiołem, który dla mnie $gprzyniosłeś:przyniosłaś;. Co ważniejsze, pozwolą ci widzieć duchy Cienistego Księżyca, w tym Terona Krwawego Biesa.$B$BJeśli kiedykolwiek znajdziesz Terona Krwawego Biesa, zniszcz go.', 0),
(10647, 'koKR', 'Niezły łup tam masz, mon. Dobra robota! A nagrodę dostaniesz, nie martw się!', 0),
(10648, 'koKR', 'No, oto twoja nagroda. Tylko nie wydaj wszystkiego w jednym miejscu.', 0),
(10651, 'koKR', 'Świetna robota, $N! Twoje zwycięstwo nad Varedisem będzie miało ogromny wpływ na naszą wojnę z Illidanem.$B$B$GUdowodniłeś:Udowodniłaś; swoją wartość nie tylko Aldorom, ale całej Rubieży. Pozwól, że zniszczę to, co zostało z tej okropnej księgi.', 0),
(10660, 'koKR', 'To może trochę potrwać. Weź te monety za swoją ciężką pracę.', 0),
(10661, 'koKR', '<Gnomus łapczywie chwyta śledziony.>$B$BOto twoje pieniądze, tak jak obiecałem. Zawołam cię, jeśli będę potrzebować więcej śledzion.$B$BPrzepyszne... Śmiem twierdzić, że są „wyśledzionite”!', 0),
(10672, 'koKR', 'Słuchaj, nie ma czasu do stracenia. Obserwowałem oznakowane diemetradony i odkryłem, że wszystkie podlegają gigantycznemu, nie, OLBRZYMIEMU diemetradonowi zwanemu Spaczogrzbietem Większym.', 0),
(10673, 'koKR', 'Nareszcie! Pełna ochrona przed lawą jest moja! Oczywiście tobie też należy się udział w tej technologii, $N. $GZasłużyłeś:Zasłużyłaś; na to!', 0),
(10677, 'koKR', 'To fantastyczne, ale właśnie dostałem niesamowite wieści!', 0),
(10678, 'koKR', 'Teraz potrzebuję trochę czasu dla siebie, $N. Dzięki za całą pomoc!', 0),
(10680, 'koKR', 'Dobrze, że $gprzyszedłeś:przyszłaś;. Czeka nas wiele pracy.', 0),
(10681, 'koKR', 'Dobrze, że $gprzyszedłeś:przyszłaś;. Czeka nas wiele pracy.', 0),
(10683, 'koKR', 'Tablice Baa\'ri! Tak, mogą nam dostarczyć bardzo cennych informacji.', 0),
(10684, 'koKR', 'To pasuje do charakteru pisma Akamy... Zobaczmy, czego się dowiemy.', 0),
(10685, 'koKR', 'Tak! Cztery fragmenty medalionu. Teraz trzeba je złożyć...', 0),
(10686, 'koKR', 'Spodziewaliśmy się ciebie, $N. Akama mówił, że prędzej czy później się zjawisz.', 0),
(10687, 'koKR', 'Przyjrzyjmy się tej broni z bliska, $N. Hmm... to dość niepokojące.', 0),
(10688, 'koKR', 'To powinno dać nam trochę czasu... Miejmy nadzieję, że wystarczy, żebyśmy zdobyli więcej informacji.', 0),
(10692, 'koKR', 'Dobra robota, $N. Zabijając Varedisa, $gpołożyłeś:położyłaś; kres jednemu z najniebezpieczniejszych przedsięwzięć Illidana.$B$BPo czymś takim twoje imię na pewno pójdzie w świat.$B$BPozwól, że zabiorę to, co zostało z Księgi spaczonych imion. Dopilnuję, żeby została należycie... zutylizowana.', 0),
(10702, 'koKR', 'Wspaniale! Jeśli trafi się jeszcze jakaś czarna robota, będę wiedział, gdzie cię szukać.', 0),
(10703, 'koKR', 'Ano, dobra robota! Masz tu trochę grosza za fatygę. Jak trza będzie wynieść więcej śmieci, będę wiedział, po kogo posłać.', 0),
(10705, 'koKR', 'Jasnowidz Popielnych Języków od dawna nie żyje. Gdy odwracasz jego ciało, dostrzegasz napis nabazgrany na podłodze.', 0),
(10706, 'koKR', 'Tak... oczywiście! Teraz wszystko staje się jasne.', 0),
(10707, 'koKR', 'Kryształ! Jego moc... jest teraz w moich rękach!', 0),
(10744, 'koKR', '<Kurdran słucha twojego raportu.>$B$BTo naprawdę dobre wieści! Jeszcze kilka dni temu nawet by mi się nie śniło, że zdołamy przerwać oblężenie warowni przez Legion.$B$BNie tylko $gpowstrzymałeś:powstrzymałaś; ich natarcie, ale i $gzłamałeś:złamałaś; kręgosłup ich machiny wojennej! Za twoje męstwo masz wdzięczność klanu Dzikiego Młota, $N.', 0),
(10745, 'koKR', '<Zwierzchnik słucha twojego raportu.>$B$BZnakomite wieści! Utrzymywanie linii obrony przed piekielnikami Legionu pochłaniało zbyt wiele sił. Nie żebym się spodziewał, że moi ludzie się złamią, ale byli bardzo przeciążeni.$B$B$GDowiodłeś:Dowiodłaś; dziś swojej wartości dla Hordy. Gwardia Kor\'kronu zawsze będzie zaszczycona, mogąc walczyć u twojego boku.', 0),
(10750, 'koKR', 'Rzeczywiście, te nieznośne szczeniaki knują coś podstępnego. Musimy to zbadać dokładniej...', 0),
(10751, 'koKR', 'Nie uwierzysz, siepaczu.', 0),
(10759, 'koKR', '<Arakkoa skrzeczy ze śmiechem.>$B$BTak, to ja jestem dezerterem, o którym wspomina dziennik dowódcy. Czekałem na dzień, w którym inni dostrzegą zagrożenie ze strony tych, których niegdyś nazywałem braćmi.', 0),
(10760, 'koKR', 'Niewiele tu przydatnych rzeczy, ale kilka wpisów może się okazać pomocnych. Wygląda na to, że aż do śmierci ci arakkoa przygotowywali jakiś złożony magiczny rytuał, tylko po co? Jest tu też ciekawa wzmianka o jakimś „dezerterze”.', 0),
(10761, 'koKR', '<Arakkoa skrzeczy ze śmiechem.>$B$BTak, to ja jestem dezerterem, o którym wspomina dziennik dowódcy. Czekałem na dzień, w którym inni dostrzegą zagrożenie ze strony tych, których niegdyś nazywałem braćmi.', 0),
(10765, 'koKR', 'A więc próbują zyskać przychylność olbrzymów, co? Mam plan, który powinien zerwać ten bezbożny sojusz.', 0),
(10766, 'koKR', 'Miło mi cię poznać, $N. Jestem Plexi.$B$BNie będę cię zanudzał formalnościami. Wiemy, po co tu jesteśmy. No to do roboty.', 0),
(10767, 'koKR', 'To pewnie ciebie zapowiadał mi Strażnik krwi Gulmok. Mam pewien plan, ale do dokończenia przygotowań potrzebuję twojej pomocy.', 0),
(10768, 'koKR', 'Aha! Te świetnie się nadadzą.', 0),
(10769, 'koKR', 'No proszę, proszę... Czyżby to $gsiepacz:siepaczka;, $gktórego:którą; wysłałem w pole? $GWróciłeś:Wróciłaś; w jednym kawałku.$B$B<Or\'barokh kiwa głową.>$B$BWiedziałem, że mnie nie zawiedziesz, żołnierzu. $GPowstrzymałeś:Powstrzymałaś; poważne natarcie Illidari i przy okazji $gzasłużyłeś:zasłużyłaś; na małą nagrodę.', 0),
(10772, 'koKR', 'Rzeczywiście, te nieznośne szczeniaki knują coś podstępnego. Musimy to zbadać dokładniej...', 0),
(10773, 'koKR', 'Nie uwierzysz, żołnierzu!', 0),
(10774, 'koKR', 'A więc próbują zyskać przychylność olbrzymów, co? Mam plan, który może zerwać ten bezbożny sojusz.', 0),
(10775, 'koKR', 'Aha! Te świetnie się nadadzą.', 0),
(10776, 'koKR', 'No proszę, proszę... Czyżby to $gżołnierz:żołnierka;, $gktórego:którą; wysłałem w pole? $GWróciłeś:Wróciłaś; w jednym kawałku.$B$B<Yoregar kiwa głową.>$B$BWiedziałem, że mnie nie zawiedziesz, żołnierzu. $GPowstrzymałeś:Powstrzymałaś; poważne natarcie Illidari i przy okazji $gzasłużyłeś:zasłużyłaś; na małą nagrodę.', 0),
(10777, 'koKR', '<Parshah ogląda totem.>$B$BDobrze. Ten stary totem przez lata nie stracił mocy, ale sam nie wystarczy, żeby powstrzymać Mroczne Konklawe.', 0),
(10778, 'koKR', 'Dobra robota. Taki skarb zasługuje na coś lepszego niż zamknięcie w ciemnej skrzyni. Dopilnujemy, żeby posłużył godnemu celowi.', 0),
(10780, 'koKR', '<Parshah przyjmuje przyprószone popiołem pióra, kręcąc głową.>$B$BLepiej by było, gdyby wtedy zginęli, ale nic nigdy nie jest takie proste. To, że magia Gul\'dana zmieniła ich w zagrożenie, któremu próbowali zapobiec, to wyjątkowo okrutne zrządzenie losu.', 0),
(10782, 'koKR', '<Parshah przyjmuje nakrycie głowy i ostrożnie je obraca.>$B$BJest w nim moc, której potrzebujemy, żeby pokrzyżować działania Mrocznego Konklawe w Obozie Sketh\'lon.', 0),
(10793, 'koKR', '$GZabiłeś:Zabiłaś; ich zdobywcę? W takim razie nie mamy wiele czasu...$B$BKarmazynowy Symbol to grupa złożona z elitarnych sług Illidana. Stoją na szczycie łańcucha dowodzenia wszystkich sił Illidari poza Czarną Świątynią. Ci żołnierze porozumiewają się bezpośrednio ze Zdrajcą i wykonują jego rozkazy bez szemrania.$B$BTo właśnie te bestie bez wątpienia poprowadzą natarcie na ten świat, tratując wszystkich, którzy staną im na drodze.', 0),
(10804, 'koKR', 'Masz dobre i współczujące serce, $gprzyjacielu:przyjaciółko;.', 0),
(10807, 'koKR', 'Chwała Widzącym, $N. $GSpełniłeś:Spełniłaś; wolę Jasnowidza, pokonując tych, którzy idą za Illidanem.', 0),
(10808, 'koKR', 'Latami szukałem sposobu na powstrzymanie Mrocznego Konklawe, a ty $godniosłeś:odniosłaś; sukces tam, gdzie ja poniosłem porażkę. Mroczne rytuały Konklawe nie będą nam już zagrażać.$B$BCzęsto dręczy mnie poczucie winy, że przed laty porzuciłem towarzyszy, ale teraz wreszcie wiem, że podjąłem słuszną decyzję. Gdyby nie ówczesne wahania mojego sumienia, mógłbym skończyć jako jeden z cieni pośród nich.', 0),
(10811, 'koKR', 'Moje dzieci opowiedziały mi o twoich bohaterskich czynach. Możesz zrobić jeszcze więcej.', 0),
(10814, 'koKR', 'A więc nam pomożesz?', 0),
(10816, 'koKR', 'Doskonała robota, $N. Niech Światłość nadal cię chroni.', 0),
(10817, 'koKR', '$GZdobyłeś:Zdobyłaś; dziś mój najwyższy szacunek, $N.$B$BZabicie jednego spaczonego orka to niełatwe zadanie. Wyrżnięcie ich całej chmary to już, no cóż... bohaterstwo.', 0),
(10824, 'koKR', 'Elfy Kaela są wyjątkowo dobrze wyszkolone. Znakomita robota.', 0),
(10836, 'koKR', 'Dobra robota, $N. Odkryłem sposób, w jaki możemy uwolnić zniewolone smokowce przetrzymywane w Fortecy Smoczych Paszcz.', 0),
(10837, 'koKR', '<Neltharaku odbiera od ciebie kryształy.>$B$BZaraz przygotuję dla ciebie kryształy.', 0),
(10854, 'koKR', '<Neltharaku się śmieje.>$B$BOrki musiały być w szoku, gdy smokowce tak się na nich rzuciły. Dobra robota, $N. Może naprawdę jesteś $gbohaterem:bohaterką; naszego stada.', 0),
(10858, 'koKR', 'To te łańcuchy. Wysysają moją moc. Jedynym sposobem jest zdobycie klucza od Zuluheda i uwolnienie mnie.', 0),
(10866, 'koKR', 'Jestem wolna! $GOcaliłeś:Ocaliłaś; nas, $N!', 0),
(10870, 'koKR', '$GDowiodłeś:Dowiodłaś;, że jesteś $gsprzymierzeńcem:sprzymierzeńczynią; Otchłanioskrzydłych. Moja matka jest wolna, a moi bracia i siostry ocaleni! $B$BByć może pewnego dnia znów cię wezwiemy. Gdy ten dzień nadejdzie, wiedz, że przyjmiemy cię z otwartymi ramionami – jak brata Stada Otchłanioskrzydłych.', 0),
(10871, 'koKR', '$GDowiodłeś:Dowiodłaś;, że jesteś $gsprzymierzeńcem:sprzymierzeńczynią; Otchłanioskrzydłych. Moja matka jest wolna, a moi bracia i siostry ocaleni!$B$BByć może pewnego dnia znów cię wezwiemy. Gdy ten dzień nadejdzie, wiedz, że przyjmiemy cię z otwartymi ramionami – jak $gbrata:siostrę; Stada Otchłanioskrzydłych.', 0),
(10872, 'koKR', 'Jestem wolna! $GOcaliłeś:Ocaliłaś; nas, $N!', 0),
(10944, 'koKR', 'Dziękuję ci, $N. Olum to jeden z moich najdroższych przyjaciół i najbardziej zaufanych stronników. Jego wkład w nasze plany był nieoceniony.', 0),
(10946, 'koKR', 'Dobra robota, $N. To przybliży nas o krok do odwrócenia uwagi Illidana od nas i od...$B$B<Akama spogląda w stronę Maiev Cienistej Pieśni.>$B$BZostało jeszcze wiele do zrobienia, $N.', 0),
(10947, 'koKR', 'Moja wizja... teraz wszystko staje się jasne. Moc, jaką ten artefakt ma nad duszą... by ją uwięzić... by ją w siebie wchłonąć... Użyję tej mocy, by odzyskać to, co do mnie należy! Nadszedł czas, by zanieść walkę do Illidana!', 0),
(10957, 'koKR', 'Stało się, $N. Nadszedł czas, by uderzyć na Illidana.', 0),
(10958, 'koKR', 'Spodziewaliśmy się ciebie, $N. Akama bardzo potrzebuje twojej pomocy.', 0),
(10959, 'koKR', 'Stało się tak, jak przepowiedziano, $N. Jeden po drugim przyboczni Illidana padli... a teraz sam Zdrajca spotkał swój kres!$B$BWiedz jedno, $N: każda decyzja Akamy i każda chwila jego życia od przybycia Illidana prowadziły do tego momentu. Illidan wreszcie nie żyje, a nasz lud... jest wolny!', 0),
(10985, 'koKR', '<Xi\'ri pulsuje energią, a ty czujesz, jak w twoich dłoniach materializuje się jakiś przedmiot. To medalion, który w imieniu Akamy $gprzekazałeś:przekazałaś; A\'dalowi, a jego moc wzmocniła magia naaru. Sha\'tarowie powierzyli ci Medalion Karaboru, a wraz z nim dostęp do Czarnej Świątyni.>', 0),
(11012, 'koKR', 'Nasze ziemie przepadły. Nasze dzieci porwano nocą i zmuszono do niewolniczej pracy... albo gorzej...$B$B<Głos Mordenaia napina się.>$B$BNadszedł czas, sojuszniku. Nadszedł czas, by odebrać to, co niegdyś było nasze! $GDowiodłeś:Dowiodłaś;, że jesteś $gsprawnym wojownikiem:sprawną wojowniczką; o współczującej duszy.$B$BCzy przysięgasz pomóc Stadu Otchłanioskrzydłych odzyskać nasze ziemie i odbudować nasze domy? Czy przysięgasz czuwać nad stadem i pozwolić, by nasz ród odrodził się na nowo? Przysięgnij, a wspólnie stańmy do walki o nasz dom i naszych bliskich!', 0),
(11013, 'koKR', '<Mor\'ghor czyta list i wybucha śmiechem.>$B$BRycerz śmierci? Nie $gnadawałbyś:nadawałabyś; się nawet do czyszczenia butów rycerza śmierci, robaku.$B$B<Mor\'ghor mierzy cię wzrokiem.>$B$BAle owszem... Może $gzdołałbyś:zdołałabyś; dosłużyć się stopnia peona. W najgorszym razie wrzucę cię do dołu i zostawię na śmierć...', 0),
(11014, 'koKR', 'Varkule dobrze cię urządzi, $gsiepaczu:siepaczko;. Wybierzesz sobie jedną robotę, najlepiej pasującą do twoich umiejętności, plus zbieranie kryształów Otchłanioskrzydłych. Zlecenia robocze masz wypełniać raz dziennie.$B$BNo, to kupa gównianej roboty, ale nawet wyniesieni zaczynali jako peony.', 0),
(11015, 'koKR', 'Na dziś $gskończyłeś:skończyłaś;, $gmłody:młoda;. Wróć jutro, jeśli jeszcze będziesz żyć.', 0),
(11016, 'koKR', 'Na dziś $gskończyłeś:skończyłaś;, $gmłody:młoda;. Wróć jutro, jeśli jeszcze będziesz żyć.', 0),
(11017, 'koKR', 'Na dziś $gskończyłeś:skończyłaś;, $gmłody:młoda;. Wróć jutro, jeśli jeszcze będziesz żyć.', 0),
(11018, 'koKR', 'Na dziś $gskończyłeś:skończyłaś;, $gmłody:młoda;. Wróć jutro, jeśli jeszcze będziesz żyć.', 0),
(11019, 'koKR', 'Chyba nie $gmyślałeś:myślałaś;, że zostawimy cię $gsamego:samą; z armią spaczonych orków?$B$B<Oczy Yarzilla migoczą półprzezroczystym błękitem.>$B$BTak, jesteśmy tu z tobą, $N. Przy każdej przysłudze, którą wyświadczysz spaczonym orkom w swojej misji odzyskania ziem Otchłanioskrzydłych, będziemy u twego boku, by dopilnować, że poniosą należytą stratę.$B$BPodczas misji sabotażowych musisz się trzymać w cieniu, żeby nie ściągać na siebie niepotrzebnej uwagi.', 0),
(11020, 'koKR', '<Yarzill mówi cichym szeptem.>$B$BŚwietna robota, $N. Na razie się nie wychylaj. Wróć do mnie jutro, a zrobimy to znowu.', 0),
(11035, 'koKR', '<Yarzill szepcze.>$B$BOddajesz Otchłanioskrzydłym wielką przysługę, $N. Powoli obalimy Smocze Paszcze. Od środka toczy ich teraz choroba – choroba, na którą nie ma lekarstwa...$B$BWróć do mnie jutro, jeśli chcesz więcej pracy na Podniebnym Szlaku Smoczych Paszcz.', 0),
(11041, 'koKR', 'A więc ze szczątków jednego z moich nadzorców $gwydobyłeś:wydobyłaś; rozkaz i $gwziąłeś:wzięłaś; sprawy w swoje ręce? Udało ci się zaimponować Mor\'ghorowi. Dobra robota...', 0),
(11049, 'koKR', 'Neltharaku będzie bardzo zadowolony, $N. Dobra robota.', 0),
(11050, 'koKR', '$GJesteś prawdziwym bohaterem:Jesteś prawdziwą bohaterką;, $N.', 0),
(11053, 'koKR', 'Uważnie śledziłem twoje poczynania, $N. $GOkazałeś:Okazałaś; się nieocenionym nabytkiem dla Smoczych Paszcz. Dlatego awansuję cię na nadzorcę. Z tym stopniem wiążą się nowe obowiązki, które musisz wypełniać.$B$BPowstań, $gnadzorco:nadzorczyni; $N! Powstań i odszukaj w obozie tych, którzy potrzebują twojej pomocy.', 0),
(11054, 'koKR', 'ARRR! Może jednak nadasz się na nadzorcę. Ta przerośnięta jaszczurka była zmorą niejednego orka!$B$B<Główny nadzorca Błotobryła zaczyna wykuwać broń.>', 0),
(11055, 'koKR', 'Ciężki dzień pracy! Ale się opłaca, co? Aż serce rośnie, jak się patrzy na te bezużyteczne kurduple ślinące się nad kryształami... W każdym razie na dziś to wszystko. Wróć jutro na kolejną rundę butorangowej dyscypliny.', 0),
(11063, 'koKR', 'Chcesz więc dołączyć do Niebołamaczy, co? Owszem, $gdowiodłeś:dowiodłaś;, że z ciebie $gzdolny:zdolna; członek Smoczych Paszcz, ale na niebie Rubieży to nic nie znaczy. Trzeba odpowiedzieć na pytanie: CZY UMIESZ LATAĆ?$B$BI nie chodzi mi tylko o to, żeby wsiąść na smokowca Otchłani i dowieźć ładunek kryształów do fortu jak ci ciamajdowaci przewoźnicy. Mówię o byciu najlepszym... Orkiem nad Orkami...$B$BNa zachodzie jest sześciu jeźdźców. Pokonaj ich wszystkich, a nadam ci skrzydła Niebołamacza.', 0),
(11064, 'koKR', 'Dynie? Jakże upadli możni... Jestem pewien, że pozostali jeźdźcy okażą się o wiele trudniejszymi przeciwnikami.', 0),
(11067, 'koKR', 'Ciekawe... Następny pojedynek bez wątpienia okaże się dużo trudniejszy. Corlok to nie byle ciamajda.', 0),
(11068, 'koKR', 'Dwaj następni jeźdźcy to najlepsi piloci, jakich mieli do zaoferowania krasnoludy i orki z Azeroth. Nie masz szans!', 0),
(11069, 'koKR', 'Nie wierzę! Twoim następnym wyzwaniem jest Mulverick. Nie ma mowy, żebyś $gprzeżył:przeżyła; ten pojedynek.', 0),
(11070, 'koKR', 'No, wygląda na to, że zostaliście już tylko ty i kapitan, $gsiepaczu:siepaczko;. Powodzenia! Przyda ci się!', 0),
(11071, 'koKR', 'Nawet mi się nie śniło, że ktoś będzie dość zręczny, by pokonać Kruszyciela Niebios. Wiesz, co to oznacza, prawda? Jesteś teraz Orkiem nad Orkami! Musisz bronić swojego tytułu.', 0),
(11075, 'koKR', 'Górnicy ciężko pracują, ale żaden nie ośmiela się zapuścić głębiej w kopalnie. Wolą śmierć, niż kopać głębiej pod przymusem! To ty będziesz $gmusiał:musiała; wykonać obowiązki i zadania, których oni nie dokończyli.', 0),
(11076, 'koKR', 'Dobra robota, $N. Wróć jutro na kolejną wyprawę w głąb kopalni.', 0),
(11077, 'koKR', 'Na dziś wystarczy, $gnadzorco:nadzorczyni;. Wróć jutro na kolejną rundę sprzątania.', 0),
(11081, 'koKR', 'Świetna robota, $gnadzorco:nadzorczyni;. Mor\'ghor usłyszy o twojej wybitnej służbie dla Smoczych Paszcz.$B$BA wracając do tych psów z Mętnej Krwi. Planują ucieczkę, tak? Śmią się sprzeciwiać jedynemu prawdziwemu władcy Rubieży? Ich panowie za to zapłacą!', 0),
(11082, 'koKR', 'Nie ma nic do powiedzenia? Może gdy będzie się wykrwawiał na dnie tej przeklętej kopalni, sobie przypomni... Przypomni sobie, co znaczy wejść w drogę siłom Illidana!', 0),
(11083, 'koKR', 'No, nie rozumiem tego... Można by pomyśleć, że po 2 dniach nie będą nawet aż tak głodni. Mętna Krew...$B$B<Ronag kręci głową.>$B$BCholera, ale są głupi...', 0),
(11084, 'koKR', '<Mor\'ghor kiwa głową.>$B$BTak jest, powiedziałem: kapitanie. $GZasłużyłeś:Zasłużyłaś; na kolejny awans, $N.$B$BNa pewno nie pracujesz jak żaden spaczony ork, jakiego widziałem. Tak dalej, a może kiedyś zostaniesz nadrządcą.$B$BA teraz ruszaj i obejmij dowodzenie. Radziłbym ci spróbować zdobyć skrzydła Niebołamacza.', 0),
(11086, 'koKR', 'Świetna robota, kapitanie! Lord Illidan usłyszy o twoim bohaterstwie!', 0),
(11089, 'koKR', '<Balthas zręcznie łączy przyniesione przez ciebie części.>$B$BJesteś $ggotów:gotowa; do drugiej fazy planu, kapitanie.', 0),
(11090, 'koKR', 'Wróci, ale na razie wojna Legionu przeciwko lordowi Illidanowi została osłabiona. Lord usłyszy o twoich czynach, kapitanie.', 0),
(11092, 'koKR', 'Sam lord Illidan poprosił, abym awansował cię do stopnia dowódcy! To bezprecedensowe. Będziesz pierwszym członkiem Smoczych Paszcz, który osiągnął taki stopień poza Czarną Świątynią.', 0),
(11094, 'koKR', 'Dobrze, że $gprzyszedłeś:przyszłaś; do nas. Może zdołamy obrócić ten atak na naszą korzyść i odwrócić sytuację przeciw Smoczym Paszczom.', 0),
(11095, 'koKR', '<Hobb szczerzy zęby.>$B$BNajzabójczejsza pułapka w dziejach...', 0),
(11097, 'koKR', '<Mor\'ghor wybucha śmiechem.>$B$BHA! Wiedziałem, że mnie nie zawiedziesz, dowódco! Chcę, żebyś co najmniej raz dziennie $gprowadził:prowadziła; najazd na Sanktuarium Gwiazd. Nie będą mieli innego wyjścia, jak opuścić Cienisty Księżyc!', 0),
(11099, 'koKR', 'Dobrze, że $gprzyszedłeś:przyszłaś; do nas. Może zdołamy obrócić ten atak na naszą korzyść i odwrócić sytuację przeciw Smoczym Paszczom.', 0),
(11100, 'koKR', '<Arcus szczerzy zęby.>$B$BNajzabójczejsza pułapka w dziejach...', 0),
(11101, 'koKR', '<Mor\'ghor wybucha śmiechem.>$B$BHA! Wiedziałem, że mnie nie zawiedziesz, dowódco! Chcę, żebyś co najmniej raz dziennie $gprowadził:prowadziła; najazd na Ołtarz Sha\'tar. Nie będą mieli innego wyjścia, jak opuścić Cienisty Księżyc!', 0),
(11107, 'koKR', 'Jesteś $gpierwszym najwyższym lordem:pierwszą najwyższą lady; Smoczych Paszcz, $N. Sam pan postanowił tu przybyć, by cię awansować.', 0),
(11544, 'koKR', 'Dziękuję, przyjacielu. Teraz będę mogła wykuć więcej szczególnego stopu, z którego powstaje broń i zbroje dla naszych wojsk.$b$bZostało mi też trochę wyciągu z tego procesu, który zapewne przyda ci się do broni. Proszę, wybierz, co ci najlepiej posłuży.$b$bWróć do mnie jutro. Bez wątpienia będę potrzebować więcej uzbrojenia.', 0),
(11752, 'koKR', 'Zbezcześć wielkie ognisko Przymierza w Dolinie Cienistego Księżyca!', 0),
(11779, 'koKR', 'Zbezcześć wielkie ognisko Hordy w Dolinie Cienistego Księżyca!', 0),
(11823, 'koKR', 'Uczcij płomień Doliny Cienistego Księżyca!', 0),
(11855, 'koKR', 'Uczcij płomień Doliny Cienistego Księżyca!', 0),
(13429, 'koKR', '<Xi\'ri pulsuje energią, a ty czujesz, jak w twoich dłoniach materializuje się jakiś przedmiot. To medalion, który w imieniu Akamy $gprzekazałeś:przekazałaś; A\'dalowi, a jego moc wzmocniła magia naaru. Sha\'tarowie powierzyli ci Medalion Karaboru, a wraz z nim dostęp do Czarnej Świątyni.>', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(10451, 'koKR', '$GOdnalazłeś:Odnalazłaś; siostrę Wildę?', 0),
(10458, 'koKR', 'Obawiam się, że dla tej krainy nie ma już nadziei.', 0),
(10480, 'koKR', 'Gdziekolwiek są nagi, tam niemal na pewno znajdziesz udręczone duchy wody.', 0),
(10481, 'koKR', 'Wkrótce przemówimy z duchami.', 0),
(10514, 'koKR', 'Dawaj te bulwy!', 0),
(10515, 'koKR', 'Bez litości!', 0),
(10519, 'koKR', 'Cierpliwości, $N. Słuchaj.', 0),
(10523, 'koKR', 'Udało ci się?', 0),
(10528, 'koKR', 'Ar\'tor unosi się przed tobą bez życia.', 0),
(10537, 'koKR', 'Nie lękaj się, $gbohaterze:bohaterko;. Gdy nadejdzie właściwa pora, pomogę ci...', 0),
(10540, 'koKR', 'Szyfr musi zostać odzyskany!', 0),
(10541, 'koKR', '<Pojedyncza łza spływa po policzku Oronoka.>', 0),
(10562, 'koKR', 'Już się $gzmęczyłeś:zmęczyłaś;, $N?', 0),
(10563, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(10564, 'koKR', '$GZnalazłeś:Znalazłaś; sposób, żeby zniszczyć zapas piekielników Legionu?', 0),
(10568, 'koKR', '$GZnalazłeś:Znalazłaś; już tablice, $N?', 0),
(10570, 'koKR', 'Pospiesz się, $gchłopcze:dziewczyno;.', 0),
(10571, 'koKR', 'Są już jakieś wieści, $N? Czas nie gra na naszą korzyść.', 0),
(10572, 'koKR', '<Wręczasz materiały dowódcy skrzydła.>', 0),
(10574, 'koKR', 'Masz już cztery fragmenty medalionu, $N?', 0),
(10576, 'koKR', 'To zbyt skomplikowane. I tak byś nie $gzrozumiał:zrozumiała;.', 0),
(10577, 'koKR', 'Przebranie jest delikatne. Niemal każda czynność poza chodzeniem zniszczy magię, która je trzyma w całości.', 0),
(10578, 'koKR', 'Musisz działać szybko!', 0),
(10579, 'koKR', '$N!', 0),
(10582, 'koKR', '$GUtorowałeś:Utorowałaś; już drogę do Kuźni Śmierci?', 0),
(10583, 'koKR', '$GZnalazłeś:Znalazłaś; w Kuźni Śmierci jakiś ślad Flanisa?', 0),
(10585, 'koKR', 'Nie możemy sobie pozwolić na to, żeby dalej produkowali. $GPołożyłeś:Położyłaś; już kres rytuałowi przywołania?', 0),
(10586, 'koKR', 'Jakie wieści przynosisz z Kuźni Śmierci?', 0),
(10589, 'koKR', 'Musimy znaleźć sposób, żeby zniszczyć resztę tych piekielników, $N. Zaszliśmy daleko, ale porażka wciąż może nas kosztować wszystko.', 0),
(10595, 'koKR', 'Już się $gzmęczyłeś:zmęczyłaś;, $N?', 0),
(10596, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(10597, 'koKR', '<Wręczasz materiały Gulmokowi.>', 0),
(10598, 'koKR', '$GZnalazłeś:Znalazłaś; sposób, żeby zniszczyć zapas piekielników Legionu?', 0),
(10600, 'koKR', '$GUtorowałeś:Utorowałaś; już drogę do Kuźni Śmierci?', 0),
(10601, 'koKR', '$GZnalazłeś:Znalazłaś; w Kuźni Śmierci jakiś ślad Kagrosha?', 0),
(10602, 'koKR', 'Nie możemy sobie pozwolić na to, żeby dalej produkowali. $GPołożyłeś:Położyłaś; już kres rytuałowi przywołania?', 0),
(10603, 'koKR', 'Jakie wieści przynosisz z Kuźni Śmierci?', 0),
(10604, 'koKR', 'Obecność Legionu w naszym sąsiedztwie jest nie do zniesienia! Musimy znaleźć sposób, żeby się z nim rozprawić, zanim wznowi atak.', 0),
(10606, 'koKR', 'Masz tę instrukcję?', 0),
(10611, 'koKR', 'Masz tę instrukcję?', 0),
(10612, 'koKR', '$GWróciłeś:Wróciłaś;, więc zakładam, że operacja się udała. Co masz do zameldowania?', 0),
(10613, 'koKR', '$GWróciłeś:Wróciłaś;, więc zakładam, że operacja się udała. Co masz do zameldowania?', 0),
(10619, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłem, $N?', 0),
(10622, 'koKR', '$GZrobiłeś:Zrobiłaś;, o co cię prosiłem, $N? W tych stronach niełatwo o zaufanie.', 0),
(10624, 'koKR', 'Jak to, co? Zrobię coś z popiołu – to chyba oczywiste.', 0),
(10625, 'koKR', 'Jeśli zgubisz gogle, daj mi znać, a zrobię ci nową parę.', 0),
(10626, 'koKR', '$GZdobyłeś:Zdobyłaś; te prototypy?', 0),
(10627, 'koKR', '$GZdobyłeś:Zdobyłaś; te prototypy?', 0),
(10634, 'koKR', 'Poleć na Występ Otchłanioskrzydłych i odzyskaj tę część.', 0),
(10635, 'koKR', 'Jeśli chcesz ujrzeć duchy Cienistego Księżyca, musisz użyć duchokularów.', 0),
(10636, 'koKR', 'Jeśli chcesz ujrzeć duchy Cienistego Księżyca, musisz użyć duchokularów.', 0),
(10637, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam?', 0),
(10642, 'koKR', 'Tak, istnieje tu dwoistość... Czuję ją.', 0),
(10643, 'koKR', 'Jeśli zgubisz gogle, daj mi znać, a zrobię ci nową parę.', 0),
(10645, 'koKR', 'Co ty mówisz?', 0),
(10647, 'koKR', 'Po nagrodę przychodzisz, mon?', 0),
(10648, 'koKR', 'Mam nadzieję, że $gzrobiłeś:zrobiłaś; coś wyjątkowego, $gchłopcze:dziewczyno;. Bo jak nie, to zmykaj!', 0),
(10651, 'koKR', '$GZrobiłeś:Zrobiłaś; to, o co cię prosiłam, $N?', 0),
(10660, 'koKR', 'Śledziony! Potrzebuję śledzion!', 0),
(10661, 'koKR', 'Śledziony! Potrzebuję śledzion!', 0),
(10672, 'koKR', 'Słuchaj, nie mam czasu ani ochoty tłumaczyć, co to wszystko znaczy. Po prostu oznakuj te diemetradony.', 0),
(10673, 'koKR', 'Rusz się! Apetyt tego gnoma nie zna granic!', 0),
(10677, 'koKR', 'Danie dnia: żołądek.', 0),
(10678, 'koKR', 'Danie dnia: skóra Spaczogrzbieta.', 0),
(10683, 'koKR', '$GZnalazłeś:Znalazłaś; już tablice, $N?', 0),
(10684, 'koKR', 'Są już jakieś wieści, $N? Czas nie gra na naszą korzyść.', 0),
(10685, 'koKR', 'Masz już cztery fragmenty medalionu, $N?', 0),
(10688, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam?', 0),
(10692, 'koKR', '$GZrobiłeś:Zrobiłaś; to, o co cię prosiłam, $N?', 0),
(10702, 'koKR', 'Wróć do mnie, gdy dzicz będzie na tyle bezpieczna, że nasze karawany zdołają ją przebyć.', 0),
(10703, 'koKR', 'Wróć do mnie, gdy dzicz będzie na tyle bezpieczna, że nasze karawany zdołają ją przebyć.', 0),
(10707, 'koKR', '$GWróciłeś:Wróciłaś;, $N.', 0),
(10750, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10751, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10765, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10768, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10772, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10773, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10774, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10775, 'koKR', 'Co masz do zameldowania, żołnierzu?', 0),
(10777, 'koKR', '$GOdzyskałeś:Odzyskałaś; totem od Asghara?', 0),
(10778, 'koKR', 'Udało ci się zdobyć różdżkę?', 0),
(10780, 'koKR', '$GZebrałeś:Zebrałaś; pióra do kostura?', 0),
(10782, 'koKR', '$GWróciłeś:Wróciłaś; z nasyconym nakryciem głowy?', 0),
(10793, 'koKR', '<Generał Auralion unosi się w środku kryształu.>$B$BCo... Co ty tu robisz?', 0),
(10804, 'koKR', 'Sam ich nie uratuję, $N!', 0),
(10807, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłem, $N?', 0),
(10808, 'koKR', 'Czy to już koniec, $N? $GPowstrzymałeś:Powstrzymałaś; Mroczne Konklawe przed dokończeniem rytuału?', 0),
(10814, 'koKR', 'Pozwól, że dokończę opowieść.', 0),
(10816, 'koKR', 'Witaj, $N. Jakie przynosisz wieści?', 0),
(10817, 'koKR', 'Witaj, $N. Jakie przynosisz wieści?', 0),
(10823, 'koKR', 'Co ostatnio dla nas $gzrobiłeś:zrobiłaś;, $N? Wojna z Kael\'thasem sama się nie wygra, wiesz?', 0),
(10824, 'koKR', 'Śmiało, $N. Mów.', 0),
(10836, 'koKR', 'Czy to już zrobione? Mogę tylko mieć nadzieję, że nie jest za późno...', 0),
(10837, 'koKR', 'Potrzebuję kryształów pnącza Otchłani.', 0),
(10854, 'koKR', 'Nie trać czasu, mamy wiele do zrobienia!', 0),
(10866, 'koKR', '<Karynaku jęczy.>', 0),
(10946, 'koKR', 'Czy zadanie wykonane, $N? Illidan nie jest cierpliwym panem!', 0),
(10947, 'koKR', '$GOdzyskałeś:Odzyskałaś; już filakterię, $N?', 0),
(10985, 'koKR', '<Xi\'ri dostrzega twoją obecność.>', 0),
(11013, 'koKR', '<Mor\'ghor chrząka.>$B$B$GSpóźniłeś:Spóźniłaś; się...', 0),
(11015, 'koKR', 'Kryształy Otchłani mają wiele zastosowań. Głównie robi się z nich broń i zbroje...', 0),
(11016, 'koKR', 'Skór obdzieraczy używamy do podszewek zbroi i plandek na konstrukcje.', 0),
(11017, 'koKR', 'Jak mówiłem, pyłku otchłaniopyłu używają nasi czarujący.', 0),
(11018, 'koKR', 'Gug tam dalej użyje tej rudy do wzmocnienia naszej broni i zbroi.', 0),
(11020, 'koKR', 'To brudna robota, $N.', 0),
(11035, 'koKR', 'Martwe orki nie mówią, $N. Dopilnuj, żeby ci przewoźnicy Smoczych Paszcz nie uciekli.', 0),
(11041, 'koKR', 'Kto śmie zbliżać się do Mor\'ghora? Lepiej, żeby to było coś ważnego.', 0),
(11049, 'koKR', 'Jak idzie polowanie na jaja?', 0),
(11050, 'koKR', 'Te jaja nie mogą trafić w niepowołane ręce, $N. Przynoś mi każde kolejne jajo, jakie znajdziesz.$B$BTylko pamiętaj, żeby się nie wychylać I nie wzbudzać podejrzeń!', 0),
(11054, 'koKR', 'Peony czekają na dyscyplinę, $N! Pośpiesz się!', 0),
(11055, 'koKR', 'Cała sztuka tkwi w nadgarstku, $N.', 0),
(11067, 'koKR', 'Trope pokonał kilku moich najlepszych jeźdźców. Nie daj się zwieść temu brudowi.', 0),
(11070, 'koKR', 'Mulverick to najbardziej utalentowany jeździec, jakiego w życiu widziałem. Od tytułu Orka nad Orkami dzieli go tylko jego lekkomyślność.', 0),
(11071, 'koKR', 'Drugie miejsce to nie taki wstyd, $N. Możesz zająć miejsce Mulvericka w składzie...', 0),
(11076, 'koKR', '$GZebrałeś:Zebrałaś; ładunek?', 0),
(11077, 'koKR', 'Jak idzie walka z plagą obdzieraczy?', 0),
(11081, 'koKR', 'Co to jest?', 0),
(11082, 'koKR', 'No i? Czemu to tyle trwa?', 0),
(11083, 'koKR', 'Problem „rozwiązany”?', 0),
(11086, 'koKR', 'W końcu to nasz pan wygnał demony z Rubieży i zamknął ich portale. Wszyscy powinni bić pokłony przed wspaniałością Illidana.', 0),
(11089, 'koKR', '$GZebrałeś:Zebrałaś; części potrzebne do sporządzenia działa dusz?', 0),
(11094, 'koKR', 'Uspokój się, dziecko.', 0),
(11095, 'koKR', '<Hobb kiwa głową.>', 0),
(11097, 'koKR', '$GZmiażdżyłeś:Zmiażdżyłaś; ich butem, dowódco?', 0),
(11099, 'koKR', 'Uspokój się, dziecko.', 0),
(11100, 'koKR', '<Arcus kiwa głową.>', 0),
(11101, 'koKR', '$GZmiażdżyłeś:Zmiażdżyłaś; ich butem, dowódco?', 0),
(11486, 'koKR', 'Co to jest?', 0),
(11544, 'koKR', 'Potrzebuję całego oczyszczonego metalu Ata\'mal, jaki tylko zdołam zdobyć, $N.', 0),
(13663, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0);
