INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2989, 'koKR', 'Dowódco,\n\nSzyfr ma zostać dostarczony Zuluhedowi. Pozostanie pod jego pieczą do odwołania.\n\n-Lord Illidan Burzogniewny', 0),
(2993, 'koKR', 'Mój drogi Kanclerzu,\n\nZadanie przeciągnięcia olbrzymów Cienistego Księżyca na naszą stronę spoczywa teraz w twoich zdolnych rękach. Użyj swojego uroku krwawego elfa, by przekonać ich do mojego punktu widzenia. Jeśli to nie poskutkuje, wytęp ich wszystkich co do jednego...\n\n-Lord Illidan Burzogniewny', 0),
(3006, 'koKR', 'W imię naszego wielkiego pana... Ku chwale Illidana!\n\nMor\'ghorze,\n\nPosyłam ci tego nędznika jako sługę Illidana. Choć nie ma przyszłości jako rycerz śmierci, być może jego umiejętności przypadną ci do gustu. Zmuś go biciem do posłuszeństwa. Uczyń z niego wojownika Illidari.\n\nA jeśli zawiedzie... Jeśli okaże słabość... Pozbądź się go. Do dołów z nim!\n\nLord Teron Krwawy Bies', 0),
(3028, 'koKR', 'W imię naszego wielkiego pana... Ku chwale Illidana!\n\nPospolite składniki działa dusz można zdobyć dzięki różnym profesjom. Inżynierowie i górnicy powinni dostarczyć ci sztabki spaczostali, rdzeń energetyczny z khorium i ramę z adamantytu.\n\nPo nieskazitelną tajemną esencję musisz się udać do Puszczy Terokkar. W środku puszczy, powyżej placówki Hordy, Warowni Kamieniołamaczy, znajdziesz siedzibę Sar\'thisa, heretyka arakkoa. Okolica ta nazywa się Jezioro Jorune.\n\nPorozmawiaj z Sar\'thisem i powiedz mu, czego szukasz. Koniecznie wspomnij, że to ja cię przysłałem, bo jest mi winien przysługę czy dwie.\n\nZrób, o co poprosi Sar\'this, a esencja powinna trafić w twoje ręce.\n\n-Balthas', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(22861, 0, 0, 'koKR', 'Podejdź bliżej, demonie! Czeka cię śmierć!'),
(22861, 0, 1, 'koKR', 'Pieski Illidana! Zniszczyć ich wszystkich!'),
(22863, 0, 0, 'koKR', 'Podejdź bliżej, demonie! Czeka cię śmierć!'),
(22863, 0, 1, 'koKR', 'Pieski Illidana! Zniszczyć ich wszystkich!'),
(22917, 7, 0, 'koKR', 'Czuję waszą nienawiść.'),
(22917, 7, 1, 'koKR', 'Poddajcie się strachowi!'),
(22917, 7, 3, 'koKR', 'Cóż za... arogancja!'),
(23434, 1, 0, 'koKR', 'Wyprostować się, żołnierze. Żadnej litości!'),
(23440, 1, 1, 'koKR', 'Niech żyją Smocze Paszcze! Giń, $gnędzny:nędzna; $N!'),
(23440, 1, 2, 'koKR', 'Twoje kości pękną pod moim butem, $N'),
(23441, 1, 1, 'koKR', 'Niech żyją Smocze Paszcze! Giń, $gnędzny:nędzna; $N!'),
(23441, 1, 2, 'koKR', 'Twoje kości pękną pod moim butem, $N');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1690, 'koKR', 'Zabić ich wszystkich!', '', 0),
(16557, 'koKR', 'Jak zobaczę tu jakieś leniwe peony, załaduję je do katapulty i wystrzelę prosto do Czarnej Świątyni!', 'Jak zobaczę tu jakieś leniwe peony, załaduję je do katapulty i wystrzelę prosto do Czarnej Świątyni!', 0),
(16559, 'koKR', 'Jeśli któryś z was, peonów, zechce sobie zrobić przerwę, cmentarz jest tuż obok.', 'Jeśli któryś z was, peonów, zechce sobie zrobić przerwę, cmentarz jest tuż obok.', 0),
(16586, 'koKR', 'Bron! Ej, Bron! Walnij mnie!', '', 0),
(16587, 'koKR', '%s mruga, a na jego twarzy maluje się konsternacja.', '', 0),
(16588, 'koKR', 'Co, pięściami?', '', 0),
(16589, 'koKR', 'Nie, to dla mięczaków. Walnij mnie młotem!', '', 0),
(16590, 'koKR', 'Nie... nie wiem, czy to dobry pomysł, Moke. Jeszcze ci się coś stanie...', '', 0),
(16591, 'koKR', 'ZRÓB TO, MAMINSYNKU!', '', 0),
(16592, 'koKR', 'Eee... Moke?', '', 0),
(16593, 'koKR', '...TO BYŁO SUPER!', '', 0),
(16654, 'koKR', 'Piękna jest, co? Sky\'ree... wierna gryfica naszego dowódcy. Sam Kurdran przyjmuje gości w warowni. Kiedy jest zajęty, ja zajmuję się naszą Sky\'ree. Cudne stworzenie; silna i dzika jak mało która. Oddałaby życie za Kurdrana, oj tak. Wierniejszej duszy nie $gwidziałeś:widziałaś;.\nTo zaszczyt się nią opiekować, a jakże.', '', 0),
(17140, 'koKR', '%s ryczy wyzywająco.', '', 0),
(17711, 'koKR', 'Zachować czujność!', 'Zachować czujność!', 0),
(17713, 'koKR', 'Uważajcie na intruzów.', 'Uważajcie na intruzów.', 0),
(17715, 'koKR', 'Nie wolno nam zawieść pana.', 'Nie wolno nam zawieść pana.', 0),
(18146, 'koKR', 'Zrozumiano.', 'Zrozumiano.', 0),
(18410, 'koKR', 'Nie zawiedziemy.', 'Nie zawiedziemy.', 0),
(18664, 'koKR', 'Dziękuję ci, uzdrowicielko ziemi.', '', 0),
(18665, 'koKR', '', 'Dziękuję ci, dobra duszo. $GUwolniłeś:Uwolniłaś; mnie z wodnego więzienia Szramowijów, ale w pobliżu przetrzymują jeszcze wielu innych. Czy pomożesz mi uwolnić także ich?', 0),
(18668, 'koKR', '', 'Wyczuwam udręczone duchy, $n. Są tędy. Szybko!', 0),
(18669, 'koKR', '', 'Chroń mnie, $n. Muszę przełamać ich plugawą magię!', 0),
(18670, 'koKR', '', 'Teraz musimy znaleźć wyjście.', 0),
(18671, 'koKR', '', 'To już niedaleko, $n. Wyjście jest tuż przed nami.', 0),
(18672, 'koKR', '', 'Dziękuję, $n. Wróć, proszę, do moich braci przy Ołtarzu Potępienia, w pobliżu Ręki Gul\'dana, i powiedz im, że Wilda jest bezpieczna. Niech Matka Ziemia czuwa nad tobą...', 0),
(18673, 'koKR', '', 'Nagi nie szanują natury. Wypaczają ją i psują, by służyła ich potrzebom. Żyją po to, by niepokoić duchy.', 0),
(18675, 'koKR', '', 'Burzliwa natura wielkich wód Azeroth i Draenoru to bezpośredni skutek udręki duchów wody.', 0),
(18684, 'koKR', '', 'Lady Vash musi odpowiedzieć za te okrucieństwa. Musi stanąć przed sądem!', 0),
(18685, 'koKR', '', 'Nagi ze Szramowijów są wyjątkowo okrutne dla swoich więźniów. To cud, że przetrwałam w tym wodnym więzieniu tak długo. Chwała Matce Ziemi.', 0),
(18687, 'koKR', '', 'Uważaj!', 0),
(18688, 'koKR', '', 'Nagi atakują! Broń się!', 0),
(18692, 'koKR', 'Zabić ich wszystkich!', '', 0),
(18694, 'koKR', 'Rozedrzyj tę ziemię, Gul\'danie! Zerwij więź!', 'Rozedrzyj tę ziemię, Gul\'danie! Zerwij więź!', 0),
(18695, 'koKR', 'Opuściły nas! Nie zapominajcie!', 'Opuściły nas! Nie zapominajcie!', 0),
(18696, 'koKR', 'Weźmiemy od ziemi siłą, jeśli nie zechce dać!', 'Weźmiemy od ziemi siłą, jeśli nie zechce dać!', 0),
(18697, 'koKR', 'Nie rób tego, Gul\'danie! Żywioły nigdy nam nie wybaczą!', 'Nie rób tego, Gul\'danie! Żywioły nigdy nam nie wybaczą!', 0),
(18698, 'koKR', 'Przestań! Musisz przestać!', 'Przestań! Musisz przestać!', 0),
(18699, 'koKR', 'Pomyśl o naszych dzieciach, Gul\'danie! Zniszczysz nas wszystkich!', 'Pomyśl o naszych dzieciach, Gul\'danie! Zniszczysz nas wszystkich!', 0),
(18700, 'koKR', 'Skazałeś nas wszystkich na potępienie... Jesteśmy zgubieni.', 'Skazałeś nas wszystkich na potępienie... Jesteśmy zgubieni.', 0),
(18701, 'koKR', 'Milczeć! Rozbicie wkrótce nastąpi!', '', 0),
(18702, 'koKR', 'Bądźcie świadkami niezaprzeczalnej potęgi naszego mrocznego pana!', '', 0),
(18703, 'koKR', 'Dzięki jego darowi zrównam tę ziemię z ziemią i ukształtuję ją na nowo!', '', 0),
(18704, 'koKR', 'Patrzcie! Patrzcie, jak ziemia pęka przed nami! Patrzcie, jak płynie energia! Wykarmi nasze armie...', '', 0),
(18705, 'koKR', 'Nigdy nie zabraknie nam mocy! Zapewniłem nam przyszłość! Grzejcie się w blasku mojej chwały!', '', 0),
(18706, 'koKR', 'Stało... się...', '', 0),
(18736, 'koKR', 'To tutaj Gul\'dan zerwał więź między orkami a duchami żywiołów. Jego nienasyconego głodu władzy nie zaspokoiła nawet całkowita zagłada draenei. Musiał zniszczyć także Draenor, pustosząc ziemię i wysysając z niej całą energię na potrzeby swojej wojny.$B$BTeraz pozostały tylko ślady jego szaleństwa.$B$BSpójrz na ołtarz, $N – ta ziemia jest nawiedzona na zawsze...', '', 0),
(18749, 'koKR', 'Odsuń się, $n. Duchy mogą zaatakować.', '', 0),
(18752, 'koKR', '%s się kłania.', '', 0),
(18753, 'koKR', 'Chcemy ci pomóc, duchu. Szukamy twojej mądrości.', '', 0),
(18757, 'koKR', 'Masz rację, duchu. To mój lud ci to zrobił. Pozwól nam to naprawić.', '', 0),
(18758, 'koKR', 'Powiedz nam, proszę: kim lub czym jest Cyrukh?', '', 0),
(18760, 'koKR', 'Władca... Władca Ognia? Wydobyto na światło dzienne władcę żywiołów? Ależ oczywiście... Gul\'danie, ty przeklęty głupcze!', '', 0),
(18762, 'koKR', 'Musi być jakiś sposób.', '', 0),
(18764, 'koKR', 'Nie wątp we mnie i moich towarzyszy, duchu. Powiedz nam, jak przywołać Władcę Ognia. Moi sojusznicy go zniszczą.', '', 0),
(18768, 'koKR', 'Znajdziemy te słowa. Przywołamy twego pana i go zniszczymy.', '', 0),
(18778, 'koKR', 'Teraz odzyskajmy utracone słowa!', '', 0),
(18833, 'koKR', 'Witaj, wędrowcze. Jestem Oronok. Proszę, usiądź przy moim ognisku i ogrzej się.$B$BStrzeż się wygłodniałych bestii ze Strzaskanej Półki pod nami!', '', 0),
(18834, 'koKR', 'Co masz na sprzedaż, Oronoku?', 'Co masz na sprzedaż, Oronoku?', 0),
(18934, 'koKR', 'Czy jesteś $ggotów:gotowa; wysłuchać historii Szyfru Potępienia, $n?', '', 0),
(18935, 'koKR', 'Jestem $ggotów:gotowa; wysłuchać twojej opowieści, Oronoku.\n', 'Jestem $ggotów:gotowa; wysłuchać twojej opowieści, Oronoku.\n', 0),
(18936, 'koKR', 'Dobrze. Słowa, których szukasz, mają nazwę, $n. Znane są jako Szyfr Potępienia: słowa, które wypowiedział sam Gul\'dan, by rozbić tę ziemię. To właśnie zaklęcie zerwało ostatnią więź, jaka łączyła orki z żywiołami Draenoru.$B$B<Oronok kiwa głową.>$B$BTak, to szyfr musisz odtworzyć, a na koniec wypowiedzieć jego słowa.', '', 0),
(18937, 'koKR', 'Jak mam odnaleźć szyfr?', 'Jak mam odnaleźć szyfr?', 0),
(18938, 'koKR', 'Szyfr Potępienia przez dwadzieścia lat przechowywano w prywatnych komnatach Gul\'dana w Karaborze. Ach, no tak, przecież nie masz pojęcia, czym jest Karabor, prawda?$B$BCzarna Świątynia...$B$BTak, teraz siedziba Illidana Burzogniewnego.$B$BGdy Illidan przejął Czarną Świątynię, odkrył szyfr. Zdawał sobie sprawę, że szkoda temu światu już się dokonała, ale uznał, że rozsądnie będzie zabezpieczyć szyfr na później.', '', 0),
(18940, 'koKR', 'Gdy stoisz przy Ołtarzu Potępienia i widzisz duchy potępionych klęczące w modlitwie, nie widzisz mnie, stojącego obok Gul\'dana.$B$B<Oronok kiwa głową.>$B$BMówiłem ci, że byłem już wieloma rzeczami, prawda? Jedną z tych „rzeczy” był porucznik Gul\'dana.$B$BZrobiłem w życiu wiele strasznych rzeczy. Zarzynałem mężczyzn, kobiety i dzieci. Tańczyłem we krwi niewinnych draenei... a jednak...$B$B<Oronokowi słowa więzną w gardle.>', '', 0),
(18941, 'koKR', 'A jednak co? O co chodzi, Oronoku?', 'A jednak co? O co chodzi, Oronoku?', 0),
(18942, 'koKR', 'Nigdy nie zapomnę tego dnia, $N. Nigdy. Choć dawno porzuciłem szamanizm na rzecz magii cienia, poczułem to cięcie. Poczucie straty tak głębokie... Nie potrafię ci go opisać samymi słowami.$B$BGdy więź z żywiołami została zerwana, wszystkie orki na Draenorze się zmieniły. Jeśli ktokolwiek miał jeszcze wątpliwości co do potęgi cieni, zmyła je fala roztopionej lawy wzbierająca nad strzaskaną ziemią.\n', '', 0),
(18944, 'koKR', 'Zalała mnie fala mdłości. Gdy rytuał dobiegł końca, pobiegłem do domu, do moich dzieci. Zebrałem tyle dobytku, ile mogłem unieść w rękach, i odszedłem z moimi chłopcami. Uciekliśmy w góry i się ukryliśmy. Naprawdę nie było innego wyjścia...$B$BNie ma dnia, żebym nie myślał o tym cięciu. Ponowne połączenie z żywiołami zajęło 20 lat. Minęło 20 lat, zanim żywioły w ogóle zaczęły się goić.', '', 0),
(18945, 'koKR', 'A co teraz z szyfrem? I z twoimi chłopcami?', 'A co teraz z szyfrem? I z twoimi chłopcami?', 0),
(18946, 'koKR', 'Jak mówiłem, Illidan znalazł szyfr, kiedy przejął Czarną Świątynię. Podzielił księgę na trzy części i powierzył je pieczy swoich sług.$B$BMoi chłopcy... Moi chłopcy są już dorośli. Gdy dotarła do mnie wieść, co Illidan zrobił z szyfrem, wysłałem chłopców, by odzyskali te części.$B$BMusisz odnaleźć moich chłopców, $n. Musisz ich odnaleźć i odzyskać Szyfr Potępienia.', '', 0),
(18947, 'koKR', 'Odnajdę twoich chłopców i szyfr, Oronoku.', 'Odnajdę twoich chłopców i szyfr, Oronoku.', 0),
(18954, 'koKR', 'Koniec z uprzejmymi prośbami, rybia gębo.', '', 0),
(18955, 'koKR', 'Gdzie jest Szyfr Potępienia? Wiem, że jedna trzecia jest w tej wiosce.', '', 0),
(18956, 'koKR', 'O czymmm... ty mówisssz, miękkossskóry?', '', 0),
(18957, 'koKR', 'Nagi nie mająąą... tego... szyfrrru...', '', 0),
(18958, 'koKR', 'Nie... No jasne, że nie. Co ja sobie myślałem? Po co miałbyś trzymać jedną trzecią Szyfru Potępienia?', '', 0),
(18959, 'koKR', 'Ale ze mnie głupiec. Może powinienem cię rozkuć i puścić wolno?', '', 0),
(18960, 'koKR', 'NAPRAWDĘ WYGLĄDAM NA TAKIEGO GŁUPKA, NAGO? TERAZ POCZUJESZ BÓL!', '', 0),
(18961, 'koKR', 'Tak... tak... Uwolnij mnie...', '', 0),
(18962, 'koKR', '%s pluje na nagę ze Szramowijów.', '', 0),
(18963, 'koKR', 'WSTAWAJ, ZGNIŁY ŚMIECIU! WSTAWAJ, ZANIM Z TOBĄ SKOŃCZĘ!', '', 0),
(18965, 'koKR', 'Nie bij już dowódcy Szramowijóóów, orku! Powiem ci! Szyfrrr... Jest ukryty w jednej ze skrzyń na Cyplu Szramowijóóów... Klucze mająąą nagi, które tam sssą...', '', 0),
(18966, 'koKR', 'Słucham...', '', 0),
(18967, 'koKR', 'SZRAMOWIJEEE!', '', 0),
(18971, 'koKR', 'Martwe ciało Ar\'tora wisi w powietrzu, podtrzymywane demoniczną magią. Czerpią z niego nawet po śmierci...', '', 0),
(18978, 'koKR', 'Ja... umarłem.$B$BCzemu wciąż tu jestem? Czy nie czekają na mnie wielkie łowiska, do których mam się wznieść?$B$BNie... Najpierw muszę wykonać swoje zadanie. Zanim opuszczę ten świat, trzeba odzyskać drugą część Szyfru Potępienia.', 'Ja... umarłem.$B$BCzemu wciąż tu jestem? Czy nie czekają na mnie wielkie łowiska, do których mam się wznieść?$B$BNie... Najpierw muszę wykonać swoje zadanie. Zanim opuszczę ten świat, trzeba odzyskać drugą część Szyfru Potępienia.', 0),
(18993, 'koKR', 'Ja... ja umarłem... Tak bardzo cierpiałem... pochłonęła mnie ciemność... Widzisz mnie, $N?', '', 0),
(19017, 'koKR', 'Potrzebuję pomocy kolejnego łowcy duchów, Ar\'torze.', 'Potrzebuję pomocy kolejnego łowcy duchów, Ar\'torze.', 0),
(19150, 'koKR', 'Władca zagłady Kazzak będzie zadowolony. Macie zwiększyć tempo ataków. Zniszczcie warownie orków i krasnoludów tak szybko, jak się da.', '', 0),
(19151, 'koKR', 'Nie martw się tym. Zwiększyłem produkcję w Kuźni Śmierci. Będziesz mieć tyle piekielników, ile trzeba do wykonania rozkazów. Nie zawiedź, Jovaanie.', '', 0),
(19251, 'koKR', 'Kto śmie przeszkadzać wielkiemu dowódcy?', '', 0),
(19260, 'koKR', 'Przynoszę wieści od lorda Illidana.', 'Przynoszę wieści od lorda Illidana.', 0),
(19262, 'koKR', 'Fragment szyfru ma zostać przeniesiony. Każ go dostarczyć Zuluhedowi.', 'Fragment szyfru ma zostać przeniesiony. Każ go dostarczyć Zuluhedowi.', 0),
(19265, 'koKR', 'Och? Oczywiście masz dokumenty potwierdzające to polecenie.', '', 0),
(19266, 'koKR', 'Może mnie nie dosłyszałeś, Ruusku. Wydaję ci rozkaz od samego Illidana!', 'Może mnie nie dosłyszałeś, Ruusku. Wydaję ci rozkaz od samego Illidana!', 0),
(19267, 'koKR', 'Słuchaj no, peonie. Mamy ustaloną procedurę dostarczania i przechowywania fragmentu szyfru. Wysłannik dostarcza pismo opieczętowane przez lorda Illidana. Nie ma pisma, nie ma przekazania.', '', 0),
(19268, 'koKR', 'Dobrze. Wrócę do Czarnej Świątyni i powiadomię lorda Illidana, że nie chcesz spełnić jego woli. Radzę ci uporządkować sprawy z podwładnymi i dać im znać, że wkrótce opuścisz ten świat.', 'Dobrze. Wrócę do Czarnej Świątyni i powiadomię lorda Illidana, że nie chcesz spełnić jego woli. Radzę ci uporządkować sprawy z podwładnymi i dać im znać, że wkrótce opuścisz ten świat.', 0),
(19269, 'koKR', '<Ruusk z trudem przełyka ślinę.>$B$BCo... Co masz na myśli?', '', 0),
(19270, 'koKR', 'Mam się wdawać we wszystkie krwawe szczegóły? Chyba dobrze wiemy, co lord Illidan robi z tymi, którzy sprzeciwiają się jego słowu. A teraz muszę już iść! Żegnaj, Ruusku! Na zawsze...\n', 'Mam się wdawać we wszystkie krwawe szczegóły? Chyba dobrze wiemy, co lord Illidan robi z tymi, którzy sprzeciwiają się jego słowu. A teraz muszę już iść! Żegnaj, Ruusku! Na zawsze...\n', 0),
(19271, 'koKR', 'Czekaj. Dokąd idziesz? Potrzebne było przekazanie, tak? Po prostu to załatwmy i miejmy z głowy, dobrze? Zuluhed u Smoczych Paszcz? Załatwione. Przekaż, proszę, lordowi Illidanowi, że jego rozkazy wykonano przy pełnej współpracy Zaćmienia.$B$BWyślę Ruula Zaciemniacza, żeby osobiście dostarczył fragment!$B$BDobrze słyszysz – Ruula...\n', '', 0),
(19272, 'koKR', 'Ach, dobrze, że zmieniłeś zdanie, Ruusku. Dziękuję i żegnaj.', 'Ach, dobrze, że zmieniłeś zdanie, Ruusku. Dziękuję i żegnaj.', 0),
(19281, 'koKR', 'Skrzynię? Nie wysyłałem ci żadnej skrzyni, Jovaanie. Nie masz ważniejszych spraw na głowie? Zajmij się nimi!', '', 0),
(19290, 'koKR', 'Twój świat dobiegł końca.', '', 0),
(19291, 'koKR', 'Niebo pociemnieje i wszystko ucichnie. Dopiero wtedy poznasz słodki spokój śmierci...', '', 0),
(19298, 'koKR', 'Cyrukh się przebudził!', '', 0),
(19299, 'koKR', 'Będziecie cierpieć wiecznie!', '', 0),
(19301, 'koKR', 'Cyrukh po was idzie!', '', 0),
(19302, 'koKR', 'Ci, którzy ważą się igrać z ogniem, spłoną na popiół!', '', 0),
(19303, 'koKR', 'Formuje się płonący wir.', '', 0),
(19308, 'koKR', 'Mała istoto z ciała, twoje życzenie się spełni! Nadchodzi po ciebie śmierć!', '', 0),
(19314, 'koKR', '', 'Chwała naaru, $n. Światłość wkrótce zatriumfuje nad swoimi wrogami.', 0),
(19325, 'koKR', 'Wygląda na to, że krasnoluda odkryto i zabito w trakcie misji szpiegowskiej. Słudzy Kuźni Śmierci zostawili zwłoki na widoku, być może jako ostrzeżenie dla innych intruzów.', '', 0),
(19326, 'koKR', 'Odzyskaj plecak Flanisa.', 'Odzyskaj plecak Flanisa.', 0),
(19336, 'koKR', 'Słyszę to, co ty, bracie. Spójrz za siebie...', '', 0),
(19395, 'koKR', '', 'Uwolnij mnie natychmiast albo poczuj mój gniew!', 0),
(19399, 'koKR', 'Zwłoki orka niedbale odrzucono na bok, żeby nie zaśmiecały przejścia.', '', 0),
(19400, 'koKR', 'Przeszukaj zwłoki w poszukiwaniu plecaka Kagrosha.', 'Przeszukaj zwłoki w poszukiwaniu plecaka Kagrosha.', 0),
(19407, 'koKR', '', 'Jeśli naprawdę pragniemy tego samego, Akamo, to mnie uwolnij! Jeśli Illidan ma zginąć, to z mojej ręki!', 0),
(19409, 'koKR', '', 'Przeklinam cię, Akamo! Nie jestem pionkiem w twojej grze... moja wola należy do mnie. Gdy rozpętam swój gniew na Illidanie, nie będzie to miało nic wspólnego z twoim głupim planem!', 0),
(19410, 'koKR', 'Wszystkie nagrody za wykonane usługi wydaje herold wojny Sardon Celnocios.$B$BZakaz naklejania ogłoszeń.', '', 0),
(19411, 'koKR', 'Wszystkie nagrody za wykonane usługi wydaje herold wojny Piworyj.$B$BZakaz naklejania ogłoszeń.', '', 0),
(19413, 'koKR', 'Z taką nagrodą, jak mogą odmówić, mon?', '', 0),
(19444, 'koKR', 'Nigdy się nie rozproszymy, $gśmiertelniku:śmiertelniczko;... Nasz los jest związany z Krwawym Biesem...', 'Nigdy się nie rozproszymy, $gśmiertelniku:śmiertelniczko;... Nasz los jest związany z Krwawym Biesem...', 0),
(19445, 'koKR', 'Módl się, by lodowate objęcia Terona Krwawego Biesa nie sięgnęły po ciebie...', 'Módl się, by lodowate objęcia Terona Krwawego Biesa nie sięgnęły po ciebie...', 0),
(19446, 'koKR', 'To ty $gnajechałeś:najechałaś; nasz dom. Krwawy Bies nas pomści!', 'To ty $gnajechałeś:najechałaś; nasz dom. Krwawy Bies nas pomści!', 0),
(19447, 'koKR', 'Krwawy Bies zetnie ci głowę, intruzie!', 'Krwawy Bies zetnie ci głowę, intruzie!', 0),
(19448, 'koKR', 'Jesteśmy tu uwięzieni... na wieki. Taka jest wola Krwawego Biesa.', 'Jesteśmy tu uwięzieni... na wieki. Taka jest wola Krwawego Biesa.', 0),
(19480, 'koKR', 'Teron Krwawy Bies? Tak... Wiem o nim.', '', 0),
(19494, 'koKR', 'Twoje ciało należy do mnie! Nasze losy są na zawsze splecione.', '', 0),
(19503, 'koKR', 'Nie trać czasu, głupcze! Użyj naszej mocy, by zabić tych, którzy staną nam na drodze! Zniszcz Karsiusa, zanim cię obezwładni!', '', 0),
(19504, 'koKR', 'Twoja żałosna próba ucieczki nie potrwa długo, Krwawy Biesie. Uwolnij $gchłopaka:dziewczynę; i się poddaj! Nawet w swojej zbroi i ze swoją bronią nie pokonasz pradawnych!', '', 0),
(19505, 'koKR', 'Niech to będzie nauczka dla tych, którzy chcieliby czynić zło naszym ziemiom!', '', 0),
(19506, 'koKR', 'Coś ty... $gzrobił:zrobiła;...', '', 0),
(19508, 'koKR', 'Jeszcze się spotkamy... Kiedyś.', '', 0),
(19509, 'koKR', 'Wcielona śmierć znów została uwolniona na świat! Teron Krwawy Bies powrócił...', '', 0),
(19577, 'koKR', 'Pieski Illidana! Zapłacicie życiem za moje uwięzienie!', '', 0),
(19608, 'koKR', 'Czego ode mnie chcesz, szamanie?', '', 0),
(19609, 'koKR', 'Nie masz oczu? Nie widziałeś demonów u samego progu? Nie mam żołnierzy na zbyciu!', '', 0),
(19610, 'koKR', 'Módl się do swoich bogów, szamanie. Może oni ci pomogą. Horda jednak nie może...', '', 0),
(19612, 'koKR', 'Nie rozumiem! Ślepyś? Nie widzisz, że demony walą nam do drzwi? Kogo niby mam wysłać na rozmowy z twoimi kumplami szamanami? Pokaż mi go!', '', 0),
(19666, 'koKR', 'Ustawiłem na zboczu kilka konsol sterujących. Szybko dostań się do jednej z nich i przejmij kontrolę nad grabieżcą Spaczenia! Będziesz mieć ograniczoną ilość czasu.', '', 0),
(19675, 'koKR', 'Mów szybko, $n. Nie mamy wiele czasu!', 'Mów szybko, $n. Nie mamy wiele czasu!', 0),
(19693, 'koKR', '', 'Użycz nam siły olbrzymów z Cienistego Księżyca, Coroku. Pan jest sprawiedliwym władcą. Na pewno zadba o tych, którzy pomogli poskromić buntowników tego świata.', 0),
(19695, 'koKR', 'A... jeśli tego nie zrobimy?', '', 0),
(19696, 'koKR', '', 'Wtedy staniecie się wrogami mojego pana, Illidana. Wrogowie Illidana zostają zniszczeni. Czy twoje olbrzymy zdołają odeprzeć atak sił z Punktu Zaćmienia?', 0),
(19697, 'koKR', '', 'Nie... Tak myślałam...', 0),
(19707, 'koKR', '$GDotarłeś:Dotarłaś; aż tutaj, $gsiepaczu:siepaczko;. Teraz nie ma już odwrotu.', '', 0),
(19708, 'koKR', '$GZgubiłem:Zgubiłam; rakietnicę Kor\'kronu, panie. Mogę dostać drugą?', '$GZgubiłem:Zgubiłam; rakietnicę Kor\'kronu, panie. Mogę dostać drugą?', 0),
(19722, 'koKR', '<Arakkoa obdarza cię udręczonym spojrzeniem, raz patrząc na ciebie, a raz jakby przez ciebie.>$B$BCóż sprowadziły nasze wysiłki, jeśli nie jeszcze większą ohydę niż ta, której chcieliśmy zapobiec?', '', 0),
(19737, 'koKR', 'Zuchwale zaatakowałeś moje dzieci, Illidanie! Pakt został zerwany. Olbrzym nigdy nie stanie po stronie elfa! NIGDY!', '', 0),
(19739, 'koKR', '%s ryczy wyzywająco.', '', 0),
(19742, 'koKR', 'Co jest, $N? Masz jakieś nowe informacje?', 'Co jest, $N? Masz jakieś nowe informacje?', 0),
(19744, 'koKR', 'Nigdy nie zdobędziecie Serca Furii! Jego moc należy do Illidana!', '', 0),
(19746, 'koKR', 'No to o co chodzi? Nie widzisz, że jestem zajętym krasnoludem?', '', 0),
(19747, 'koKR', 'Potrzebuję nowej rakietnicy Dzikiego Młota, thanie.', 'Potrzebuję nowej rakietnicy Dzikiego Młota, thanie.', 0),
(19759, 'koKR', 'Ratuj się, $N. Uciekaj z tego miejsca! Karmazynowy Symbol zgładzi cię na miejscu, jeśli cię odkryją.', 'Ratuj się, $N. Uciekaj z tego miejsca! Karmazynowy Symbol zgładzi cię na miejscu, jeśli cię odkryją.', 0),
(19807, 'koKR', '', 'Musisz... uwolnić... moje dzieci...', 0),
(19809, 'koKR', 'Nie wytrzymają tak w nieskończoność! W końcu opadną im skrzydła...', '', 0),
(19820, 'koKR', 'Panie... Zawiodłem cię...', '', 0),
(19830, 'koKR', '%s odzyskuje Serce Furii.', '', 0),
(19849, 'koKR', 'Dziękuję ci, $gśmiertelniku:śmiertelniczko;.', '', 0),
(19862, 'koKR', 'Witaj, $gśmiertelniku:śmiertelniczko;.', '', 0),
(19863, 'koKR', 'Słucham cię, smoku.', 'Słucham cię, smoku.', 0),
(19864, 'koKR', 'We wschodniej części Pól Otchłanioskrzydłych leży Forteca Smoczych Paszcz. To tam okrutny orkowy klan Smoczych Paszcz torturuje pojmane smokowce, próbując nagiąć je do swojej woli. Wiele z nich straciło nadzieję i woli teraz wykonywać polecenia Smoczych Paszcz. Pozostałe... Nie chcą lądować w obawie, że oddziały wojenne Smoczych Paszcz je pojmą i zabiorą z powrotem do fortecy.', '', 0),
(19865, 'koKR', 'Przecież jesteście smokami! Jak orki mogły wam to zrobić?', 'Przecież jesteście smokami! Jak orki mogły wam to zrobić?', 0),
(19866, 'koKR', 'Ja... My jesteśmy bezsilni. Illidan odnalazł i oddał Smoczym Paszczom ich przywódcę – Zuluheda. To ten ork odpowiadał za pojmanie i uwięzienie Alexstrazy. Jak mielibyśmy walczyć z taką potęgą? Pojmał Aspekt!$B$BI równie łatwo zabrał moją partnerkę.', '', 0),
(19867, 'koKR', 'Twoją partnerkę?', 'Twoją partnerkę?', 0),
(19868, 'koKR', '<Neltharaku kiwa głową.>$B$BKarynaku... Jest więziona na szczycie Fortecy Smoczych Paszcz. Wiele razy próbowałem ją uwolnić. Wszystkie próby zawiodły... $GWalczyłeś:Walczyłaś; już z tymi bestiami, prawda?\n', '', 0),
(19869, 'koKR', '$GWalczyłem:Walczyłam; z wieloma bestiami, smoku. Pomogę ci.', '$GWalczyłem:Walczyłam; z wieloma bestiami, smoku. Pomogę ci.', 0),
(20126, 'koKR', 'Lordzie Illidanie, pobłogosław mnie mocą stada!', '', 0),
(20127, 'koKR', 'Głupi śmiertelnicy. Myśleliście, że nie ukarzę was za wasze występki?', '', 0),
(20128, 'koKR', 'Owszem, nadszedł czas, by skończyć tę maskaradę.', '', 0),
(20129, 'koKR', 'Zniszczyć ich! Zniszczyć ich wszystkich!', '', 0),
(20139, 'koKR', 'Dobrze znów cię widzieć, przyjacielu.', '', 0),
(20434, 'koKR', 'Masz za mało reputacji u Widzących albo nie $gzłożyłeś:złożyłaś; im przysięgi wierności.', 'Masz za mało reputacji u Widzących albo nie $gzłożyłeś:złożyłaś; im przysięgi wierności.', 0),
(20459, 'koKR', 'Jestem wolny! Ale sekret... jest teraz zagrożony. Trzeba ostrzec Akamę!', '', 0),
(20498, 'koKR', 'Akamo, przyjacielu! Czy już wiesz? Poplecznicy Vash mnie zdemaskowali. Nasz sekret jest zagrożony!', '', 0),
(20499, 'koKR', 'Illidan mnie znajdzie, a gdy to zrobi... wydrze ze mnie sekret Popielnych Języków – taka jest moc Zdrajcy! Nie... Jest tylko jedno wyjście. Moja przydatność dla sprawy dobiegła końca. Muszę odejść do świata duchów!', '', 0),
(20500, 'koKR', 'Moja decyzja jest ostateczna. Nie dam się odwieść. Poświęciłem życie naszemu planowi. Narażenie go teraz byłoby zdradą wszystkich, którzy zginęli za sprawę na długo przede mną.', '', 0),
(20501, 'koKR', 'Dziękuję ci, Akamo. Zaszczycasz mnie, pozwalając mi przeżyć tę chwilę w otoczeniu moich braci. Żegnaj, przyjacielu. Prowadź dobrze nasz lud.', '', 0),
(20502, 'koKR', 'Illidan mnie szuka. Nie jestem tu bezpieczny... nikt z nas nie jest.', '', 0),
(20667, 'koKR', 'Za Xi\'riego! Za Sha\'tarów!', 'Za Xi\'riego! Za Sha\'tarów!', 0),
(20668, 'koKR', 'Twój koniec jest bliski, Illidari!', 'Twój koniec jest bliski, Illidari!', 0),
(20669, 'koKR', 'Pieski Illidana! Zniszczyć ich wszystkich!', 'Pieski Illidana! Zniszczyć ich wszystkich!', 0),
(20670, 'koKR', 'Podejdź bliżej, demonie! Czeka cię śmierć!', 'Podejdź bliżej, demonie! Czeka cię śmierć!', 0),
(20671, 'koKR', 'Żałosny robaku... dni twojego pana dobiegły końca!', 'Żałosny robaku... dni twojego pana dobiegły końca!', 0),
(20672, 'koKR', 'Mam wiadomość dla twojego pana, szumowino!', 'Mam wiadomość dla twojego pana, szumowino!', 0),
(20696, 'koKR', '', 'Naprzód, Widzący! Pokażcie sługusom Illidana hart naszej stali!', 0),
(20867, 'koKR', 'Akama. Twoja dwulicowość mnie nie dziwi. Powinienem był dawno temu wyrżnąć ciebie i twoich zniekształconych pobratymców.', '', 0),
(20868, 'koKR', 'Śmiałe słowa. Ale wciąż... nie jestem przekonany.', '', 0),
(20884, 'koKR', 'Nie jesteście gotowi!', '', 0),
(20941, 'koKR', 'Nie zbliżać się. Zostaniecie wyeliminowani.', '', 0),
(20942, 'koKR', 'Rozpoczynam zakłócenie tektoniczne.', '', 0),
(20943, 'koKR', 'Magnituda ustawiona. Zwalniam.', '', 0),
(20944, 'koKR', 'Trajektoria namierzona.', '', 0),
(20945, 'koKR', 'Włączam maksymalną prędkość.', '', 0),
(20946, 'koKR', 'Poziom zagrożenia: zero.', '', 0),
(20947, 'koKR', 'Dyrektywa wykonana.', '', 0),
(20948, 'koKR', 'Cel zlikwidowany.', '', 0),
(20949, 'koKR', 'Awaria systemu za pięć, c-z-t-e-r-y...', '', 0),
(20992, 'koKR', 'Czego ty chcieć? Dziwnie pachnieć jak na spaczony ork...', '', 0),
(20993, 'koKR', 'Ty nie robić tu swój dom. Może ty chcieć coś zjeść?', '', 0),
(20995, 'koKR', 'Ja chcieć, żeby Gug naprawić zbroja. Może ja coś kupić.', 'Ja chcieć, żeby Gug naprawić zbroja. Może ja coś kupić.', 0),
(20996, 'koKR', 'Czasem wpadają tu te przeklęte krwawe elfy i żądają jakiegoś niedorzecznego odczynnika albo trucizny. Muszę zawsze mieć pełne zapasy takich rzeczy, bo inaczej lord Illidan dowie się, że Smocze Paszcze nie współpracują...$B$B<Rumpus z trudem przełyka ślinę.>$B$BTego byśmy nie chcieli...', 'Czasem wpadają tu te przeklęte krwawe elfy i żądają jakiegoś niedorzecznego odczynnika albo trucizny. Muszę zawsze mieć pełne zapasy takich rzeczy, bo inaczej lord Illidan dowie się, że Smocze Paszcze nie współpracują...$B$B<Rumpus z trudem przełyka ślinę.>$B$BTego byśmy nie chcieli...', 0),
(20997, 'koKR', 'Co masz na sprzedaż, Rumpusie?', 'Co masz na sprzedaż, Rumpusie?', 0),
(21010, 'koKR', '$GBracie:Siostro;, od teraz łączy cię z Otchłanioskrzydłymi więź krwi. Wszyscy Otchłanioskrzydli staną za tobą! Nadszedł czas, by uderzyć w samo serce naszych wrogów, przyjacielu! Musimy odzyskać nasze utracone dziedzictwo.', '', 0),
(21061, 'koKR', 'Nie mam dla ciebie nic nowego, $gmłody:młoda;. $GWyrosłeś:Wyrosłaś; już z pracy fizycznej...', '', 0),
(21066, 'koKR', 'Oto moc... demona we mnie!', '', 0),
(21068, 'koKR', 'To wszystko, śmiertelnicy? Na tyle furii was stać?', '', 0),
(21069, 'koKR', 'Maiev... Jak to w ogóle możliwe?', '', 0),
(21118, 'koKR', 'Czas jeść!?', '', 0),
(21119, 'koKR', 'Mmmm! JEDZENIE!', '', 0),
(21120, 'koKR', 'Ja taki głodny! MNIAM!', '', 0),
(21121, 'koKR', 'To wkłada baraninę do brzucha!', '', 0),
(21122, 'koKR', 'Ej... ja się nie czuć dobrze.', '', 0),
(21123, 'koKR', 'Ty zły ork... złyyy... o... argh!', '', 0),
(21251, 'koKR', 'Chodźcie, moi słudzy. Potraktujcie tego zdrajcę, jak na to zasługuje!', '', 0),
(21252, 'koKR', 'Nie pozwolę, by tknęła mnie taka hołota jak wy!', '', 0),
(21275, 'koKR', 'Oto Płomienie Azzinotha!', '', 0),
(21290, 'koKR', 'Wyglądasz znajomo...', '', 0),
(21300, 'koKR', 'Kto... Kto ty być?? Czego ty chcieć?', '', 0),
(21302, 'koKR', 'Tak... Tak, my już iść... Proszę, nie bić nas...', '', 0),
(21321, 'koKR', '<Błotobryła poleruje buty.>', '', 0),
(21331, 'koKR', 'AUUUU! Dobra, dobra, ja wracać do roboty!', '', 0),
(21332, 'koKR', 'EJ! Już nie butorang! Ja przepraszać! Ja pracować!', '', 0),
(21333, 'koKR', 'UFF! Butorang mnie bolało! Ja myśleć, praca lepsza niż butorang!', '', 0),
(21334, 'koKR', 'CZEMU TO SMARUJE SKÓRĘ BUTORANGIEM?? CZEMU??', '', 0),
(21335, 'koKR', 'ARGH! BUTORANG!', '', 0),
(21336, 'koKR', 'AJAJAJ! Kiedyś ja mieć ten butorang...', '', 0),
(21346, 'koKR', 'Spadaj, zanim cię spiorę moim butorangiem.', '', 0),
(21362, 'koKR', 'Może i jestem stary, ale wciąż dam radę $gtakiemu młokosowi:takiej smarkuli; jak ty, $n. Postaraj się nie zostać w tyle...', '', 0),
(21363, 'koKR', 'No, $gwygrałeś:wygrałaś;... chyba.', '', 0),
(21418, 'koKR', 'Trope pokaże ci, jak latają Smocze Paszcze... Ty pokażesz Trope\'owi, jak umiera ciamajda.', '', 0),
(21419, 'koKR', '$GSpisałeś:Spisałaś; się. Trope jest naprawdę zaskoczony... Zgłoś się do Ja\'ya.', '', 0),
(21421, 'koKR', 'Miejmy to już z głowy...', '', 0),
(21422, 'koKR', '$GStoczyłeś:Stoczyłaś; piekielnie dobrą walkę, $gżółtodziobie:żółtodziobko;. Piekielnie dobrą...', '', 0),
(21423, 'koKR', 'Wracam do starej szkoły. Ja będę Przymierzem, a ty Wioską Mroźnych Wilków. BOMBY W DÓŁ!', '', 0),
(21424, 'koKR', 'Dzięki za to... Dostać taką lekcję – to uczy pokory.', '', 0),
(21425, 'koKR', 'Czeka cię ostra jazda, $n. Mam nadzieję, że już $gzałatwiłeś:załatwiłaś; sprawy pogrzebowe.', '', 0),
(21426, 'koKR', 'Jesteś $gnajlepszy:najlepsza; ze wszystkich, jakich widziałem. Nie wierzę, że to mówię, ale możesz mieć szansę z Kruszycielem Niebios. A jeśli nie pójdzie ci najlepiej, możesz zostać moim skrzydłowym...', '', 0),
(21429, 'koKR', 'MULVERICK!', '', 0),
(21430, 'koKR', 'Przygotujcie stos pogrzebowy! $n rzuca wyzwanie Kruszycielowi Niebios!', '', 0),
(21431, 'koKR', 'Jestem... pokonany... Nowym Orkiem nad Orkami jest $n!', '', 0),
(21432, 'koKR', 'Płaczę nad tobą, $n. Naprawdę nie masz pojęcia, w co się $gwpakowałeś:wpakowałaś;...', '', 0),
(21440, 'koKR', 'Znajdziesz tu mnóstwo roboty, $n.', '', 0),
(21452, 'koKR', '', 'Musimy znów wziąć te kopalnie w żelazny uścisk!', 0),
(21453, 'koKR', '<Nadzorca Mętnej Krwi chrząka.>', '', 0),
(21454, 'koKR', 'Przysłali cię, żebyś mnie $gzabił:zabiła;, co? Jakie to przewidywalne... Istoty rządzone strachem są wszystkie takie same.$B$BAle ty... Ty nie jesteś $gjednym:jedną; z nich...', '', 0),
(21455, 'koKR', '$GPrzyszedłem:Przyszłam; po ciebie, nadzorco.', '$GPrzyszedłem:Przyszłam; po ciebie, nadzorco.', 0),
(21456, 'koKR', 'Jak śmiesz podważać słowo nadzorcy Smoczych Paszcz!', 'Jak śmiesz podważać słowo nadzorcy Smoczych Paszcz!', 0),
(21457, 'koKR', 'Nadzorca?$B$BJesteś takim $gnadzorcą:nadzorczynią;, jak ja królem Wichrogrodu. Tak... To o tobie mówią.', '', 0),
(21458, 'koKR', 'Otchłanioskrzydli. Mówią do nas. Zaoferowali nam pokój i ochronę. Coś, czego Złamani nigdy tak naprawdę nie zaznali. Przyjęliśmy ich ofertę i pomogliśmy Toranaku rozbudzić stwory tej kopalni – wielkim kosztem dla nas samych. Wielu moich braci oddało życie w tej ofensywie. Próbowaliśmy uczynić kopalnię niezdatną do życia, by zmusić Smocze Paszcze do przeniesienia się, a w końcu do opuszczenia tej wyspy.', '', 0),
(21459, 'koKR', 'Kto o mnie mówi? O czym ty mówisz, Złamany?', 'Kto o mnie mówi? O czym ty mówisz, Złamany?', 0),
(21461, 'koKR', 'Smocze Paszcze są skorumpowane. Ogołacają tę wyspę ze wszystkich bogactw naturalnych i zaopatrują nimi armie Illidana z Czarnej Świątyni. Wiele jednak zatrzymują dla siebie, a to, co ukryli, sprzedają temu, kto da najwięcej.', '', 0),
(21462, 'koKR', 'Kim są ci kupcy?', 'Kim są ci kupcy?', 0),
(21463, 'koKR', 'Nie wiemy. Sądzimy, że zamieszane jest w to Czarne Stado, a także jakieś niezależne strony trzecie. Dlatego tu jesteś, $N. Rozwikłasz tę zagadkę od środka i przyniesiesz Otchłanioskrzydłym odkupienie.$B$BA teraz... Mogę tylko przypuszczać, że poprosiła cię, żebyś $gprzyniósł:przyniosła; jej moją dłoń.', '', 0),
(21464, 'koKR', 'No... tak.', 'No... tak.', 0),
(21465, 'koKR', 'Chętnie poniosę taką ofiarę, jeśli oznacza to upadek Smoczych Paszcz.', '', 0),
(21470, 'koKR', 'Muszę natychmiast opuścić to miejsce!', '', 0),
(21497, 'koKR', 'Spójrzcie w oczy Zdrajcy!', '', 0),
(21498, 'koKR', 'To zbyt łatwe!', '', 0),
(21499, 'koKR', 'Kto następny posmakuje moich ostrzy?', '', 0),
(21500, 'koKR', 'Nic nie wiecie o mocy!', '', 0),
(21501, 'koKR', 'Poczujcie nienawiść dziesięciu tysięcy lat!', '', 0),
(21506, 'koKR', 'Wygrałaś... Maiev. Ale łowczyni... jest niczym bez łowów. Ty... jesteś niczym... beze mnie.', '', 0),
(21632, 'koKR', 'Obrońcy, pokażcie tym kundlom furię Widzących!', '', 0),
(21633, 'koKR', 'Wyprostować się, żołnierze. Żadnej litości!', '', 0),
(21656, 'koKR', 'SPALIĆ TO!', '', 0),
(21663, 'koKR', 'Zwycięstwo Widzących! Smocze Paszcze zostały pokonane!', '', 0),
(21685, 'koKR', 'Smocze Paszcze trzeba powstrzymać...', '', 0),
(21728, 'koKR', 'Zwycięstwo Aldorów! Smocze Paszcze zostały pokonane!', '', 0),
(21804, 'koKR', 'Co to ma znaczyć, Mor\'ghorze?', '', 0),
(21808, 'koKR', 'Bełkoczący idioto. Ty niepojęcie nieudolny błaźnie...\n', '', 0),
(21809, 'koKR', 'TO jest twój bohater?', '', 0),
(21810, 'koKR', 'Oszukano cię, imbecylu.', '', 0),
(21811, 'koKR', 'Cała... ta... operacja... ZOSTAŁA SPALONA!', '', 0),
(21812, 'koKR', 'W ciągu godziny chcę zobaczyć w mojej siedzibie truchło tego insekta w kawałkach. Zawiedź, a spotka cię los o wiele gorszy od śmierci.', '', 0),
(21825, 'koKR', 'Nie skrzywdzisz $gchłopaka:dziewczyny;, Mor\'ghorze! Szybko, $n, wskakuj mi na grzbiet!', '', 0),
(21951, 'koKR', 'Smokowce to mój interes, $n. Mam pozwolenie, by sprzedawać je naszym najwyższym rangą oficerom.', '', 0),
(21952, 'koKR', '$GChciałbym:Chciałabym; kupić nowego smokowca.', '$GChciałbym:Chciałabym; kupić nowego smokowca.', 0),
(22036, 'koKR', 'Zmarnowaliście zbyt wiele czasu, śmiertelnicy. Teraz zginiecie.', '', 0),
(24137, 'koKR', 'Niesamowite, czego można się nauczyć od gnoma, jeśli dość mocno go przycisnąć: sprytnych sztuczek, jak się wykaraskać z opresji, jak piec pyszne ciasteczka, a nawet jak zbudować maszynę latającą.', '', 0),
(24149, 'koKR', '', 'Witaj, $N.$b$bDo roboty! Nie ma sensu czekać na zaopatrzenie, które może nigdy nie dotrzeć.$b$bPotrzebuję kowadła, żeby porządnie wyposażyć nasze wojska. W tej chwili jest ukończone w $3228w procentach.$b$bA gdy kowadło będzie gotowe, będę mogła wykuć dla ciebie o wiele więcej potężnych przedmiotów.', 0),
(24150, 'koKR', '', 'Witaj, $n.$b$bSkoro skończyłam budować kowadło, mogę zacząć wyposażać nasze wojska. To ważny krok, ale wciąż zostało wiele do zrobienia.$b$bCo ważniejsze dla ciebie, mogę teraz wykonać nowe rzeczy, które mogą cię zainteresować.', 0),
(25036, 'koKR', '%s odzyskuje przytomność.', '%s odzyskuje przytomność.', 0),
(27076, 'koKR', 'Tak?', '', 0),
(44668, 'koKR', 'Tak?', 'Tak?', 0),
(45305, 'koKR', 'Tak?', 'Tak?', 0);
